INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12675, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "为降低已有风险而采取方向相反的金融交易。", "primary_collocate": null, "pronunciation": "duì chōng", "ipa": "tuei˥˩ tʂʰʊŋ˥", "syllable_count": 2, "sentences": [{"text": "当极端气候频发导致主粮产区波动时，分布式的城市食品生产网络展现出显著的风险对冲能力，使地方政府将此类项目纳入关键基础设施的应急规划范畴。", "target_word": "对冲", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "公司用期货对冲价格上涨的风险。", "target_word": "对冲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "银行买了美元来对冲汇率风险。", "target_word": "对冲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想用期权对冲手里股票的风险。", "target_word": "对冲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农场主卖出期货，对冲粮价下跌的风险。", "target_word": "对冲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司没有对冲油价风险，亏了很多钱。", "target_word": "对冲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "投资者买入黄金，对冲股市下跌的风险。", "target_word": "对冲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "航空公司提前买油，对冲油价上涨。", "target_word": "对冲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们对冲了一部分外汇风险。", "target_word": "对冲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对冲可以减少投资的损失，但也要付费用。", "target_word": "对冲", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "对冲了", "label": "体标"}, {"form": "对冲过", "label": "体标"}, {"form": "对冲基金", "label": "复合"}, {"form": "對沖", "label": "繁体"}], "register": "书面", "sense_fingerprint": "金融上用方向相反的交易来抵消已有风险", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7495a4d-72ab-465f-85aa-3d63cd57a817') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12675, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "对冲", "is_correct": true, "explanation": "对冲：用方向相反的交易抵消已有风险，与句中“风险对冲能力”相符。"}, {"text": "集中", "is_correct": false, "explanation": "语义：“集中”与句中“分布式”的网络特点相反，风险集中不能体现分散应对的能力。"}, {"text": "赌博", "is_correct": false, "explanation": "语域：“赌博”口语色彩重，还带投机意味，与这句书面的风险管理语境不合。"}, {"text": "放大", "is_correct": false, "explanation": "搭配：“放大”一般不与“能力”组合，说“风险放大能力”不自然。"}], "explanations": {"对冲": "对冲：用方向相反的交易抵消已有风险，与句中“风险对冲能力”相符。", "集中": "语义：“集中”与句中“分布式”的网络特点相反，风险集中不能体现分散应对的能力。", "赌博": "语域：“赌博”口语色彩重，还带投机意味，与这句书面的风险管理语境不合。", "放大": "搭配：“放大”一般不与“能力”组合，说“风险放大能力”不自然。"}, "sentence_index": 0, "correct_answer": "对冲"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他想用房子对冲那笔贷款。", "explanation": "这里应该用〈抵押〉。对冲是用反向交易抵消风险，不用于给贷款提供保障。"}, {"text": "保险公司对冲了他的车祸损失。", "explanation": "这里应该用〈赔偿〉。对冲针对的是尚未发生的价格风险，不用于事后的赔付。"}, {"text": "妈妈用旧衣服对冲了家里的开销。", "explanation": "这里应该用〈节省〉。对冲是金融上的反向交易，不用于日常开支。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38ac4151-2c16-4845-9ced-8cd8f2dffe0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12675, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "对冲", "is_correct": true, "explanation": "对冲：用反向交易抵消股价下跌的风险，符合句意。"}, {"text": "加剧", "is_correct": false, "explanation": "语义：买入黄金的目的是减少风险，说“加剧”与句意相反。"}, {"text": "推迟", "is_correct": false, "explanation": "搭配：“推迟”不能与“风险”组合，说“推迟股市下跌的风险”不成立。"}, {"text": "纠正", "is_correct": false, "explanation": "搭配：“纠正”要接错误或偏差，不能说“纠正股市下跌的风险”。"}], "explanations": {"对冲": "对冲：用反向交易抵消股价下跌的风险，符合句意。", "加剧": "语义：买入黄金的目的是减少风险，说“加剧”与句意相反。", "推迟": "搭配：“推迟”不能与“风险”组合，说“推迟股市下跌的风险”不成立。", "纠正": "搭配：“纠正”要接错误或偏差，不能说“纠正股市下跌的风险”。"}, "sentence_index": 6, "correct_answer": "对冲"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用期权对冲了这次的责任。", "explanation": "这里应该用〈规避〉。对冲针对的是价格风险，不能用于法律上的责任。"}, {"text": "他用这笔交易对冲了利润。", "explanation": "这里应该用〈增加〉。对冲是抵消风险，不能用来增加利润。"}, {"text": "她对冲了朋友的感情。", "explanation": "这里应该用〈伤害〉。对冲是金融术语，只用于风险，不用于感情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38ac4151-2c16-4845-9ced-8cd8f2dffe0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12675, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们用期权对冲的了外汇风险。", "corrected_sentence": "他们用期权对冲了外汇风险。", "error_description": "“的”不能插在动词“对冲”与“了”之间，应说“对冲了外汇风险”，不说“对冲的了外汇风险”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38ac4151-2c16-4845-9ced-8cd8f2dffe0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12675, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "农户在期货市场卖空，对冲谷物跌价的了风险。", "corrected_sentence": "农户在期货市场卖空，对冲谷物跌价的风险。", "error_description": "“了”不能插在定语“谷物跌价的”与中心语“风险”之间；应说“对冲谷物跌价的风险”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38ac4151-2c16-4845-9ced-8cd8f2dffe0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
