INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12676, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "action", "definition": "指突然发生需要立即处理的事情或情况。", "primary_collocate": null, "pronunciation": "yìng jí", "ipa": "iŋ˥˩ tɕi˧˥", "syllable_count": 2, "sentences": [{"text": "当极端气候频发导致主粮产区波动时，分布式的城市食品生产网络展现出显著的风险对冲能力，使地方政府将此类项目纳入关键基础设施的应急规划范畴。", "target_word": "应急", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "医院设有应急室，专门接收突发的病人。", "target_word": "应急", "complexity_tier": "T3", "furigana": "yìng jí", "sentence_source": "generated"}, {"text": "学校每年都会组织一次应急演练。", "target_word": "应急", "complexity_tier": "T3", "furigana": "yìng jí", "sentence_source": "generated"}, {"text": "这只是应急的办法，不能用很久。", "target_word": "应急", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "应急情况发生后，大家要听从老师的安排。", "target_word": "应急", "complexity_tier": "T3", "furigana": "yìng jí", "sentence_source": "generated"}, {"text": "地震发生后，政府马上组织了应急救援。", "target_word": "应急", "complexity_tier": "T3", "furigana": "yìng jí", "sentence_source": "generated"}, {"text": "遇到应急情况，司机要立即停车并打开双闪。", "target_word": "应急", "complexity_tier": "T3", "furigana": "yìng jí", "sentence_source": "generated"}, {"text": "应急通道上不能停放车辆。", "target_word": "应急", "complexity_tier": "T3", "furigana": "yìng jí", "sentence_source": "generated"}, {"text": "这里的应急设备每月都要检查一次。", "target_word": "应急", "complexity_tier": "T3", "furigana": "yìng jí", "sentence_source": "generated"}, {"text": "水管突然坏了，我们只好应急处理一下。", "target_word": "应急", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "应急预案", "label": "复合"}, {"form": "應急", "label": "繁体"}], "register": "中性", "sense_fingerprint": "突然发生、需要立即处理的紧急情况", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7495a4d-72ab-465f-85aa-3d63cd57a817') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12676, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "应急", "is_correct": true, "explanation": "应急 yìngjí：突然发生、需要立即处理的情况，即正确答案。"}, {"text": "影集", "is_correct": false, "explanation": "影集 yǐngjí 与应急 yìngjí 第一个音节声调不同（第三声与第四声），意思是相册。"}, {"text": "应激", "is_correct": false, "explanation": "应激 yìngjī 与应急 yìngjí 第二个音节声调不同（第一声与第二声），意思是应激反应，是心理学术语。"}, {"text": "迎击", "is_correct": false, "explanation": "迎击 yíngjī 与应急 yìngjí 两个音节声调都不同，意思是迎面攻击。"}], "explanations": {"应急": "应急 yìngjí：突然发生、需要立即处理的情况，即正确答案。", "影集": "影集 yǐngjí 与应急 yìngjí 第一个音节声调不同（第三声与第四声），意思是相册。", "应激": "应激 yìngjī 与应急 yìngjí 第二个音节声调不同（第一声与第二声），意思是应激反应，是心理学术语。", "迎击": "迎击 yíngjī 与应急 yìngjí 两个音节声调都不同，意思是迎面攻击。"}, "sentence_index": null, "correct_answer": "应急"}, "level_3": {"options": [{"text": "应急", "is_correct": true, "explanation": "应急：突发情况下需要立即应对，修饰“规划”符合句意。"}, {"text": "豪华", "is_correct": false, "explanation": "搭配：“豪华”多修饰物品和生活，不能说“豪华规划范畴”。"}, {"text": "装饰", "is_correct": false, "explanation": "语义：关键基础设施讲求实用，说“装饰规划”与句意相悖。"}, {"text": "观赏", "is_correct": false, "explanation": "语义：“观赏”强调供人欣赏，与关键基础设施的应急规划不符。"}], "explanations": {"应急": "应急：突发情况下需要立即应对，修饰“规划”符合句意。", "豪华": "搭配：“豪华”多修饰物品和生活，不能说“豪华规划范畴”。", "装饰": "语义：关键基础设施讲求实用，说“装饰规划”与句意相悖。", "观赏": "语义：“观赏”强调供人欣赏，与关键基础设施的应急规划不符。"}, "sentence_index": 0, "correct_answer": "应急"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们找到了应急的办法，能彻底解决问题。", "explanation": "这里应该用〈根本〉。应急指临时应付，不能说它能彻底解决问题。"}, {"text": "学校每周一的应急是升国旗。", "explanation": "这里应该用〈例行〉。应急指突然发生、需要立即处理的情况，不指每周固定的例行活动，如升国旗。"}, {"text": "这份应急的合同已经签了三年。", "explanation": "这里应该用〈正式〉。应急指临时应对，不能用来形容正式的合同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38ac4151-2c16-4845-9ced-8cd8f2dffe0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12676, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "应急", "is_correct": true, "explanation": "应急 yìngjí：突然发生、需要立即处理的情况，即正确答案。"}, {"text": "性急", "is_correct": false, "explanation": "性急 xìngjí 与应急 yìngjí 声母不同（x 与 y），意思是急躁。"}, {"text": "应季", "is_correct": false, "explanation": "应季 yìngjì 与应急 yìngjí 第二个音节声调不同（第四声与第二声），意思是合乎季节。"}, {"text": "英籍", "is_correct": false, "explanation": "英籍 yīngjí 与应急 yìngjí 第一个音节声调不同（第一声与第四声），意思是英国国籍。"}], "explanations": {"应急": "应急 yìngjí：突然发生、需要立即处理的情况，即正确答案。", "性急": "性急 xìngjí 与应急 yìngjí 声母不同（x 与 y），意思是急躁。", "应季": "应季 yìngjì 与应急 yìngjí 第二个音节声调不同（第四声与第二声），意思是合乎季节。", "英籍": "英籍 yīngjí 与应急 yìngjí 第一个音节声调不同（第一声与第四声），意思是英国国籍。"}, "sentence_index": null, "correct_answer": "应急"}, "level_3": {"options": [{"text": "应急", "is_correct": true, "explanation": "应急：突然发生的情况需要立即处理，与后半句“立即停车”相呼应。"}, {"text": "平常", "is_correct": false, "explanation": "语义：“平常”指寻常时候，与后面“立即停车、打开双闪”的应对相矛盾。"}, {"text": "例行", "is_correct": false, "explanation": "搭配：“例行”多用于检查、工作，不说“遇到例行情况”。"}, {"text": "惯常", "is_correct": false, "explanation": "语域：“惯常”带书面或文言色彩，与这句口语化的提示不合。"}], "explanations": {"应急": "应急：突然发生的情况需要立即处理，与后半句“立即停车”相呼应。", "平常": "语义：“平常”指寻常时候，与后面“立即停车、打开双闪”的应对相矛盾。", "例行": "搭配：“例行”多用于检查、工作，不说“遇到例行情况”。", "惯常": "语域：“惯常”带书面或文言色彩，与这句口语化的提示不合。"}, "sentence_index": 6, "correct_answer": "应急"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们每天都应急维护设备。", "explanation": "这里应该用〈日常〉。应急指突发时的处理，不能说每天都应急维护。"}, {"text": "这里的设备每个月都要应急检修一次。", "explanation": "这里应该用〈定期〉。应急是突发时的应对，不能说每个月都应急检修。"}, {"text": "这家店一直应急营业。", "explanation": "这里应该用〈正常〉。应急指临时应对，不能说一直应急营业。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38ac4151-2c16-4845-9ced-8cd8f2dffe0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12676, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "昨晚学校发生了一只应急，大家连夜处理。", "corrected_sentence": "昨晚学校发生了一次应急，大家连夜处理。", "error_description": "“应急”指突然发生的事情，是可数名词，量词应用“次”，说“一次应急”，不说“一只应急”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38ac4151-2c16-4845-9ced-8cd8f2dffe0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12676, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校买了一套应急了设备。", "corrected_sentence": "学校买了一套应急设备。", "error_description": "“应急”是定语，修饰“设备”，中间不能插入“了”；应说“应急设备”，不说“应急了设备”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38ac4151-2c16-4845-9ced-8cd8f2dffe0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
