INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12678, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "function", "definition": "指事物或方法能发挥的功能、作用。", "primary_collocate": null, "pronunciation": "yòng tú", "ipa": "jʊŋ˥˩ tʰu˧˥", "syllable_count": 2, "sentences": [{"text": "这个工具的用途很多。", "target_word": "用途", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你知道这个小盒子的用途吗？", "target_word": "用途", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "手机有很多用途，不只是打电话。", "target_word": "用途", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种材料的用途很广。", "target_word": "用途", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "说明书上写着这台机器的用途。", "target_word": "用途", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这把刀的用途是切水果。", "target_word": "用途", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "塑料的用途越来越多了。", "target_word": "用途", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师给我们介绍了这种植物的用途。", "target_word": "用途", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个房间的用途是做书房。", "target_word": "用途", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种纸有一个特别的用途。", "target_word": "用途", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "多用途", "label": "复合"}], "register": "中性", "sense_fingerprint": "事物或方法能发挥的功能、作用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed3899f7-a8ab-4ea9-a0cc-9b78a256761b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12678, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "用途", "is_correct": true, "explanation": "正确：用途指事物能发挥的作用，「用途很多」是常见说法。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格说高低，不说多少，「价格很多」不通。"}, {"text": "体积", "is_correct": false, "explanation": "搭配：「体积」说大小，不和「很多」搭配。"}, {"text": "寿命", "is_correct": false, "explanation": "搭配：「寿命」说长短，不说「很多」。"}], "explanations": {"用途": "正确：用途指事物能发挥的作用，「用途很多」是常见说法。", "价格": "语义：价格说高低，不说多少，「价格很多」不通。", "体积": "搭配：「体积」说大小，不和「很多」搭配。", "寿命": "搭配：「寿命」说长短，不说「很多」。"}, "sentence_index": 0, "correct_answer": "用途"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个按钮的用途是按三秒。", "explanation": "这里应该用〈用法〉。用途指东西能做什么，具体怎样操作要说用法。"}, {"text": "这个学生的用途很大。", "explanation": "这里应该用〈能力〉。用途指事物能发挥的作用，形容人的本领要说能力。"}, {"text": "我学习汉语的用途是提高水平。", "explanation": "这里应该用〈目的〉。用途指事物能发挥的作用，人做事的意图要说目的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cacff6a-84f4-4112-8d18-cb2b789ffae8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12678, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "用途", "is_correct": true, "explanation": "正确：「塑料的用途越来越多」指塑料能用来做的事情变多了。"}, {"text": "硬度", "is_correct": false, "explanation": "语义：硬度说的是坚硬程度，不是数量，不能说「越来越多」。"}, {"text": "温度", "is_correct": false, "explanation": "搭配：「温度」说高低，不说多少，「温度越来越多」不通。"}, {"text": "亮度", "is_correct": false, "explanation": "搭配：「亮度」说明暗强弱，不说「越来越多」。"}], "explanations": {"用途": "正确：「塑料的用途越来越多」指塑料能用来做的事情变多了。", "硬度": "语义：硬度说的是坚硬程度，不是数量，不能说「越来越多」。", "温度": "搭配：「温度」说高低，不说多少，「温度越来越多」不通。", "亮度": "搭配：「亮度」说明暗强弱，不说「越来越多」。"}, "sentence_index": 6, "correct_answer": "用途"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这些工具派上了用途。", "explanation": "这里应该用〈用场〉。「派上用场」是固定说法，不说「派上用途」。"}, {"text": "这次旅行的用途很大。", "explanation": "这里应该用〈收获〉。收获指做事后得到的好处，旅行不是东西，不说用途。"}, {"text": "做这件事的用途是一个小时。", "explanation": "这里应该用〈用时〉。用途指事物能发挥的作用，做事花费的时间要说用时。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cacff6a-84f4-4112-8d18-cb2b789ffae8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12678, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台机器的主要用途打印文件。", "corrected_sentence": "这台机器的主要用途是打印文件。", "error_description": "错误：「用途」后缺少引出说明的「是」，直接接动词短语不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cacff6a-84f4-4112-8d18-cb2b789ffae8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12678, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台相机是两种用途。", "corrected_sentence": "这台相机有两种用途。", "error_description": "错误：「有」不能换成「是」。表示事物有几种作用，要说「有……用途」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cacff6a-84f4-4112-8d18-cb2b789ffae8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
