INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12679, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "开采、开垦或利用自然资源；也指研制新产品、建设新项目。", "primary_collocate": null, "pronunciation": "kāi fā", "ipa": "kʰai˥ fa˥", "syllable_count": 2, "sentences": [{"text": "这个地区开发了丰富的矿产资源。", "target_word": "开发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府计划开发西部的荒地。", "target_word": "开发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座岛上的旅游资源还没有开发。", "target_word": "开发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司开发出一种新的洗衣机。", "target_word": "开发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水电站开发了这条河的水力资源。", "target_word": "开发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们打算在海边开发一个旅游项目。", "target_word": "开发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂正在开发一种环保材料。", "target_word": "开发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "当地人利用太阳能开发新能源。", "target_word": "开发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这片土地开发以后，种上了很多茶树。", "target_word": "开发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国西部有很多资源等着人们去开发。", "target_word": "开发", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "开发了", "label": "体标"}, {"form": "开发过", "label": "体标"}, {"form": "开发着", "label": "体标"}, {"form": "开发者", "label": "复合"}, {"form": "開發", "label": "繁体"}], "register": "中性", "sense_fingerprint": "开发：开采、开垦、利用资源，或研制新产品、建设新项目", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2f4ca28-5514-4bef-9e2b-fe5bad49018c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12679, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "开发", "is_correct": true, "explanation": "正确答案：开发（kāi fā），指开采、利用资源或研制新产品。"}, {"text": "开放", "is_correct": false, "explanation": "fàng 与 fā 韵母不同（fàng 带 -ng），声调也不同，意思是开放。"}, {"text": "开方", "is_correct": false, "explanation": "fāng 与 fā 只多了韵尾 -ng，声调相同，意思是开方（数学运算）。"}, {"text": "开花", "is_correct": false, "explanation": "huā 与 fā 声母不同（h 与 f），声调相同，意思是开花。"}, {"text": "开伐", "is_correct": false, "explanation": "fá（第二声）与 fā（第一声）声调不同，意思是砍伐树木。"}], "explanations": {"开发": "正确答案：开发（kāi fā），指开采、利用资源或研制新产品。", "开放": "fàng 与 fā 韵母不同（fàng 带 -ng），声调也不同，意思是开放。", "开方": "fāng 与 fā 只多了韵尾 -ng，声调相同，意思是开方（数学运算）。", "开花": "huā 与 fā 声母不同（h 与 f），声调相同，意思是开花。", "开伐": "fá（第二声）与 fā（第一声）声调不同，意思是砍伐树木。"}, "sentence_index": null, "correct_answer": "开发"}, "level_3": {"options": [{"text": "开发", "is_correct": true, "explanation": "正确：“开发”指开采利用矿产资源，与“矿产资源”搭配，符合句意。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指进食，不能说吃矿产资源。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指发出歌声，与开采矿产无关。"}, {"text": "咳嗽", "is_correct": false, "explanation": "配价：“咳嗽”是不及物动词，不能带“矿产资源”作宾语。"}], "explanations": {"开发": "正确：“开发”指开采利用矿产资源，与“矿产资源”搭配，符合句意。", "吃": "语义：“吃”指进食，不能说吃矿产资源。", "唱": "语义：“唱”指发出歌声，与开采矿产无关。", "咳嗽": "配价：“咳嗽”是不及物动词，不能带“矿产资源”作宾语。"}, "sentence_index": 0, "correct_answer": "开发"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工厂每天开发上万个零件。", "explanation": "这里应该用〈生产〉。开发指研制新产品或开采资源，大批量制造零件要用生产。"}, {"text": "农民今年开发了一亩小麦。", "explanation": "这里应该用〈种〉。开发不用于种植作物，种小麦要用种。"}, {"text": "他开发了两只鸡。", "explanation": "这里应该用〈养〉。开发不用于饲养动物，养鸡要用养。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616df0a4-4e7c-4a38-ac2d-cd61070b6e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12679, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "开发", "is_correct": true, "explanation": "正确：“开发”指研制新材料，与“环保材料”搭配，符合句意。"}, {"text": "熬", "is_correct": false, "explanation": "语义：“熬”指用文火煮，不能用于制造材料。"}, {"text": "融化", "is_correct": false, "explanation": "语义：“融化”指固体受热变成液体，与“研制一种环保材料”的意思不同。"}, {"text": "睡", "is_correct": false, "explanation": "语义：“睡”指睡觉，与研制材料无关。"}], "explanations": {"开发": "正确：“开发”指研制新材料，与“环保材料”搭配，符合句意。", "熬": "语义：“熬”指用文火煮，不能用于制造材料。", "融化": "语义：“融化”指固体受热变成液体，与“研制一种环保材料”的意思不同。", "睡": "语义：“睡”指睡觉，与研制材料无关。"}, "sentence_index": 6, "correct_answer": "开发"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈开发了一双毛线袜子。", "explanation": "这里应该用〈织〉。开发指研制新产品或开采资源，手工织袜子要用织。"}, {"text": "她用彩纸开发了一只纸鹤。", "explanation": "这句话用的是“做出来”的意思，指手工制作，不是本词“开采资源、研制产品”的意思。"}, {"text": "哥哥开发了一碗热腾腾的面条。", "explanation": "这句话用的是“做出来”的意思，指做饭，不是本词“开采资源、研制产品”的意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616df0a4-4e7c-4a38-ac2d-cd61070b6e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12679, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "政府决定开发了这片沙漠。", "corrected_sentence": "政府决定开发这片沙漠。", "error_description": "错误：“决定”后的动作尚未发生，不能加表示完成的“了”。应删去“了”，说“政府决定开发这片沙漠。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616df0a4-4e7c-4a38-ac2d-cd61070b6e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12679, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们把这块荒地开发了成农场。", "corrected_sentence": "我们把这块荒地开发成了农场。", "error_description": "错误：结果补语“成”应紧接动词，“了”应放在补语之后。“开发了成农场”应改为“开发成了农场”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616df0a4-4e7c-4a38-ac2d-cd61070b6e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
