INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12683, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "租用他人房屋或物品的人。", "primary_collocate": null, "pronunciation": "zū hù", "ipa": "tsu˥ xu˥˩", "syllable_count": 2, "sentences": [{"text": "土地用途的混合开发（mixed-use development）正被重新定义：商业综合体整合垂直农场不再仅是企业社会责任的展示，而成为吸引高端租户、提升品牌粘性的商业策略。", "target_word": "租户", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "他是我的租户。", "target_word": "租户", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "租户要付房租。", "target_word": "租户", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "房东对租户很客气。", "target_word": "租户", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "商店的租户每月交一次钱。", "target_word": "租户", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新来的租户搬进了三楼。", "target_word": "租户", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这栋楼的租户大多是年轻的上班族。", "target_word": "租户", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "租户和房东签了一份两年的合同。", "target_word": "租户", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有几位租户反映楼道的灯坏了很久。", "target_word": "租户", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "租户搬走前要把房间打扫干净。", "target_word": "租户", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "个", "label": "量词"}, {"form": "租户们", "label": "复数"}, {"form": "租戶", "label": "繁体"}], "register": "中性", "sense_fingerprint": "租户：租用别人的房屋、店铺或物品的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed3899f7-a8ab-4ea9-a0cc-9b78a256761b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12683, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "租户", "is_correct": true, "explanation": "正确：「租户」指租用房屋的人，与商业综合体招揽承租方的语境相符。"}, {"text": "房东", "is_correct": false, "explanation": "语义：房东是出租房屋的人，不会被「吸引」来承租，与句意矛盾。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：「吸引」的对象是人或注意力，不能说「吸引高端空气」。"}, {"text": "动物", "is_correct": false, "explanation": "语义：动物不是商业综合体的承租方，句子无法成立。"}], "explanations": {"租户": "正确：「租户」指租用房屋的人，与商业综合体招揽承租方的语境相符。", "房东": "语义：房东是出租房屋的人，不会被「吸引」来承租，与句意矛盾。", "空气": "搭配：「吸引」的对象是人或注意力，不能说「吸引高端空气」。", "动物": "语义：动物不是商业综合体的承租方，句子无法成立。"}, "sentence_index": 0, "correct_answer": "租户"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "租户每个月都来收房租。", "explanation": "这里应该用〈房东〉。租户是租房子住的人，要交房租；收房租的是房东，两者角色正好相反。"}, {"text": "公司的租户每个月按时领工资。", "explanation": "这里应该用〈员工〉。租户指租用房屋或物品的人，领工资的是员工。"}, {"text": "租户负责小区的保安、保洁和绿化。", "explanation": "这里应该用〈物业〉。负责保安、保洁和绿化的是物业公司；租户只是承租房屋的人，不管理小区。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cacff6a-84f4-4112-8d18-cb2b789ffae8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12683, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "租户", "is_correct": true, "explanation": "正确：「租户」指租房屋住的人，与这栋楼的住户相符。"}, {"text": "学生", "is_correct": false, "explanation": "语义：学生是在校学习的人，不是上班族，与句意矛盾。"}, {"text": "农民", "is_correct": false, "explanation": "语义：农民以种地为业，与这栋楼里年轻的上班族矛盾。"}, {"text": "老人", "is_correct": false, "explanation": "语义：老人与「年轻的上班族」矛盾，句意不通。"}], "explanations": {"租户": "正确：「租户」指租房屋住的人，与这栋楼的住户相符。", "学生": "语义：学生是在校学习的人，不是上班族，与句意矛盾。", "农民": "语义：农民以种地为业，与这栋楼里年轻的上班族矛盾。", "老人": "语义：老人与「年轻的上班族」矛盾，句意不通。"}, "sentence_index": 6, "correct_answer": "租户"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "租户每成交一套房子都能拿到佣金。", "explanation": "这里应该用〈中介〉。佣金是促成交易的人拿的，租户只是承租房屋的人，不会有这种收入。"}, {"text": "租户有权决定小区的改建方案。", "explanation": "这里应该用〈业主〉。改建方案由房屋所有者决定，租户只是承租人，无权决定。"}, {"text": "租户负责建造这个小区。", "explanation": "这里应该用〈房产商〉。建造小区的是房产商，租户只是承租房屋的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cacff6a-84f4-4112-8d18-cb2b789ffae8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12683, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我租户这套房子。", "corrected_sentence": "我租了这套房子。", "error_description": "词性错误：「租户」是名词，不能表示“租用”这个动作。动词应说「租」，动作完成要加「了」，应说「我租了这套房子」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cacff6a-84f4-4112-8d18-cb2b789ffae8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12683, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那栋楼里有三位租户们。", "corrected_sentence": "那栋楼里有三位租户。", "error_description": "复数错误：「三位」已表示数量，「租户们」的「们」不能再与数词同用，应去掉「们」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cacff6a-84f4-4112-8d18-cb2b789ffae8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12685, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cacff6a-84f4-4112-8d18-cb2b789ffae8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12685, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cacff6a-84f4-4112-8d18-cb2b789ffae8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12685, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "指物体表面之间的附着或结合的特性，形容事物具有不易脱离或改变的性质。", "primary_collocate": null, "pronunciation": "nián xìng", "ipa": "njɛn˧˥ ɕiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "土地用途的混合开发（mixed-use development）正被重新定义：商业综合体整合垂直农场不再仅是企业社会责任的展示，而成为吸引高端租户、提升品牌粘性的商业策略。", "target_word": "粘性", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这种胶水粘性很强。", "target_word": "粘性", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "蜂蜜的粘性很大。", "target_word": "粘性", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "泥土潮湿时粘性更大。", "target_word": "粘性", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "用久了，胶带的粘性变小了。", "target_word": "粘性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个软件的用户粘性很高。", "target_word": "粘性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "好的内容能增强读者对网站的粘性。", "target_word": "粘性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种双面胶粘性很强，一贴上去就不容易掉。", "target_word": "粘性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店靠会员活动提高顾客的粘性，让人常常回来。", "target_word": "粘性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种新胶带粘性很好，贴过的墙也不会留下痕迹。", "target_word": "粘性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "黏性", "label": "异形词"}, {"form": "用户粘性", "label": "复合"}], "register": "中性", "sense_fingerprint": "粘性：物体能粘住别的东西的特性，也指用户、顾客不易离开的程度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed3899f7-a8ab-4ea9-a0cc-9b78a256761b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12685, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "粘性", "is_correct": true, "explanation": "正确：「粘性」可以被提升，指用户或品牌不易离开的程度，与句意相符。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：「提升」用于水平、质量，不用于颜色。"}, {"text": "体重", "is_correct": false, "explanation": "语义：品牌没有体重，句意不通。"}, {"text": "味道", "is_correct": false, "explanation": "语义：品牌没有味道，不能用来提升。"}], "explanations": {"粘性": "正确：「粘性」可以被提升，指用户或品牌不易离开的程度，与句意相符。", "颜色": "搭配：「提升」用于水平、质量，不用于颜色。", "体重": "语义：品牌没有体重，句意不通。", "味道": "语义：品牌没有味道，不能用来提升。"}, "sentence_index": 0, "correct_answer": "粘性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "橡皮筋拉长以后能恢复原状，说明它的粘性很好。", "explanation": "这里应该用〈弹性〉。恢复原状靠的是弹性，粘性指粘住别的东西的特性。"}, {"text": "这块木头的粘性很大，放进水里会下沉。", "explanation": "这里应该用〈密度〉。木头下沉由密度决定，粘性说的是粘住别的东西的特性。"}, {"text": "这块钢板的粘性很高，不容易变形。", "explanation": "这里应该用〈硬度〉。不易变形说明硬度高，粘性与变形无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cacff6a-84f4-4112-8d18-cb2b789ffae8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12685, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "粘性", "is_correct": true, "explanation": "正确：「粘性」指用户不易离开的程度，与「读者对网站」的语境相符。"}, {"text": "体重", "is_correct": false, "explanation": "语义：网站没有体重，句意不通。"}, {"text": "硬度", "is_correct": false, "explanation": "语义：内容的硬度与读者留存无关，句意不通。"}, {"text": "亮度", "is_correct": false, "explanation": "搭配：「增强」用于能力、感情等，不说「增强对网站的亮度」。"}], "explanations": {"粘性": "正确：「粘性」指用户不易离开的程度，与「读者对网站」的语境相符。", "体重": "语义：网站没有体重，句意不通。", "硬度": "语义：内容的硬度与读者留存无关，句意不通。", "亮度": "搭配：「增强」用于能力、感情等，不说「增强对网站的亮度」。"}, "sentence_index": 6, "correct_answer": "粘性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块玻璃的粘性很高，能看清楚外面。", "explanation": "这里应该用〈透明度〉。能看清楚外面靠的是透明度，粘性指粘住别的东西的特性。"}, {"text": "这种锅的粘性很好，加热不会坏。", "explanation": "这里应该用〈耐热性〉。加热不坏说明耐热，粘性与耐热无关。"}, {"text": "这块布料的粘性很好，穿着很舒服。", "explanation": "这里应该用〈柔软〉。穿着舒服靠的是柔软，粘性指粘住别的东西的特性，与布料手感无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cacff6a-84f4-4112-8d18-cb2b789ffae8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12685, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种漆粘性很，墙面不容易脱落。", "corrected_sentence": "这种漆粘性很强，墙面不容易脱落。", "error_description": "错误的形式是「粘性很」，正确的形式是「粘性很强」。「很」是程度副词，后面必须接形容词作谓语，这里漏掉了「强」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cacff6a-84f4-4112-8d18-cb2b789ffae8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12685, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种薄膜的粘性得很强，贴上去不容易掉。", "corrected_sentence": "这种薄膜的粘性很强，贴上去不容易掉。", "error_description": "助词错误：「粘性」与「很」之间不能插入「得」。「得」用于动词或形容词之后作补语，这里应说「粘性很强」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cacff6a-84f4-4112-8d18-cb2b789ffae8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
