INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12692, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指按照一定的计划、设计，进行建造和安装的工程或项目。", "primary_collocate": null, "pronunciation": "jiàn shè xiàng mù", "ipa": "tɕjɛn˥˩ ʂɤ˥˩ ɕjɑŋ˥˩ mu˥˩", "syllable_count": 4, "sentences": [{"text": "政府通过容积率奖励、税收减免等政策工具，引导私人投资流向具备生态服务功能的建设项目，从而降低公共财政在污水处理、热岛缓解与空气治理方面的长期支出。", "target_word": "建设项目", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "这个建设项目需要三年时间。", "target_word": "建设项目", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市里新批了五个建设项目。", "target_word": "建设项目", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "建设项目开工前要先做计划。", "target_word": "建设项目", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这项建设项目由政府负责。", "target_word": "建设项目", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们正在建设项目的工地上工作。", "target_word": "建设项目", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司想参加这个建设项目的投标。", "target_word": "建设项目", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他负责管理一个大型建设项目。", "target_word": "建设项目", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "建设项目完成后，城市会更漂亮。", "target_word": "建设项目", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些建设项目给当地带来了很多工作。", "target_word": "建设项目", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "项", "label": "量词"}, {"form": "大型建设项目", "label": "复合"}], "register": "书面", "sense_fingerprint": "按计划和设计进行建造安装的工程项目", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe62ec7c-1fbe-4610-b818-ca81f031db29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12692, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "建设项目", "is_correct": true, "explanation": "符合句意：政府引导投资流向的是按计划建造的工程项目，具备生态服务功能。"}, {"text": "公务员", "is_correct": false, "explanation": "语义：“具备生态服务功能”说的是工程或场地，公务员是人，不能成为投资流向的这类对象。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：歌曲不具备生态服务功能，与句中污水处理、空气治理等公共支出无关。"}, {"text": "学生", "is_correct": false, "explanation": "配价：“流向”的对象应是可以接受投资的工程，学生不能作为这类投资的承接对象。"}], "explanations": {"建设项目": "符合句意：政府引导投资流向的是按计划建造的工程项目，具备生态服务功能。", "公务员": "语义：“具备生态服务功能”说的是工程或场地，公务员是人，不能成为投资流向的这类对象。", "歌曲": "语义：歌曲不具备生态服务功能，与句中污水处理、空气治理等公共支出无关。", "学生": "配价：“流向”的对象应是可以接受投资的工程，学生不能作为这类投资的承接对象。"}, "sentence_index": 0, "correct_answer": "建设项目"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "周末社区组织了一个建设项目，大家一起聊天、吃饭。", "explanation": "这里应该用〈活动〉。建设项目指按计划建造的工程，不能用来指聚会类的活动。"}, {"text": "公司接了一只建设项目。", "explanation": "量词错误：建设项目应该用“个”或“项”，“只”用于动物等，不能用来数建设项目。"}, {"text": "我每天的建设项目是打扫办公室。", "explanation": "这里应该用〈工作〉。建设项目指按计划建造的工程，不是日常的职业工作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f1a95c44-654d-4cc2-8202-05027c378cc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12692, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "建设项目", "is_correct": true, "explanation": "符合句意：公司想参加的是一个工程项目的投标。"}, {"text": "比赛", "is_correct": false, "explanation": "搭配：“投标”针对工程、采购等标的，不能用于比赛。"}, {"text": "教材", "is_correct": false, "explanation": "搭配：“投标”的对象是工程或采购项目，教材不能作为投标标的。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不是可以招标投标的对象，与句意不符。"}], "explanations": {"建设项目": "符合句意：公司想参加的是一个工程项目的投标。", "比赛": "搭配：“投标”针对工程、采购等标的，不能用于比赛。", "教材": "搭配：“投标”的对象是工程或采购项目，教材不能作为投标标的。", "天空": "语义：天空不是可以招标投标的对象，与句意不符。"}, "sentence_index": 6, "correct_answer": "建设项目"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的建设项目是研究古代的瓷器。", "explanation": "这里应该用〈课题〉。建设项目指按计划建造的工程，不指学术研究的课题。"}, {"text": "妈妈最拿手的建设项目是红烧肉。", "explanation": "这里应该用〈菜〉。建设项目指按计划建造的工程，不能指做好的饭菜。"}, {"text": "这学期的建设项目是学习英语。", "explanation": "这里应该用〈课程〉。建设项目指工程，不能指学习的课程。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f1a95c44-654d-4cc2-8202-05027c378cc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12692, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这本建设项目预计明年完工。", "corrected_sentence": "这个建设项目预计明年完工。", "error_description": "量词错误：建设项目应用“个”或“项”，“本”用于书籍，不能用来数建设项目。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f1a95c44-654d-4cc2-8202-05027c378cc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12692, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这把建设项目由银行出资。", "corrected_sentence": "这个建设项目由银行出资。", "error_description": "量词错误：建设项目应用“个”或“项”，“把”用于有柄的器具，不能用来数建设项目。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f1a95c44-654d-4cc2-8202-05027c378cc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
