INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12694, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "action", "definition": "通过物理、化学或生物方法去除废水中的有害物质，使其达到排放或再利用标准。", "primary_collocate": null, "pronunciation": "wū shuǐ chǔ lǐ", "ipa": "u˥ ʂueɪ˨˩˦ ʈʂʰu˨˩˦ li˨˩˦", "syllable_count": 4, "sentences": [{"text": "政府通过容积率奖励、税收减免等政策工具，引导私人投资流向具备生态服务功能的建设项目，从而降低公共财政在污水处理、热岛缓解与空气治理方面的长期支出。", "target_word": "污水处理", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "污水处理需要很多钱和技术。", "target_word": "污水处理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工厂的水必须先经过污水处理，才能排进河里。", "target_word": "污水处理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "污水处理能去掉水里的有害物质。", "target_word": "污水处理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "污水处理做得好，河水就会变干净。", "target_word": "污水处理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个城市的污水处理已经达到了国家标准。", "target_word": "污水处理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "处理后的水可以再利用，这就是污水处理的目的。", "target_word": "污水处理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农村的污水处理还比较落后。", "target_word": "污水处理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在工厂负责污水处理。", "target_word": "污水处理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "污水处理中，细菌可以分解水里的脏东西。", "target_word": "污水处理", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "污水处理厂", "label": "复合"}, {"form": "污水处理系统", "label": "复合"}], "register": "书面", "sense_fingerprint": "污水处理：去除废水中的有害物质，使水达标排放或再利用的过程", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'afe32d86-09dd-4bdf-8957-2d763f51e2dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12694, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "文艺演出", "is_correct": false, "explanation": "语义：文艺演出属于文化活动，不是生态服务项目，与热岛缓解、空气治理并列不通。"}, {"text": "污水处理", "is_correct": true, "explanation": "污水处理指净化废水的过程，与热岛缓解、空气治理并列，属于生态治理方面的支出。"}, {"text": "体育赛事", "is_correct": false, "explanation": "语义：体育赛事与生态治理无关，与上文讲的建设项目方向不符。"}, {"text": "校园食堂", "is_correct": false, "explanation": "搭配：“校园食堂”不能与“热岛缓解与空气治理”并列，作为生态方面的长期支出说不通。"}], "explanations": {"文艺演出": "语义：文艺演出属于文化活动，不是生态服务项目，与热岛缓解、空气治理并列不通。", "污水处理": "污水处理指净化废水的过程，与热岛缓解、空气治理并列，属于生态治理方面的支出。", "体育赛事": "语义：体育赛事与生态治理无关，与上文讲的建设项目方向不符。", "校园食堂": "搭配：“校园食堂”不能与“热岛缓解与空气治理”并列，作为生态方面的长期支出说不通。"}, "sentence_index": 0, "correct_answer": "污水处理"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座城市有一只污水处理。", "explanation": "这里的量词错了。“只”用于小动物或成对的物件，污水处理是一项工艺，应该用〈套〉，说“一套污水处理”。"}, {"text": "他是一名污水处理，每天在河边工作。", "explanation": "这里指人，应该用〈污水处理员〉。污水处理指净化废水的过程，不指人。"}, {"text": "这家餐厅的特色菜用的是污水处理。", "explanation": "这里应该用〈食材〉之类的食物。污水处理指废水的净化过程，不能当作食物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b669a4a-1005-455a-b931-f13f08555612') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12694, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "交通管理", "is_correct": false, "explanation": "语义：“交通管理”与“处理后的水可以再利用”无关，不能作“目的”的对象。"}, {"text": "污水处理", "is_correct": true, "explanation": "污水处理的目的是让废水净化后可以再利用，与上文完全吻合。"}, {"text": "文化传播", "is_correct": false, "explanation": "语义：“文化传播”与再利用处理后的水无关，这样说没有意义。"}, {"text": "电力供应", "is_correct": false, "explanation": "搭配：“电力供应”不是对水的处理，不能说成“再利用的水”的目的。"}], "explanations": {"交通管理": "语义：“交通管理”与“处理后的水可以再利用”无关，不能作“目的”的对象。", "污水处理": "污水处理的目的是让废水净化后可以再利用，与上文完全吻合。", "文化传播": "语义：“文化传播”与再利用处理后的水无关，这样说没有意义。", "电力供应": "搭配：“电力供应”不是对水的处理，不能说成“再利用的水”的目的。"}, "sentence_index": 6, "correct_answer": "污水处理"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天都喝污水处理。", "explanation": "这里应该用〈净水〉。净水可以饮用，污水处理是废水的净化过程，不能拿来喝。"}, {"text": "他每天用污水处理洗手。", "explanation": "这里应该用〈清水〉。清水可以洗手，污水处理是工艺，不是可以直接用来洗手的水。"}, {"text": "农民每天用污水处理浇菜。", "explanation": "这里应该用〈灌溉水〉。污水处理指废水的净化过程，不是用来浇灌庄稼的水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b669a4a-1005-455a-b931-f13f08555612') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12694, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个城市的污水处理了很大进步。", "corrected_sentence": "这个城市的污水处理有了很大进步。", "error_description": "错误在于漏掉动词“有”。“有了……进步”是固定格式，应说“污水处理有了很大进步”；直接说“污水处理了很大进步”不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b669a4a-1005-455a-b931-f13f08555612') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12694, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个园区的污水处理被专业公司负责。", "corrected_sentence": "这个园区的污水处理由专业公司负责。", "error_description": "错误在于“被”。“负责”一般不用于“被”字句，不能说“被……负责”；这里应该用“由”，说“由专业公司负责”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b669a4a-1005-455a-b931-f13f08555612') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
