INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12696, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指事物或问题的某一个局部或侧面。", "primary_collocate": null, "pronunciation": "fāng miàn", "ipa": "faŋ˥ mjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "在学习方面，他很努力。", "target_word": "方面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题有两个方面。", "target_word": "方面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要看问题的另一方面。", "target_word": "方面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在工作方面很有经验。", "target_word": "方面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在饮食方面，医生给了我很多建议。", "target_word": "方面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这方面的知识我知道得不多。", "target_word": "方面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一方面我想去旅行，另一方面我没有时间。", "target_word": "方面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子在语言方面进步很快。", "target_word": "方面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司在服务方面做得很好。", "target_word": "方面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在健康方面没有什么问题。", "target_word": "方面", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "各方面", "label": "复合"}, {"form": "方方面面", "label": "重叠"}], "register": "中性", "sense_fingerprint": "事物或问题的某个局部或侧面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'afe32d86-09dd-4bdf-8957-2d763f51e2dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12696, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "方面", "is_correct": true, "explanation": "fāng miàn（方面）指事物或问题的某一局部或侧面，此处正合句意。"}, {"text": "当面", "is_correct": false, "explanation": "dāng（第一声）与 fāng 声母不同，意思是“当面”，指面对面，不是“方面”。"}, {"text": "方便", "is_correct": false, "explanation": "biàn（第四声）与 miàn 声母不同，意思是“方便”，指便利、不麻烦。"}, {"text": "锋面", "is_correct": false, "explanation": "fēng（第一声）与 fāng 韵母不同，意思是“锋面”，指气象中冷暖气团的交界面。"}], "explanations": {"方面": "fāng miàn（方面）指事物或问题的某一局部或侧面，此处正合句意。", "当面": "dāng（第一声）与 fāng 声母不同，意思是“当面”，指面对面，不是“方面”。", "方便": "biàn（第四声）与 miàn 声母不同，意思是“方便”，指便利、不麻烦。", "锋面": "fēng（第一声）与 fāng 韵母不同，意思是“锋面”，指气象中冷暖气团的交界面。"}, "sentence_index": null, "correct_answer": "方面"}, "level_3": {"options": [{"text": "方面", "is_correct": true, "explanation": "“在学习方面”指学习这一方面，此处正合句意。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：“厨房”不是学习的领域，“在学习厨房”句意不通。"}, {"text": "地铁", "is_correct": false, "explanation": "语义：“地铁”不是可以学习的内容，句子读不通。"}, {"text": "车站", "is_correct": false, "explanation": "搭配：“学习”要求知识或技能作对象，“车站”不能作学习的范围。"}], "explanations": {"方面": "“在学习方面”指学习这一方面，此处正合句意。", "厨房": "语义：“厨房”不是学习的领域，“在学习厨房”句意不通。", "地铁": "语义：“地铁”不是可以学习的内容，句子读不通。", "车站": "搭配：“学习”要求知识或技能作对象，“车站”不能作学习的范围。"}, "sentence_index": 0, "correct_answer": "方面"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们去的方面很美丽。", "explanation": "这里应该用〈地方〉。方面指事物或问题的侧面，不指地点。"}, {"text": "他是我最尊敬的方面。", "explanation": "这里应该用〈老师〉。方面不指人，不能用来称呼值得尊敬的人。"}, {"text": "我们要从两张方面来看这件事。", "explanation": "这里应该用〈个〉。“方面”用“个”计量，“张”多用于纸、桌子等平面的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b669a4a-1005-455a-b931-f13f08555612') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12696, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "方面", "is_correct": true, "explanation": "fāng miàn（方面）指事物或问题的某一局部或侧面，此处正合句意。"}, {"text": "方片", "is_correct": false, "explanation": "piàn（第四声）与 miàn 声母不同，意思是“方片”，指扑克牌中的方块花色。"}, {"text": "翻面", "is_correct": false, "explanation": "fān（第一声）与 fāng 韵母不同，意思是“翻面”，指把东西翻过来。"}, {"text": "汤面", "is_correct": false, "explanation": "tāng（第一声）与 fāng 声母不同，意思是“汤面”，指带汤的面条。"}], "explanations": {"方面": "fāng miàn（方面）指事物或问题的某一局部或侧面，此处正合句意。", "方片": "piàn（第四声）与 miàn 声母不同，意思是“方片”，指扑克牌中的方块花色。", "翻面": "fān（第一声）与 fāng 韵母不同，意思是“翻面”，指把东西翻过来。", "汤面": "tāng（第一声）与 fāng 声母不同，意思是“汤面”，指带汤的面条。"}, "sentence_index": null, "correct_answer": "方面"}, "level_3": {"options": [{"text": "方面", "is_correct": true, "explanation": "“一方面”与“另一方面”成对，表示两个侧面，此处正合句意。"}, {"text": "天", "is_correct": false, "explanation": "搭配：“一天”不能与“另一方面”成对，前后不呼应。"}, {"text": "年", "is_correct": false, "explanation": "语义：“一年”是时间单位，不能与“另一方面”成对，前后不呼应。"}, {"text": "次", "is_correct": false, "explanation": "语义：“一次”指一回，不能与“另一方面”构成侧面的对举，前后不呼应。"}], "explanations": {"方面": "“一方面”与“另一方面”成对，表示两个侧面，此处正合句意。", "天": "搭配：“一天”不能与“另一方面”成对，前后不呼应。", "年": "语义：“一年”是时间单位，不能与“另一方面”成对，前后不呼应。", "次": "语义：“一次”指一回，不能与“另一方面”构成侧面的对举，前后不呼应。"}, "sentence_index": 6, "correct_answer": "方面"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家店的方面很好吃。", "explanation": "这里应该用〈食物〉。方面指事物的侧面，不能用来形容可以吃的东西。"}, {"text": "他的方面很健康。", "explanation": "这里应该用〈身体〉。方面不能作“健康”的主体，说人的状态要用身体。"}, {"text": "我们要考虑两条方面的问题。", "explanation": "这里应该用〈个〉。“方面”要用“个”计量，“条”多用于细长的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b669a4a-1005-455a-b931-f13f08555612') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12696, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在语言的几张方面进步很大。", "corrected_sentence": "他在语言的几个方面进步很大。", "error_description": "“方面”要用“个”计量，不能用“张”；“张”多用于纸、桌子等平面的东西，应说“几个方面”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b669a4a-1005-455a-b931-f13f08555612') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12696, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一方面这个计划很好，二方面成本太高。", "corrected_sentence": "一方面这个计划很好，另一方面成本太高。", "error_description": "“一方面……另一方面”是固定的对举格式，后半句应说“另一方面”，不能说“二方面”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b669a4a-1005-455a-b931-f13f08555612') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
