INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12700, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "企业或个人通过一定方式获取资金的行为。", "primary_collocate": null, "pronunciation": "róng zī", "ipa": "ʐʊŋ˧˥ tsɹ̩˥", "syllable_count": 2, "sentences": [{"text": "这种公私协作的创新融资模式，催生了“环境收益债券”等新型金融工具，将碳汇增量、能源节约与居民健康改善等外部性效益证券化，开辟了可持续投资的量化回报路径。", "target_word": "融资", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这家小公司正在想办法融资。", "target_word": "融资", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新公司上个月成功融资了一百万元。", "target_word": "融资", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司需要融资，才能买新机器。", "target_word": "融资", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "银行可以帮企业融资。", "target_word": "融资", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他开了一家店，但是融资很困难。", "target_word": "融资", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个年轻人为新项目融资，找了很多朋友。", "target_word": "融资", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司想通过发行债券融资。", "target_word": "融资", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "融资以后，他们请了更多的工人。", "target_word": "融资", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小企业融资难，是很多人关心的问题。", "target_word": "融资", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "融资渠道", "label": "复合"}, {"form": "融资成本", "label": "复合"}, {"form": "融資", "label": "繁体"}], "register": "书面", "sense_fingerprint": "融资：企业或个人通过一定方式获取资金", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3b355173-4ded-4ba2-b8ef-c4046b577508') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12700, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "融资", "is_correct": true, "explanation": "正确：“创新融资模式”指为筹集资金而采用的方式，与“催生了新型金融工具”的语境吻合。"}, {"text": "烹饪", "is_correct": false, "explanation": "语义：烹饪指做饭，与金融工具无关，句子不通。"}, {"text": "足球", "is_correct": false, "explanation": "语义：足球是体育运动，与金融工具无关，句子不通。"}, {"text": "维修", "is_correct": false, "explanation": "搭配：“维修”的对象通常是机器设备，“创新维修模式”与金融工具的语境搭配不当。"}], "explanations": {"融资": "正确：“创新融资模式”指为筹集资金而采用的方式，与“催生了新型金融工具”的语境吻合。", "烹饪": "语义：烹饪指做饭，与金融工具无关，句子不通。", "足球": "语义：足球是体育运动，与金融工具无关，句子不通。", "维修": "搭配：“维修”的对象通常是机器设备，“创新维修模式”与金融工具的语境搭配不当。"}, "sentence_index": 0, "correct_answer": "融资"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他决定融资这家公司。", "explanation": "这里应该用〈投资〉。融资是为自己筹集资金；把钱放进别人的公司要用投资。"}, {"text": "他把钱融资给了朋友。", "explanation": "这里应该用〈借给〉。融资是获取资金，不是把钱交给别人；把钱借给别人要说借给。"}, {"text": "公司融资了三个新员工。", "explanation": "这里应该用〈雇用〉。融资的对象是资金，不能用于人；招用员工要说雇用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '776b36fe-5714-4c91-a872-cd46e51e87e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12700, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "融资", "is_correct": true, "explanation": "正确：“为新项目融资”表示为项目筹集资金，与“找了很多朋友”的语境吻合。"}, {"text": "修理", "is_correct": false, "explanation": "语义：修理针对损坏的物品，不能用于为项目而做的事，句子不通。"}, {"text": "验收", "is_correct": false, "explanation": "搭配：验收是检查项目是否合格，“为新项目验收，找了很多朋友”搭配不当。"}, {"text": "清扫", "is_correct": false, "explanation": "语义：清扫是打扫卫生，与为新项目找朋友的事情无关，句子不通。"}], "explanations": {"融资": "正确：“为新项目融资”表示为项目筹集资金，与“找了很多朋友”的语境吻合。", "修理": "语义：修理针对损坏的物品，不能用于为项目而做的事，句子不通。", "验收": "搭配：验收是检查项目是否合格，“为新项目验收，找了很多朋友”搭配不当。", "清扫": "语义：清扫是打扫卫生，与为新项目找朋友的事情无关，句子不通。"}, "sentence_index": 6, "correct_answer": "融资"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天都在融资时间。", "explanation": "这里应该用〈节省〉。融资是获取资金，不能用于时间；节省时间要说节省。"}, {"text": "他融资了损失。", "explanation": "这里应该用〈赔偿〉。融资的对象是资金，损失是需要补偿的东西；补偿损失要说赔偿。"}, {"text": "这家大公司融资了一家小企业。", "explanation": "这里应该用〈收购〉。融资是为自己获取资金，不是买下别的企业；买下企业要说收购。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '776b36fe-5714-4c91-a872-cd46e51e87e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12700, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们想通过银行融资了。", "corrected_sentence": "他们想通过银行融资。", "error_description": "“想通过银行融资了”错误，应为“想通过银行融资”。“想”表示打算或意愿，与表示完成的“了”不能同用。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '776b36fe-5714-4c91-a872-cd46e51e87e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12700, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们打算向银行融资了一百万元。", "corrected_sentence": "他们打算向银行融资一百万元。", "error_description": "“打算向银行融资了一百万元”错误，应为“打算向银行融资一百万元”。“打算”表示将来的意愿，句中的“了”表示已经完成，二者不能同用。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '776b36fe-5714-4c91-a872-cd46e51e87e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
