INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12701, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "债券是一种有价证券，是政府、金融机构或企业等发行主体为筹集资金而向投资者出具的、承诺按一定利率支付利息并按约定条件偿还本金的债权债务凭证。", "primary_collocate": null, "pronunciation": "zhài quàn", "ipa": "ʈʂai˥˩ tɕʰyɛn˥˩", "syllable_count": 2, "sentences": [{"text": "这种公私协作的创新融资模式，催生了“环境收益债券”等新型金融工具，将碳汇增量、能源节约与居民健康改善等外部性效益证券化，开辟了可持续投资的量化回报路径。", "target_word": "债券", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "他买了一些政府债券。", "target_word": "债券", "complexity_tier": "T3", "furigana": "tā mǎi le yìxiē zhèngfǔ zhàiquàn", "sentence_source": "generated"}, {"text": "这张债券五年后到期。", "target_word": "债券", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "银行发行了新的债券。", "target_word": "债券", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "债券的利息比存款高。", "target_word": "债券", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司用发行债券的办法借钱。", "target_word": "债券", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人把全部积蓄投资于债券。", "target_word": "债券", "complexity_tier": "T3", "furigana": "lǎorén bǎ quánbù jīxù tóuzī yú zhàiquàn", "sentence_source": "generated"}, {"text": "债券到期后可以拿回本金。", "target_word": "债券", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多人觉得债券比股票安全。", "target_word": "债券", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府今年发行了一千亿元债券。", "target_word": "债券", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "张", "label": "量词"}, {"form": "公司债券", "label": "复合"}], "register": "正式", "sense_fingerprint": "发行主体筹资时出具的有价证券", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'afe32d86-09dd-4bdf-8957-2d763f51e2dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12701, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "债券", "is_correct": true, "explanation": "正确答案：债券 zhàiquàn，指一种有价证券，与听到的读音一致。"}, {"text": "债权", "is_correct": false, "explanation": "债权 zhàiquán 与 债券 zhàiquàn 只有第二个字声调不同（quán 第二声，quàn 第四声），意思是债权人享有的请求权。"}, {"text": "彩券", "is_correct": false, "explanation": "彩券 cǎiquàn 与 债券 zhàiquàn 第一个字声母不同（c 与 zh）且声调不同，意思是彩票。"}, {"text": "菜券", "is_correct": false, "explanation": "菜券 càiquàn 与 债券 zhàiquàn 第一个字声母不同（c 与 zh），声调相同（第四声），意思是买菜用的购物券。"}], "explanations": {"债券": "正确答案：债券 zhàiquàn，指一种有价证券，与听到的读音一致。", "债权": "债权 zhàiquán 与 债券 zhàiquàn 只有第二个字声调不同（quán 第二声，quàn 第四声），意思是债权人享有的请求权。", "彩券": "彩券 cǎiquàn 与 债券 zhàiquàn 第一个字声母不同（c 与 zh）且声调不同，意思是彩票。", "菜券": "菜券 càiquàn 与 债券 zhàiquàn 第一个字声母不同（c 与 zh），声调相同（第四声），意思是买菜用的购物券。"}, "sentence_index": null, "correct_answer": "债券"}, "level_3": {"options": [{"text": "债券", "is_correct": true, "explanation": "正确。“环境收益债券”是一种金融工具，与句中的“融资模式”“证券化”相符。"}, {"text": "公园", "is_correct": false, "explanation": "语义：公园不是金融工具，无法被证券化，与“融资模式”“金融工具”冲突。"}, {"text": "木材", "is_correct": false, "explanation": "搭配：“环境收益”后面不能接“木材”，木材也不是融资工具。"}, {"text": "农药", "is_correct": false, "explanation": "语义：农药是化学品，不是融资工具，与句中的“创新融资”“证券化”冲突。"}], "explanations": {"债券": "正确。“环境收益债券”是一种金融工具，与句中的“融资模式”“证券化”相符。", "公园": "语义：公园不是金融工具，无法被证券化，与“融资模式”“金融工具”冲突。", "木材": "搭配：“环境收益”后面不能接“木材”，木材也不是融资工具。", "农药": "语义：农药是化学品，不是融资工具，与句中的“创新融资”“证券化”冲突。"}, "sentence_index": 0, "correct_answer": "债券"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他向银行申请了一笔债券。", "explanation": "这里应该用〈贷款〉。申请的是贷款；债券是政府或企业发行、供投资者购买的有价证券，不能向银行申请。"}, {"text": "他写了一张债券给朋友。", "explanation": "这里应该用〈借条〉。写给朋友的是借条这类个人借据；债券由发行主体出具，个人不能这样写出。"}, {"text": "银行发行了一头新的债券。", "explanation": "这里应该用〈张〉。“头”用于牛等大型牲畜，不能用于债券；债券的量词是“张”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b669a4a-1005-455a-b931-f13f08555612') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12701, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "债券", "is_correct": true, "explanation": "正确。“投资于”后接金融产品，债券是可投资的对象。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不能作为投资对象，与“全部积蓄”“投资”冲突。"}, {"text": "笑话", "is_correct": false, "explanation": "搭配：“投资于”不能接“笑话”，二者不搭配。"}, {"text": "微笑", "is_correct": false, "explanation": "搭配：“投资于微笑”不成立，“投资于”后不能接表情。"}], "explanations": {"债券": "正确。“投资于”后接金融产品，债券是可投资的对象。", "空气": "语义：空气不能作为投资对象，与“全部积蓄”“投资”冲突。", "笑话": "搭配：“投资于”不能接“笑话”，二者不搭配。", "微笑": "搭配：“投资于微笑”不成立，“投资于”后不能接表情。"}, "sentence_index": 6, "correct_answer": "债券"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家公司的债券每年都会分红。", "explanation": "这里应该用〈股票〉。分红是股票的收益方式；债券付的是约定利息，不能说分红。"}, {"text": "他给全家人买了人寿债券。", "explanation": "这里应该用〈保险〉。“人寿”修饰的是保险，人寿保险是保险合同，不是债券。"}, {"text": "他向朋友借债券度过了难关。", "explanation": "这里应该用〈借款〉。借的是钱款，债券是有价证券，不能用来借。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b669a4a-1005-455a-b931-f13f08555612') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12701, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他买了一本债券。", "corrected_sentence": "他买了一张债券。", "error_description": "量词错误：债券的量词应为“张”，“本”用于书册，不能用于债券。应说“买了一张债券”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b669a4a-1005-455a-b931-f13f08555612') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12701, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他买了三张债券们。", "corrected_sentence": "他买了三张债券。", "error_description": "后缀错误：「们」只用于指人的名词，债券是非人名词，不能加「们」表示复数。应说“他买了三张债券”，用量词“张”计量即可。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b669a4a-1005-455a-b931-f13f08555612') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12702, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "减量", "is_correct": true, "explanation": "正确：减量指减少的数量，与“增量”（增加的数量）构成反义。"}, {"text": "总额", "is_correct": false, "explanation": "总额指全部数量之和，与“增量”的增加部分不构成反义。"}, {"text": "面积", "is_correct": false, "explanation": "面积指平面或表面的大小，与“增加的数量”无关，不构成反义。"}, {"text": "比例", "is_correct": false, "explanation": "比例指两个量之间的比，与“增加的数量”不是反义关系。"}], "correct_answer": "减量", "explanations": {"减量": "正确：减量指减少的数量，与“增量”（增加的数量）构成反义。", "总额": "总额指全部数量之和，与“增量”的增加部分不构成反义。", "面积": "面积指平面或表面的大小，与“增加的数量”无关，不构成反义。", "比例": "比例指两个量之间的比，与“增加的数量”不是反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b669a4a-1005-455a-b931-f13f08555612') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12702, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "减量", "is_correct": true, "explanation": "正确：减量指减少的数量，与“增量”（增加的数量）构成反义。"}, {"text": "速度", "is_correct": false, "explanation": "速度指物体运动的快慢，与“增加的数量”无关，不构成反义。"}, {"text": "体积", "is_correct": false, "explanation": "体积指物体所占空间的大小，与“增加的数量”不是反义关系。"}, {"text": "质地", "is_correct": false, "explanation": "质地指物质的结构或质量特征，与“增加的数量”不构成反义。"}], "correct_answer": "减量", "explanations": {"减量": "正确：减量指减少的数量，与“增量”（增加的数量）构成反义。", "速度": "速度指物体运动的快慢，与“增加的数量”无关，不构成反义。", "体积": "体积指物体所占空间的大小，与“增加的数量”不是反义关系。", "质地": "质地指物质的结构或质量特征，与“增加的数量”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b669a4a-1005-455a-b931-f13f08555612') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12702, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指在原有基础上增加的部分或数量。", "primary_collocate": null, "pronunciation": "zēng liàng", "ipa": "tsəŋ˥ liaŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这种公私协作的创新融资模式，催生了“环境收益债券”等新型金融工具，将碳汇增量、能源节约与居民健康改善等外部性效益证券化，开辟了可持续投资的量化回报路径。", "target_word": "增量", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "今年的用水增量不大。", "target_word": "增量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的销售增量来自海外。", "target_word": "增量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市的人口增量很大。", "target_word": "增量", "complexity_tier": "T3", "furigana": "zhège chéngshì de rénkǒu zēngliàng hěn dà", "sentence_source": "generated"}, {"text": "他们想算一算收入的增量。", "target_word": "增量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "增量主要来自新客户。", "target_word": "增量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "和去年比，粮食增量有两百万吨。", "target_word": "增量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电力增量满足了新工厂的需要。", "target_word": "增量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这笔增量资金用来修路。", "target_word": "增量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的利润增量比去年高。", "target_word": "增量", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "净增量", "label": "复合"}], "register": "正式", "sense_fingerprint": "在原有基础上增加的部分或数量", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'afe32d86-09dd-4bdf-8957-2d763f51e2dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12702, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "增量", "is_correct": true, "explanation": "正确。“碳汇增量”指碳汇增加的部分，与句中的证券化效益相符。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不是可量化的增加部分，无法被证券化。"}, {"text": "口味", "is_correct": false, "explanation": "语义：口味与“碳汇”“能源节约”的量化效益无关，不能被证券化。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：“碳汇”后不能接“身高”，二者不搭配。"}], "explanations": {"增量": "正确。“碳汇增量”指碳汇增加的部分，与句中的证券化效益相符。", "颜色": "语义：颜色不是可量化的增加部分，无法被证券化。", "口味": "语义：口味与“碳汇”“能源节约”的量化效益无关，不能被证券化。", "身高": "搭配：“碳汇”后不能接“身高”，二者不搭配。"}, "sentence_index": 0, "correct_answer": "增量"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个城市的人口增量很快。", "explanation": "这里应该用〈增速〉。增速指增长的快慢，可以说“很快”；增量是增加的绝对数量，不说快慢。"}, {"text": "这个城市的人口增量为百分之三。", "explanation": "这里应该用〈增幅〉。增幅用百分比表示增长比例；增量是增加的绝对数量，不能与百分比搭配。"}, {"text": "我们算出了收入的一只增量。", "explanation": "这里应该用量词〈笔〉或〈部分〉。增量不用“只”，“只”用于动物等。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b669a4a-1005-455a-b931-f13f08555612') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12702, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "增量", "is_correct": true, "explanation": "正确。“和去年比，粮食增量有两百万吨”表示比去年增加的数量，与句意相符。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格不是数量，“粮食价格有两百万吨”不成立。"}, {"text": "温度", "is_correct": false, "explanation": "语义：温度不能用吨来计量，与“粮食”“两百万吨”冲突。"}, {"text": "名字", "is_correct": false, "explanation": "搭配：“两百万吨”是重量，不能修饰“名字”，二者不搭配。"}], "explanations": {"增量": "正确。“和去年比，粮食增量有两百万吨”表示比去年增加的数量，与句意相符。", "价格": "语义：价格不是数量，“粮食价格有两百万吨”不成立。", "温度": "语义：温度不能用吨来计量，与“粮食”“两百万吨”冲突。", "名字": "搭配：“两百万吨”是重量，不能修饰“名字”，二者不搭配。"}, "sentence_index": 6, "correct_answer": "增量"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们的利润增量达到百分之十。", "explanation": "这里应该用〈增速〉。增速用百分比表示增长快慢；增量是绝对数量，不能用百分比表示。"}, {"text": "我们的一场增量比去年高。", "explanation": "这里应该用量词〈笔〉或〈部分〉。增量不用“场”，“场”用于比赛、事件等。"}, {"text": "我们公司的一只增量比去年高。", "explanation": "这里应该用量词〈个〉或〈部分〉。增量不用“只”，“只”用于动物等。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b669a4a-1005-455a-b931-f13f08555612') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12702, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只增量用来交税。", "corrected_sentence": "这笔增量用来交税。", "error_description": "量词错误：“增量”的量词应为“笔”，“只”用于动物等，不能用于增量。应说“这笔增量用来交税”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b669a4a-1005-455a-b931-f13f08555612') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12702, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们算出了一只增量。", "corrected_sentence": "我们算出了一笔增量。", "error_description": "量词错误：增量的量词应为“笔”，“只”用于动物等，不能用于增量。应说“算出了一笔增量”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b669a4a-1005-455a-b931-f13f08555612') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12703, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62a53044-a493-4c4f-98e1-1c5ad3ab549f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
