INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12703, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "外部性是指一个经济主体的行为对另一个经济主体产生的影响，而这种影响没有通过市场价格反映出来，分为正外部性和负外部性。", "primary_collocate": null, "pronunciation": "wài bù xìng", "ipa": "waɪ˥˩ pu˥˩ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "这种公私协作的创新融资模式，催生了“环境收益债券”等新型金融工具，将碳汇增量、能源节约与居民健康改善等外部性效益证券化，开辟了可持续投资的量化回报路径。", "target_word": "外部性", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "污染是一种典型的外部性。", "target_word": "外部性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经济学家常常讨论外部性问题。", "target_word": "外部性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂排污会产生外部性，附近居民受到了影响。", "target_word": "外部性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府想用税收来解决外部性问题。", "target_word": "外部性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "种花让邻居也觉得开心，这是一种外部性。", "target_word": "外部性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外部性让市场价格不能反映真实成本。", "target_word": "外部性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生要先弄清楚外部性是什么意思。", "target_word": "外部性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司没有考虑生产带来的外部性。", "target_word": "外部性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吸烟的外部性让旁边的人受到伤害。", "target_word": "外部性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "正外部性", "label": "复合"}, {"form": "负外部性", "label": "复合"}], "register": "书面语", "sense_fingerprint": "经济学术语：行为影响他人却未通过市场价格体现", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fcde248-60b2-40e2-9942-98eba9d40edd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12703, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "电压", "is_correct": false, "explanation": "搭配：“电压”不能修饰“效益”，“电压效益证券化”不成立。"}, {"text": "外部性", "is_correct": true, "explanation": "“外部性效益”指未通过市场定价的外溢效益，与前文的“碳汇增量、能源节约、居民健康改善”并列，作定语修饰“效益”，句意通顺。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重不是一种可以证券化的环境或经济效益，与前文的并列成分不属于同一类。"}, {"text": "利率", "is_correct": false, "explanation": "语义：利率是资金的价格，不是可以被证券化的效益类别，“利率效益”说不通。"}], "explanations": {"电压": "搭配：“电压”不能修饰“效益”，“电压效益证券化”不成立。", "外部性": "“外部性效益”指未通过市场定价的外溢效益，与前文的“碳汇增量、能源节约、居民健康改善”并列，作定语修饰“效益”，句意通顺。", "体重": "语义：体重不是一种可以证券化的环境或经济效益，与前文的并列成分不属于同一类。", "利率": "语义：利率是资金的价格，不是可以被证券化的效益类别，“利率效益”说不通。"}, "sentence_index": 0, "correct_answer": "外部性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的外部性很强，喜欢认识新朋友。", "explanation": "这里应该用〈外向性〉。外部性是经济学术语，指经济行为对他人的影响，不用来形容人的性格；描述性格要用外向性。"}, {"text": "这座桥被外部性冲垮了。", "explanation": "这里应该用〈外力〉。外部性指经济行为对他人的影响，不指物理上从外面施加的力量；被水流、风等冲垮要说“外力”。"}, {"text": "这面墙的外部性很漂亮。", "explanation": "这里应该用〈外部〉。外部性指经济学上的影响，不指物体的表面；说墙的外面要用“外部”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62a53044-a493-4c4f-98e1-1c5ad3ab549f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12703, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "成本", "is_correct": false, "explanation": "搭配：句中已有“真实成本”，若用“成本”作主语，“成本让……不能反映真实成本”语义重复、不通。"}, {"text": "心情", "is_correct": false, "explanation": "语义：心情不会影响市场价格，“心情让市场价格不能反映真实成本”不成立。"}, {"text": "外部性", "is_correct": true, "explanation": "“外部性”作主语，指行为的影响没有体现在价格中，因此市场价格不能反映真实成本，句意符合。"}, {"text": "身高", "is_correct": false, "explanation": "语义：身高与市场价格和成本无关，不能作为使价格失真的原因。"}], "explanations": {"成本": "搭配：句中已有“真实成本”，若用“成本”作主语，“成本让……不能反映真实成本”语义重复、不通。", "心情": "语义：心情不会影响市场价格，“心情让市场价格不能反映真实成本”不成立。", "外部性": "“外部性”作主语，指行为的影响没有体现在价格中，因此市场价格不能反映真实成本，句意符合。", "身高": "语义：身高与市场价格和成本无关，不能作为使价格失真的原因。"}, "sentence_index": 6, "correct_answer": "外部性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们要减少外部性的干扰。", "explanation": "这里应该用〈外界〉。外部性是经济学术语，指行为对他人的影响；指外面世界对我们的干扰要说“外界”。"}, {"text": "公司外部性的矛盾很多。", "explanation": "这里应该用〈内部〉。外部性不指组织内部的关系；说公司内部的矛盾要用“内部”。"}, {"text": "不要只看人的外部性。", "explanation": "这里应该用〈外在〉。外部性指经济行为的影响，不指人的外表；谈外貌、外表要用“外在”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62a53044-a493-4c4f-98e1-1c5ad3ab549f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12703, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "企业排放废水，会产生了一种负外部性，周围居民也要承担代价。", "corrected_sentence": "企业排放废水，会产生一种负外部性，周围居民也要承担代价。", "error_description": "“了”误用：“会”表示将来，“产生了”表示已经完成，二者冲突；应去掉“了”，说“会产生一种负外部性”。错误在动词后的“了”，不在量词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62a53044-a493-4c4f-98e1-1c5ad3ab549f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12703, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "政府的补贴带来了一只正外部性，使更多人受益。", "corrected_sentence": "政府的补贴带来了一种正外部性，使更多人受益。", "error_description": "量词误用：“外部性”应搭配量词“种”，不能用“只”（“只”多用于动物或成对的东西）；应说“带来了一种正外部性”。错误在量词，不在“正”的位置。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62a53044-a493-4c4f-98e1-1c5ad3ab549f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
