INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12707, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "将事物转化为可测量的数值或指标。", "primary_collocate": null, "pronunciation": "liàng huà", "ipa": "ljaŋ˥˩ xwa˥˩", "syllable_count": 2, "sentences": [{"text": "这种公私协作的创新融资模式，催生了“环境收益债券”等新型金融工具，将碳汇增量、能源节约与居民健康改善等外部性效益证券化，开辟了可持续投资的量化回报路径。", "target_word": "量化", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "工作成果很难量化。", "target_word": "量化", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们需要把学习效果量化。", "target_word": "量化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这项指标无法量化，只能靠经验判断。", "target_word": "量化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司用数据量化每个员工的业绩。", "target_word": "量化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "研究人员正在量化空气污染的影响。", "target_word": "量化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "把风险量化以后，管理者更容易决策。", "target_word": "量化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "满意度可以通过问卷来量化。", "target_word": "量化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "科学家想量化气候变化带来的损失。", "target_word": "量化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个目标不够具体，也没法量化。", "target_word": "量化", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "量化了", "label": "体标"}, {"form": "量化过", "label": "体标"}, {"form": "量化分析", "label": "复合"}], "register": "书面", "sense_fingerprint": "把抽象事物转化为可测量的数值或指标", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd042e930-7fd0-48af-9748-9ff8f70b3c62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12707, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "量化", "is_correct": true, "explanation": "量化：这里指能够用数值衡量，修饰“回报路径”，说明回报可以计量，语境相合。"}, {"text": "切割", "is_correct": false, "explanation": "语义：切割指切开，与“回报路径”的数值化无关，不能让路径变得可以计量。"}, {"text": "烘焙", "is_correct": false, "explanation": "语义：“烘焙”指用火加工面点食物，与回报路径的数值计量无关。"}, {"text": "体验", "is_correct": false, "explanation": "搭配：“体验”说的是感受，不能用来修饰“回报路径”。"}], "explanations": {"量化": "量化：这里指能够用数值衡量，修饰“回报路径”，说明回报可以计量，语境相合。", "切割": "语义：切割指切开，与“回报路径”的数值化无关，不能让路径变得可以计量。", "烘焙": "语义：“烘焙”指用火加工面点食物，与回报路径的数值计量无关。", "体验": "搭配：“体验”说的是感受，不能用来修饰“回报路径”。"}, "sentence_index": 0, "correct_answer": "量化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工人正在量化房间的面积。", "explanation": "这里应该用〈测量〉。量化指把抽象事物转化为数值，房间的面积是具体的长度，要用测量。"}, {"text": "公司把纸质档案量化了。", "explanation": "这里应该用〈数字化〉。量化强调转化为可测量的数值指标，把纸质文件变成电子文件要用数字化。"}, {"text": "超市里正在量化水果。", "explanation": "这里应该用〈称重〉。水果的重量是具体的测量，要说称重，不能说量化。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7543f63b-fd76-44ab-99eb-487ab45345c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12707, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "量化", "is_correct": true, "explanation": "量化：这里指把风险转化为可测量的数值，与“管理者更容易决策”的语境相合。"}, {"text": "拧干", "is_correct": false, "explanation": "语义：“拧干”指用力挤出水分，风险不能被拧干，句意不通。"}, {"text": "加热", "is_correct": false, "explanation": "语义：“加热”指使东西升温，风险不能被加热，句意不通。"}, {"text": "背诵", "is_correct": false, "explanation": "搭配：“背诵”的对象是课文或诗词，不能说“把风险背诵”。"}], "explanations": {"量化": "量化：这里指把风险转化为可测量的数值，与“管理者更容易决策”的语境相合。", "拧干": "语义：“拧干”指用力挤出水分，风险不能被拧干，句意不通。", "加热": "语义：“加热”指使东西升温，风险不能被加热，句意不通。", "背诵": "搭配：“背诵”的对象是课文或诗词，不能说“把风险背诵”。"}, "sentence_index": 6, "correct_answer": "量化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这份报告把三点结论量化出来了。", "explanation": "这里应该用〈归纳〉。量化指把事物变成数值，提炼出三点结论要用归纳。"}, {"text": "这本书是用英文量化成汉语的。", "explanation": "这里应该用〈翻译〉。量化是把事物变成数值，把英文转成汉语要用翻译。"}, {"text": "孩子们在课堂上量化课文。", "explanation": "这里应该用〈朗读〉。量化指变成数值，大声读课文要用朗读。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7543f63b-fd76-44ab-99eb-487ab45345c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12707, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师把学生的表现量化分数。", "corrected_sentence": "老师把学生的表现量化成分数。", "error_description": "补语缺失：“量化”后要用“成”引出结果，应说“量化成分数”，去掉“成”就不通顺。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7543f63b-fd76-44ab-99eb-487ab45345c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12707, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "财务部门把成本量化很清楚。", "corrected_sentence": "财务部门把成本量化得很清楚。", "error_description": "补语标记缺失：说明“清楚”的程度时，“量化”后要用“得”，应说“量化得很清楚”，省略“得”就不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7543f63b-fd76-44ab-99eb-487ab45345c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
