INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12713, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指一种通过奖励或惩罚来引导人们努力工作的规则或方式。", "primary_collocate": null, "pronunciation": "jī lì jī zhì", "ipa": "tɕi˥ li˥˩ tɕi˥ ʈʂɻ̩˥˩", "syllable_count": 4, "sentences": [{"text": "监管不再局限于禁限措施，更涵盖激励机制、信息透明与公众参与等多元工具。", "target_word": "激励机制", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "前沿的城市治理实践正试图通过法规强制与激励机制，确保低收入社区同样享有技术赋能的农业设施与高质量绿地，避免生态特权的固化。", "target_word": "激励机制", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "公司想用新的激励机制留住员工。", "target_word": "激励机制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的激励机制能让大家更努力工作。", "target_word": "激励机制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个班的激励机制是每周奖励一次。", "target_word": "激励机制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们公司没有合适的激励机制。", "target_word": "激励机制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司改了激励机制，大家都很高兴。", "target_word": "激励机制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板说，要建立公平的激励机制。", "target_word": "激励机制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有了激励机制，工人干活更积极了。", "target_word": "激励机制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的激励机制是多卖多得。", "target_word": "激励机制", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一套激励机制", "label": "量词"}], "register": "中性", "sense_fingerprint": "用奖惩规则引导人们努力工作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90865500-d708-484f-b474-f4f4acd19e44') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12713, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "激励机制", "is_correct": true, "explanation": "正确。“激励机制”是多元工具之一，与“信息透明、公众参与”并列，句意通顺。"}, {"text": "语言", "is_correct": false, "explanation": "语义：“语言”不是监管工具，与前后并列的“多元工具”不一致。"}, {"text": "交响乐", "is_correct": false, "explanation": "语义：“交响乐”不属于监管工具，句子读起来不通。"}, {"text": "季节", "is_correct": false, "explanation": "搭配：“涵盖”后接的应是可以列为工具的事物，“季节”不能这样搭配。"}], "explanations": {"激励机制": "正确。“激励机制”是多元工具之一，与“信息透明、公众参与”并列，句意通顺。", "语言": "语义：“语言”不是监管工具，与前后并列的“多元工具”不一致。", "交响乐": "语义：“交响乐”不属于监管工具，句子读起来不通。", "季节": "搭配：“涵盖”后接的应是可以列为工具的事物，“季节”不能这样搭配。"}, "sentence_index": 0, "correct_answer": "激励机制"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公司每月给表现好的员工发激励机制。", "explanation": "这里应该用〈奖励〉。“发”后面接的应是奖品等具体事物，激励机制是制度，不能直接发放。"}, {"text": "这个月我拿到了很多激励机制。", "explanation": "这里应该用〈奖金〉。奖金是可以拿到的钱，激励机制是制度，不能说“拿到”。"}, {"text": "公司下个月给我们涨激励机制。", "explanation": "这里应该用〈工资〉。“涨”用于工资、物价，激励机制是制度，不能说“涨”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e155ee9-b460-47eb-b88b-f47b46a1a6c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12713, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "激励机制", "is_correct": true, "explanation": "正确。“改了激励机制”指修改一套制度，与句意相合。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“改”一般不与“天气”搭配，“改了天气”在这里不通。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“空气”不能被“改”，“改了空气”读起来不通。"}, {"text": "脚步", "is_correct": false, "explanation": "语义：“脚步”不是可以修改的制度，句意不通。"}], "explanations": {"激励机制": "正确。“改了激励机制”指修改一套制度，与句意相合。", "天气": "搭配：“改”一般不与“天气”搭配，“改了天气”在这里不通。", "空气": "搭配：“空气”不能被“改”，“改了空气”读起来不通。", "脚步": "语义：“脚步”不是可以修改的制度，句意不通。"}, "sentence_index": 6, "correct_answer": "激励机制"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校每年给优秀学生颁发激励机制。", "explanation": "这里应该用〈奖学金〉。“颁发”的对象是奖学金、证书等，激励机制是制度，不能颁发。"}, {"text": "他每个月按时领取激励机制。", "explanation": "这里应该用〈薪水〉。“领取”用于薪水、奖金等钱物，激励机制是制度，不能领取。"}, {"text": "运动员在赛场上赢得了激励机制。", "explanation": "这里应该用〈金牌〉。“赢得”的对象是金牌、比赛等，激励机制是制度，不能赢得。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e155ee9-b460-47eb-b88b-f47b46a1a6c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12713, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "公司新推出了几套激励机制们。", "corrected_sentence": "公司新推出了几套激励机制。", "error_description": "错误：“激励机制们”。“们”只用于指人的复数，“激励机制”是事物，不能加“们”。正确为“几套激励机制”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e155ee9-b460-47eb-b88b-f47b46a1a6c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12713, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新经理想设计一只激励机制。", "corrected_sentence": "新经理想设计一套激励机制。", "error_description": "量词错误：“激励机制”是一套制度，量词应用“套”，“只”用于动物或成对器物中的一件，正确为“一套激励机制”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e155ee9-b460-47eb-b88b-f47b46a1a6c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12714, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "高收入", "is_correct": true, "explanation": "反义：“低收入”指收入水平低，“高收入”指收入水平高，二者相反。"}, {"text": "距离", "is_correct": false, "explanation": "不是反义：“距离”指空间或时间的间隔，与收入水平无关。"}, {"text": "河流", "is_correct": false, "explanation": "不是反义：“河流”指地表的水流，与收入水平无关。"}, {"text": "面包", "is_correct": false, "explanation": "不是反义：“面包”是食物，与收入水平无关。"}], "correct_answer": "高收入", "explanations": {"高收入": "反义：“低收入”指收入水平低，“高收入”指收入水平高，二者相反。", "距离": "不是反义：“距离”指空间或时间的间隔，与收入水平无关。", "河流": "不是反义：“河流”指地表的水流，与收入水平无关。", "面包": "不是反义：“面包”是食物，与收入水平无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1249cc0b-e936-4f6d-a885-4bc9b9606521') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12714, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "高收入", "is_correct": true, "explanation": "反义：“低收入”指收入水平低，“高收入”指收入水平高，二者相反。"}, {"text": "书本", "is_correct": false, "explanation": "不是反义：“书本”是学习用品，与收入水平无关。"}, {"text": "冬天", "is_correct": false, "explanation": "不是反义：“冬天”指季节，与收入水平无关。"}, {"text": "石头", "is_correct": false, "explanation": "不是反义：“石头”是矿物，与收入水平无关。"}], "correct_answer": "高收入", "explanations": {"高收入": "反义：“低收入”指收入水平低，“高收入”指收入水平高，二者相反。", "书本": "不是反义：“书本”是学习用品，与收入水平无关。", "冬天": "不是反义：“冬天”指季节，与收入水平无关。", "石头": "不是反义：“石头”是矿物，与收入水平无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1249cc0b-e936-4f6d-a885-4bc9b9606521') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12714, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "指个人或家庭的收入水平较低，通常低于社会平均水平。", "primary_collocate": null, "pronunciation": "dī shōu rù", "ipa": "ti˥ ʂoʊ˥ ɻu˥˩", "syllable_count": 3, "sentences": [{"text": "前沿的城市治理实践正试图通过法规强制与激励机制，确保低收入社区同样享有技术赋能的农业设施与高质量绿地，避免生态特权的固化。", "target_word": "低收入", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "政府给低收入家庭发放了生活补贴。", "target_word": "低收入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个社区住着很多低收入的人。", "target_word": "低收入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "低收入群体更需要稳定的工作。", "target_word": "低收入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的收入低于平均水平，属于低收入。", "target_word": "低收入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校为低收入学生减免了学费。", "target_word": "低收入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家正在提高低收入者的保障水平。", "target_word": "低收入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "低收入家庭的孩子也应该有机会上好大学。", "target_word": "低收入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市为低收入人群建了新住房。", "target_word": "低收入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "统计数据显示低收入家庭的支出主要用在吃饭上。", "target_word": "低收入", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "低收入者", "label": "复合词"}, {"form": "低收入群体", "label": "复合词"}], "register": "中性", "sense_fingerprint": "个人或家庭收入低于社会平均水平", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '23a895ae-04dc-425d-89b4-86e14f5ee5e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12714, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "低收入", "is_correct": true, "explanation": "正确：“低收入社区”指收入水平较低的社区，与句中的社会保障语境相符。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气社区”说不通，与句中的设施与绿地讨论无关。"}, {"text": "墨水", "is_correct": false, "explanation": "搭配：“享有”不能与“墨水”搭配，句子要说的是设施与资源。"}, {"text": "农药", "is_correct": false, "explanation": "语义：“农药社区”不成立，与句中的公共服务讨论无关。"}], "explanations": {"低收入": "正确：“低收入社区”指收入水平较低的社区，与句中的社会保障语境相符。", "天气": "语义：“天气社区”说不通，与句中的设施与绿地讨论无关。", "墨水": "搭配：“享有”不能与“墨水”搭配，句子要说的是设施与资源。", "农药": "语义：“农药社区”不成立，与句中的公共服务讨论无关。"}, "sentence_index": 0, "correct_answer": "低收入"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每个月的低收入是五千元。", "explanation": "这里应该用〈工资〉。“低收入”指收入水平较低的状况，不是具体的金额，不能说“是五千元”。"}, {"text": "他的低收入很高，买得起大房子。", "explanation": "这里应该用〈薪水〉。“薪水很高”说的是数额；“低收入”指收入水平偏低的状况，不能与“很高”搭配。"}, {"text": "他的低收入有五万元，足够养老了。", "explanation": "这里应该用〈积蓄〉。“低收入”指收入水平较低的状况，不是可以持有的钱款，不能说“有五万元”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1249cc0b-e936-4f6d-a885-4bc9b9606521') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12714, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "低收入", "is_correct": true, "explanation": "正确：“低收入者”指收入水平较低的人，与“保障水平”的语境相符。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色的保障水平”说不通，句子讨论的是人群的保障。"}, {"text": "手机", "is_correct": false, "explanation": "语义：“手机”不能作为保障对象，与句意不符。"}, {"text": "体温", "is_correct": false, "explanation": "搭配：“提高”不能与“体温”组合成保障水平。"}], "explanations": {"低收入": "正确：“低收入者”指收入水平较低的人，与“保障水平”的语境相符。", "颜色": "语义：“颜色的保障水平”说不通，句子讨论的是人群的保障。", "手机": "语义：“手机”不能作为保障对象，与句意不符。", "体温": "搭配：“提高”不能与“体温”组合成保障水平。"}, "sentence_index": 6, "correct_answer": "低收入"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家公司的低收入很高，年年增长。", "explanation": "这里应该用〈利润〉。“利润很高”说的是数额，“低收入”不能与“很高”搭配。"}, {"text": "这次比赛的低收入是十万元。", "explanation": "这里应该用〈奖金〉。“低收入”指收入水平较低的状况，不能用来说具体的金额，“奖金是十万元”才正确。"}, {"text": "这位老人的低收入很快乐。", "explanation": "这里应该用〈心情〉。“低收入”指收入水平偏低的状况，不是情绪，不能说“很快乐”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1249cc0b-e936-4f6d-a885-4bc9b9606521') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12714, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "社区里有很多很低收入家庭，需要帮助。", "corrected_sentence": "社区里有很多低收入家庭，需要帮助。", "error_description": "错误在修饰语：“低收入”修饰“家庭”时前面不能加“很”，应说“低收入家庭”，不能说“很低收入家庭”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1249cc0b-e936-4f6d-a885-4bc9b9606521') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12714, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "政府加大了对低收入群体们的扶持。", "corrected_sentence": "政府加大了对低收入群体的扶持。", "error_description": "错误在后缀：“群体”本身已表示人群的集合，后面不能再加“们”，应说“低收入群体”，不能说“低收入群体们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1249cc0b-e936-4f6d-a885-4bc9b9606521') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
