INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12716, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指为某个主体提供或赋予其完成某种任务或达成某种目标的能力、资源或条件。", "primary_collocate": null, "pronunciation": "fù néng", "ipa": "fu˥˩ nəŋ˧˥", "syllable_count": 2, "sentences": [{"text": "前沿的城市治理实践正试图通过法规强制与激励机制，确保低收入社区同样享有技术赋能的农业设施与高质量绿地，避免生态特权的固化。", "target_word": "赋能", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "区块链技术赋能点对点电力交易，家庭富余电能可直接售予社区用户；人工智能算法则通过气象数据与用电行为预测，实现跨区域源荷动态平衡。", "target_word": "赋能", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这家公司用数据赋能小商店。", "target_word": "赋能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新平台赋能农民，让他们直接卖货。", "target_word": "赋能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校用网络课程赋能偏远地区的老师。", "target_word": "赋能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "政府为小企业提供资金，赋能它们发展。", "target_word": "赋能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "好的培训能赋能年轻人，让他们更有信心。", "target_word": "赋能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个项目赋能了上百家小工厂。", "target_word": "赋能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "数字工具赋能医生，看病更快。", "target_word": "赋能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们想用新技术赋能当地的茶农。", "target_word": "赋能", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "赋能了", "label": "体标（了）"}, {"form": "赋能过", "label": "体标（过）"}, {"form": "賦能", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "给人或事物提供能力、资源或条件，使其能完成任务或达成目标", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd70a85e3-8683-4acb-9c19-ccb5efd1bd2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12716, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "赋能", "is_correct": true, "explanation": "赋能：给予能力或条件，与“技术”搭配修饰“农业设施”，符合句意。"}, {"text": "废弃", "is_correct": false, "explanation": "语义：“废弃”指弃置不用，与“享有”及“高质量”的正面语境矛盾。"}, {"text": "污染", "is_correct": false, "explanation": "语义：“污染”是损害，与“享有”及“确保同样享有”的语境相反。"}, {"text": "打破", "is_correct": false, "explanation": "搭配：“打破”不能修饰“农业设施”，“技术打破的设施”不成词组。"}], "explanations": {"赋能": "赋能：给予能力或条件，与“技术”搭配修饰“农业设施”，符合句意。", "废弃": "语义：“废弃”指弃置不用，与“享有”及“高质量”的正面语境矛盾。", "污染": "语义：“污染”是损害，与“享有”及“确保同样享有”的语境相反。", "打破": "搭配：“打破”不能修饰“农业设施”，“技术打破的设施”不成词组。"}, "sentence_index": 0, "correct_answer": "赋能"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天赋能跑步机，跑得很快。", "explanation": "这里应该用〈使用〉。赋能指给人或组织能力，不能用于操作器械，应用使用。"}, {"text": "学校赋能午餐，让学生吃得饱。", "explanation": "这里应该用〈提供〉。赋能的对象是人或组织，指给予能力；午餐是物品，应用提供。"}, {"text": "他在河边赋能了一座小桥。", "explanation": "这里应该用〈修建〉。赋能指给人或组织能力，不能用于建造，应用修建。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75032242-aa41-4dc6-a1af-4b3c4359a516') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12716, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "赋能", "is_correct": true, "explanation": "赋能：给予能力，符合“让他们更有信心”的积极语境。"}, {"text": "打击", "is_correct": false, "explanation": "语义：“打击”是压制、伤害，与“好的培训”及“更有信心”矛盾。"}, {"text": "忽悠", "is_correct": false, "explanation": "语域：“忽悠”是口语且含欺骗义，与书面语境及“好的培训”的正面评价不符。"}, {"text": "拖累", "is_correct": false, "explanation": "语义：“拖累”指使人受牵累，与“更有信心”的正面结果相反。"}], "explanations": {"赋能": "赋能：给予能力，符合“让他们更有信心”的积极语境。", "打击": "语义：“打击”是压制、伤害，与“好的培训”及“更有信心”矛盾。", "忽悠": "语域：“忽悠”是口语且含欺骗义，与书面语境及“好的培训”的正面评价不符。", "拖累": "语义：“拖累”指使人受牵累，与“更有信心”的正面结果相反。"}, "sentence_index": 6, "correct_answer": "赋能"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "农民在山上赋能了一大片树林。", "explanation": "这句想表达“种植”，即栽下树苗；赋能指给人或事物能力，不能用于栽植，此义应用〈种〉。"}, {"text": "这家商店主要赋能新鲜蔬菜。", "explanation": "这句表示“销售”，即售卖商品；赋能指给人或事物能力，不能用于货物买卖。"}, {"text": "他不小心赋能了杯子。", "explanation": "这句表示“摔碎”，即损坏物品；赋能不能用于此义，与杯子搭配不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75032242-aa41-4dc6-a1af-4b3c4359a516') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12716, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个平台没赋能了许多小店。", "corrected_sentence": "这个平台赋能了许多小店。", "error_description": "错误在于多加了否定词“没”。“没”与“了”不能同用，应删去“没”，说“这个平台赋能了许多小店”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75032242-aa41-4dc6-a1af-4b3c4359a516') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12716, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新政策会赋能得当地的小企业。", "corrected_sentence": "新政策会赋能当地的小企业。", "error_description": "错误在于动词“赋能”后直接加了“得”。“赋能”是及物动词，后接宾语时不能加“得”，应删去“得”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75032242-aa41-4dc6-a1af-4b3c4359a516') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12717, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "低质量", "is_correct": true, "explanation": "正确：“低质量”指品质差，与“品质优秀”的“高质量”相对。"}, {"text": "粗糙", "is_correct": false, "explanation": "“粗糙”说质地不光滑，与品质优劣不构成反义关系。"}, {"text": "陈旧", "is_correct": false, "explanation": "“陈旧”说过时，不是“高质量”的反义词。"}, {"text": "廉价", "is_correct": false, "explanation": "“廉价”说价格低，不是“高质量”的反义词。"}], "correct_answer": "低质量", "explanations": {"低质量": "正确：“低质量”指品质差，与“品质优秀”的“高质量”相对。", "粗糙": "“粗糙”说质地不光滑，与品质优劣不构成反义关系。", "陈旧": "“陈旧”说过时，不是“高质量”的反义词。", "廉价": "“廉价”说价格低，不是“高质量”的反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7543f63b-fd76-44ab-99eb-487ab45345c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12717, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "低质量", "is_correct": true, "explanation": "正确：“低质量”指品质差，与“高质量”相对。"}, {"text": "简陋", "is_correct": false, "explanation": "“简陋”说条件粗陋，不是“高质量”的反义词。"}, {"text": "老旧", "is_correct": false, "explanation": "“老旧”说过时，与品质优劣不构成反义。"}, {"text": "昂贵", "is_correct": false, "explanation": "“昂贵”说价格高，不是“高质量”的反义词。"}], "correct_answer": "低质量", "explanations": {"低质量": "正确：“低质量”指品质差，与“高质量”相对。", "简陋": "“简陋”说条件粗陋，不是“高质量”的反义词。", "老旧": "“老旧”说过时，与品质优劣不构成反义。", "昂贵": "“昂贵”说价格高，不是“高质量”的反义词。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7543f63b-fd76-44ab-99eb-487ab45345c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12717, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指物品或服务的品质优秀，达到很高标准。", "primary_collocate": null, "pronunciation": "gāo zhì liàng", "ipa": "kaʊ˥ ʈʂʅ˥˩ ljaŋ˥˩", "syllable_count": 3, "sentences": [{"text": "前沿的城市治理实践正试图通过法规强制与激励机制，确保低收入社区同样享有技术赋能的农业设施与高质量绿地，避免生态特权的固化。", "target_word": "高质量", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这家公司提供高质量的服务。", "target_word": "高质量", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们的目标是做出高质量的产品。", "target_word": "高质量", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了买到高质量的茶叶，他去了产地。", "target_word": "高质量", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家酒店一直提供高质量的服务，回头客很多。", "target_word": "高质量", "complexity_tier": "T3", "furigana": "zhè jiā jiǔ diàn yì zhí tí gōng gāo zhì liàng de fú wù, huí tóu kè hěn duō.", "sentence_source": "generated"}, {"text": "这本书是一本高质量的学术著作。", "target_word": "高质量", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个城市需要更多高质量的公共服务。", "target_word": "高质量", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板说，高质量的材料才能做出好家具。", "target_word": "高质量", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈只买高质量的食品，不管价格高不高。", "target_word": "高质量", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家工厂生产的每一件零件都是高质量的。", "target_word": "高质量", "complexity_tier": "T3", "furigana": "zhè jiā gōng chǎng shēng chǎn de měi yí jiàn líng jiàn dōu shì gāo zhì liàng de.", "sentence_source": "generated"}], "morphological_forms": [{"form": "高質量", "label": "繁体"}, {"form": "高质量发展", "label": "复合"}], "register": "书面", "sense_fingerprint": "物品或服务品质优秀、标准很高", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd042e930-7fd0-48af-9748-9ff8f70b3c62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12717, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "高质量", "is_correct": true, "explanation": "正确：“高质量绿地”说绿地的品质，与“同样享有”的平等要求相符。"}, {"text": "低档", "is_correct": false, "explanation": "语义：“低档”指等级低，与“确保……同样享有”的要求矛盾。"}, {"text": "荒废", "is_correct": false, "explanation": "语义：“荒废”指闲置不用、败坏，与“享有”的好设施和绿地相反，句意不通。"}, {"text": "陈旧", "is_correct": false, "explanation": "搭配：“陈旧”说过时，不能与“技术赋能”并列来描述绿地。"}], "explanations": {"高质量": "正确：“高质量绿地”说绿地的品质，与“同样享有”的平等要求相符。", "低档": "语义：“低档”指等级低，与“确保……同样享有”的要求矛盾。", "荒废": "语义：“荒废”指闲置不用、败坏，与“享有”的好设施和绿地相反，句意不通。", "陈旧": "搭配：“陈旧”说过时，不能与“技术赋能”并列来描述绿地。"}, "sentence_index": 0, "correct_answer": "高质量"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他身材很高质量，站在人群里很显眼。", "explanation": "这里应该用〈高大〉。身材高大说的是人的体格，“高质量”只用于物品或服务的品质。"}, {"text": "他跑步的速度很高质量，一下子就冲到了终点。", "explanation": "这里应该用〈快〉。“高质量”说物品或服务的品质，不能形容速度，速度快要说“快”。"}, {"text": "他的品德很高质量，大家都很尊敬他。", "explanation": "这里应该用〈高尚〉。“高质量”不用于品德，形容品德和精神境界要用“高尚”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7543f63b-fd76-44ab-99eb-487ab45345c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12717, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "高质量", "is_correct": true, "explanation": "正确：“更多高质量的公共服务”与“需要更多”的期望相符。"}, {"text": "私人", "is_correct": false, "explanation": "搭配：“公共服务”与“私人”对立，不能说“私人的公共服务”。"}, {"text": "劣质", "is_correct": false, "explanation": "语义：“劣质”与“需要更多”所期望的服务水平相反，句子说不通。"}, {"text": "落后", "is_correct": false, "explanation": "语义：“落后”说水平跟不上，与“需要更多”所要的好服务相矛盾。"}], "explanations": {"高质量": "正确：“更多高质量的公共服务”与“需要更多”的期望相符。", "私人": "搭配：“公共服务”与“私人”对立，不能说“私人的公共服务”。", "劣质": "语义：“劣质”与“需要更多”所期望的服务水平相反，句子说不通。", "落后": "语义：“落后”说水平跟不上，与“需要更多”所要的好服务相矛盾。"}, "sentence_index": 6, "correct_answer": "高质量"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台机器的效率很高质量，每分钟能包装两百个。", "explanation": "这里应该用〈高效〉。“高质量”说物品或服务的品质，设备的效率要用“高效”。"}, {"text": "他的棋艺很高质量，几乎没有对手。", "explanation": "这里应该用〈高明〉。“高质量”用于物品或服务，技艺水平要用“高明”。"}, {"text": "我今天的心情很高质量，特别开心。", "explanation": "这里应该用〈高兴〉。“高质量”只说物品或服务的品质，不能形容心情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7543f63b-fd76-44ab-99eb-487ab45345c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12717, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工人们高质量的完成了任务。", "corrected_sentence": "工人们高质量地完成了任务。", "error_description": "“高质量”修饰动词“完成”时作状语，应用“地”，说“高质量地完成”；“高质量的完成”误用了定语的“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7543f63b-fd76-44ab-99eb-487ab45345c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12717, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家餐厅的服务很越来越高质量了。", "corrected_sentence": "这家餐厅的服务越来越高质量了。", "error_description": "“越来越”本身已表示程度加深，前面不能再加程度副词“很”，应说“越来越高质量了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7543f63b-fd76-44ab-99eb-487ab45345c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12718, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7543f63b-fd76-44ab-99eb-487ab45345c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12718, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7543f63b-fd76-44ab-99eb-487ab45345c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12718, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "特权指个人或群体在特定范围内享有的、超出一般法律或规则的特殊权利或待遇。", "primary_collocate": null, "pronunciation": "tè quán", "ipa": "tʰɤ˥˩ tɕʰɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "前沿的城市治理实践正试图通过法规强制与激励机制，确保低收入社区同样享有技术赋能的农业设施与高质量绿地，避免生态特权的固化。", "target_word": "特权", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "法律面前，任何人都不能有特权。", "target_word": "特权", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他以为当了经理就有特权，可以不守规则。", "target_word": "特权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家银行给老客户一些特权。", "target_word": "特权", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "会员可以享受提前进场的特权。", "target_word": "特权", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "有些人利用特权，不排队就进去了。", "target_word": "特权", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司取消了高层的停车特权。", "target_word": "特权", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "哥哥是老大，有先选房间的特权。", "target_word": "特权", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们反对任何人用特权欺负别人。", "target_word": "特权", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位官员滥用特权，受到了调查。", "target_word": "特权", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "特權", "label": "繁体"}, {"form": "特权阶级", "label": "复合"}, {"form": "种", "label": "量词"}], "register": "书面", "sense_fingerprint": "超出一般规则的特殊权利或待遇", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd042e930-7fd0-48af-9748-9ff8f70b3c62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12718, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "特权", "is_correct": true, "explanation": "正确：“生态特权”指超出规则的特殊权利，被固化的正是这种特殊待遇。"}, {"text": "奖金", "is_correct": false, "explanation": "语义：“奖金”是一次性奖励，不会“固化”，与“避免……固化”的语境不合。"}, {"text": "工资", "is_correct": false, "explanation": "搭配：“固化”多用于制度、格局、偏见，不说“生态工资的固化”。"}, {"text": "学费", "is_correct": false, "explanation": "语义：“学费”与生态问题无关，句中“固化”的对象应是不公平的待遇。"}], "explanations": {"特权": "正确：“生态特权”指超出规则的特殊权利，被固化的正是这种特殊待遇。", "奖金": "语义：“奖金”是一次性奖励，不会“固化”，与“避免……固化”的语境不合。", "工资": "搭配：“固化”多用于制度、格局、偏见，不说“生态工资的固化”。", "学费": "语义：“学费”与生态问题无关，句中“固化”的对象应是不公平的待遇。"}, "sentence_index": 0, "correct_answer": "特权"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "每个公民都享有言论的特权，任何人都不能剥夺。", "explanation": "这里应该用〈权利〉。特权指超出一般规则、只给少数人的待遇；人人都享有的言论自由要说“权利”。"}, {"text": "他愿意承担更多的特权，帮助大家。", "explanation": "这里应该用〈责任〉。“承担”搭配责任、义务，特权是享有的，不能说承担。"}, {"text": "他的特权是口语很好，所以很快就被录取了。", "explanation": "这里应该用〈优势〉。特权指规则给予的特殊权利，不能指能力或条件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7543f63b-fd76-44ab-99eb-487ab45345c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12718, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "特权", "is_correct": true, "explanation": "正确：“停车特权”指高层享有的特殊待遇，取消的正是它。"}, {"text": "吟诗", "is_correct": false, "explanation": "搭配：“吟诗”是文艺活动，不能与“停车”搭配，“取消停车吟诗”说不通。"}, {"text": "讲座", "is_correct": false, "explanation": "语义：“讲座”与停车无关，不是能被取消的停车待遇。"}, {"text": "作业", "is_correct": false, "explanation": "语义：“作业”指学习任务，与高层的停车毫无关系。"}], "explanations": {"特权": "正确：“停车特权”指高层享有的特殊待遇，取消的正是它。", "吟诗": "搭配：“吟诗”是文艺活动，不能与“停车”搭配，“取消停车吟诗”说不通。", "讲座": "语义：“讲座”与停车无关，不是能被取消的停车待遇。", "作业": "语义：“作业”指学习任务，与高层的停车毫无关系。"}, "sentence_index": 6, "correct_answer": "特权"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "每个人都有纳税的特权，不能逃避。", "explanation": "这里应该用〈义务〉。纳税是人人都要履行的义务，特权指超出一般规则的待遇。"}, {"text": "这位老工人的特权是修理各种机器。", "explanation": "这里应该用〈特长〉。“特权”指只属于少数人的特殊权利或待遇，擅长修机器要说“特长”。"}, {"text": "他的特权是喜欢下棋，每天都下很久。", "explanation": "这里应该用〈爱好〉。“特权”指只属于少数人的权利，个人喜欢做的事要说“爱好”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7543f63b-fd76-44ab-99eb-487ab45345c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12718, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他获得了一只特权，可以提前进场。", "corrected_sentence": "他获得了一项特权，可以提前进场。", "error_description": "“特权”的量词应用“项”或“种”，不能用“只”，“只”多用于动物或成对的东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7543f63b-fd76-44ab-99eb-487ab45345c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12718, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位官员滥用了一项的特权，受到了调查。", "corrected_sentence": "这位官员滥用了一项特权，受到了调查。", "error_description": "数量短语“一项”后不能直接加“的”修饰名词，应说“一项特权”，不说“一项的特权”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7543f63b-fd76-44ab-99eb-487ab45345c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
