INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12719, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指与某事物完全相反或矛盾的另一方。", "primary_collocate": null, "pronunciation": "duì lì miàn", "ipa": "twei˥˩ li˥˩ mjɛn˥˩", "syllable_count": 3, "sentences": [{"text": "在此背景下，城市不再被视作自然的对立面，而是通过技术创新与制度设计，成为可持续性、粮食主权与经济活力协同演进的复杂适应系统。", "target_word": "对立面", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "他总是站在大家的对立面。", "target_word": "对立面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们不要把老板看成对立面。", "target_word": "对立面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两家公司成了对立面，很少合作。", "target_word": "对立面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不想站在父母的对立面。", "target_word": "对立面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把朋友当成了对立面。", "target_word": "对立面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他怕站到多数人的对立面。", "target_word": "对立面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这件事上，他们成了对立面。", "target_word": "对立面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师不是学生的对立面。", "target_word": "对立面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球迷把对手球队看作对立面。", "target_word": "对立面", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "与某一方相反或矛盾的另一方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '23a895ae-04dc-425d-89b4-86e14f5ee5e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12719, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "对立面", "is_correct": true, "explanation": "正确：“对立面”指与某方相反的一方，与“城市不再被视作自然的……”的语境相符。"}, {"text": "名称", "is_correct": false, "explanation": "语义：“被视作自然的名称”语义不通，“名称”不能表示立场或角色。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“被视作自然的颜色”语义不通，与句子的立场含义无关。"}, {"text": "节奏", "is_correct": false, "explanation": "搭配：“视作”后接事物或身份，“节奏”不能被“视作”。"}], "explanations": {"对立面": "正确：“对立面”指与某方相反的一方，与“城市不再被视作自然的……”的语境相符。", "名称": "语义：“被视作自然的名称”语义不通，“名称”不能表示立场或角色。", "颜色": "语义：“被视作自然的颜色”语义不通，与句子的立场含义无关。", "节奏": "搭配：“视作”后接事物或身份，“节奏”不能被“视作”。"}, "sentence_index": 0, "correct_answer": "对立面"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块布的对立面绣着一朵花。", "explanation": "这里应该用〈反面〉。对立面指立场或观点相反的一方，布的正反两面用反面。"}, {"text": "我家的对立面是一个超市。", "explanation": "这里应该用〈对面〉。对立面指立场相反的一方，不指地点的相对位置。"}, {"text": "这场比赛的对立面是一座体育馆。", "explanation": "这里应该用〈场地〉。对立面指立场相反的一方，比赛的场所要说场地。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1249cc0b-e936-4f6d-a885-4bc9b9606521') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12719, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "对立面", "is_correct": true, "explanation": "正确：“他怕站到多数人的对立面”，“对立面”指与多数人立场相反的一方，与句意相符。"}, {"text": "名字", "is_correct": false, "explanation": "语义：“站到多数人的名字”语义不通，“名字”不能表示立场。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“站到多数人的天气”语义不通，与句子的立场含义无关。"}, {"text": "座位", "is_correct": false, "explanation": "搭配：“站”不能带“座位”作宾语，应说“坐”。"}], "explanations": {"对立面": "正确：“他怕站到多数人的对立面”，“对立面”指与多数人立场相反的一方，与句意相符。", "名字": "语义：“站到多数人的名字”语义不通，“名字”不能表示立场。", "天气": "语义：“站到多数人的天气”语义不通，与句子的立场含义无关。", "座位": "搭配：“站”不能带“座位”作宾语，应说“坐”。"}, "sentence_index": 6, "correct_answer": "对立面"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们是好朋友，是彼此的对立面。", "explanation": "这里应该用〈伙伴〉。对立面指立场相反的一方，好朋友不能互称对立面。"}, {"text": "这座桥的对立面朝北，很长。", "explanation": "这里应该用〈方向〉。对立面不指物体的方位，桥的朝向应说方向。"}, {"text": "这幅画的对立面画着一只猫。", "explanation": "这里应该用〈背面〉。对立面指立场或观点相反的一方，画的另一面用背面。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1249cc0b-e936-4f6d-a885-4bc9b9606521') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12719, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两位同事成了很对立面。", "corrected_sentence": "两位同事成了对立面。", "error_description": "错误：“很对立面”。正确：“对立面”。“对立面”是名词，前面不能加程度副词“很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1249cc0b-e936-4f6d-a885-4bc9b9606521') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12719, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们成了对立面的。", "corrected_sentence": "他们成了对立面。", "error_description": "错误：“对立面的”。正确：“对立面”。句末多出的“的”使句子不完整，“对立面”后不能直接加“的”结束句子。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1249cc0b-e936-4f6d-a885-4bc9b9606521') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
