INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12723, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事物的基础或根本，比喻事物发展的起点或最重要的部分。", "primary_collocate": null, "pronunciation": "gēn jī", "ipa": "kən˥ tɕi˥", "syllable_count": 2, "sentences": [{"text": "房地产的价值根基，正从单一的物理空间占有，转向对生态服务流与社区福祉的动态贡献能力。", "target_word": "根基", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "好习惯是成功的根基。", "target_word": "根基", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "诚信是做生意的根基。", "target_word": "根基", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这家公司的根基很深，不怕困难。", "target_word": "根基", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "只有打好根基，才能走得远。", "target_word": "根基", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "教育是国家发展的根基。", "target_word": "根基", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "家庭是孩子成长的根基。", "target_word": "根基", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个品牌在市场上还没有稳定的根基。", "target_word": "根基", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在这座城市打下了根基，生活越来越好。", "target_word": "根基", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，语法和词汇是学好汉语的根基。", "target_word": "根基", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "比喻事物发展的基础和根本", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd042e930-7fd0-48af-9748-9ff8f70b3c62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12723, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "根基", "is_correct": true, "explanation": "根基（gēn jī）是正确答案，指事物的基础。"}, {"text": "根据", "is_correct": false, "explanation": "根据（gēnjù）与根基只有第二音节韵母不同（i 与 ü），意思是依据，声音相近。"}, {"text": "感激", "is_correct": false, "explanation": "感激（gǎnjī）与根基的第一音节韵母不同（en 与 an）且声调改变，意思是感谢，不是同一个词。"}, {"text": "根系", "is_correct": false, "explanation": "根系（gēnxì）第二音节声母 x 与 j 不同，意思是植物根的整体，与根基声音相近。"}, {"text": "根治", "is_correct": false, "explanation": "根治（gēnzhì）第二音节声母 zh 与 j 不同，意思是彻底治好，与根基声音相近。"}], "explanations": {"根基": "根基（gēn jī）是正确答案，指事物的基础。", "根据": "根据（gēnjù）与根基只有第二音节韵母不同（i 与 ü），意思是依据，声音相近。", "感激": "感激（gǎnjī）与根基的第一音节韵母不同（en 与 an）且声调改变，意思是感谢，不是同一个词。", "根系": "根系（gēnxì）第二音节声母 x 与 j 不同，意思是植物根的整体，与根基声音相近。", "根治": "根治（gēnzhì）第二音节声母 zh 与 j 不同，意思是彻底治好，与根基声音相近。"}, "sentence_index": null, "correct_answer": "根基"}, "level_3": {"options": [{"text": "根基", "is_correct": true, "explanation": "根基：指事物的基础，这里说房地产的价值基础，与后文“贡献能力”的语境相合。"}, {"text": "外壳", "is_correct": false, "explanation": "语义：外壳是包在外面的硬层，不能作为价值的基础，与“动态贡献能力”不合。"}, {"text": "账单", "is_correct": false, "explanation": "语义：账单是记录费用的单子，与“物理空间占有”“贡献能力”的意思都不合。"}, {"text": "老底", "is_correct": false, "explanation": "语域：“老底”是口语词，指家底或底细，与这段书面语的语域不合。"}], "explanations": {"根基": "根基：指事物的基础，这里说房地产的价值基础，与后文“贡献能力”的语境相合。", "外壳": "语义：外壳是包在外面的硬层，不能作为价值的基础，与“动态贡献能力”不合。", "账单": "语义：账单是记录费用的单子，与“物理空间占有”“贡献能力”的意思都不合。", "老底": "语域：“老底”是口语词，指家底或底细，与这段书面语的语域不合。"}, "sentence_index": 0, "correct_answer": "根基"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把根基存进了银行。", "explanation": "这里应该用〈存款〉。根基指事物的基础，不能存进银行，说钱存在银行要用存款。"}, {"text": "这家公司的根基下周要搬到楼上办公。", "explanation": "这里应该用〈办公室〉。根基指事物的基础，不能搬到楼上办公，说办公的地方要用办公室。"}, {"text": "她在行业里打下了一把根基。", "explanation": "量词误用：根基不用“把”（“把”用于有柄的物品），应说“打下了根基”或“打下坚实的根基”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7543f63b-fd76-44ab-99eb-487ab45345c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12723, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "根基", "is_correct": true, "explanation": "根基：指事物的基础，这里说家庭是孩子成长的基础，语义相合。"}, {"text": "学费", "is_correct": false, "explanation": "语义：学费是上学时交的钱，不是孩子成长的基础，与“家庭”的说法不合。"}, {"text": "冠军", "is_correct": false, "explanation": "语义：冠军指比赛的第一名，不能作为孩子成长的基础。"}, {"text": "面孔", "is_correct": false, "explanation": "体貌：面孔指人的外貌，不能说家庭是孩子成长的外貌，与句意不合。"}], "explanations": {"根基": "根基：指事物的基础，这里说家庭是孩子成长的基础，语义相合。", "学费": "语义：学费是上学时交的钱，不是孩子成长的基础，与“家庭”的说法不合。", "冠军": "语义：冠军指比赛的第一名，不能作为孩子成长的基础。", "面孔": "体貌：面孔指人的外貌，不能说家庭是孩子成长的外貌，与句意不合。"}, "sentence_index": 6, "correct_answer": "根基"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个故事的根基很好吃。", "explanation": "这里应该用〈情节〉。根基指事物的基础，不能形容故事好吃；说故事精彩要用情节。"}, {"text": "他的人生根基在去年就结束了。", "explanation": "这里应该用〈结局〉或〈终结〉。根基指支撑事物的基础，不能说“结束”，说人生走到尽头要用结局或终结。"}, {"text": "她在这个圈子里有一条根基。", "explanation": "量词误用：根基不用“条”（“条”用于细长的事物），应说“她在这个圈子里有一定的根基”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7543f63b-fd76-44ab-99eb-487ab45345c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12723, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次改革为公司奠定了一只坚实的根基。", "corrected_sentence": "这次改革为公司奠定了坚实的根基。", "error_description": "量词错误：“根基”前不用“只”（“只”用于动物等），应去掉“一只”，直接说“坚实的根基”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7543f63b-fd76-44ab-99eb-487ab45345c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12723, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "多背单词是学好外语根基。", "corrected_sentence": "多背单词是学好外语的根基。", "error_description": "“的”脱漏：“学好外语”修饰“根基”时须用“的”，应说“学好外语的根基”，省略“的”就不通顺。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7543f63b-fd76-44ab-99eb-487ab45345c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
