INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12725, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指拥有或控制某物，使其属于自己。", "primary_collocate": null, "pronunciation": "zhàn yǒu", "ipa": "ʈʂan˥˩ jou˨˩˦", "syllable_count": 2, "sentences": [{"text": "房地产的价值根基，正从单一的物理空间占有，转向对生态服务流与社区福祉的动态贡献能力。", "target_word": "占有", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这家公司占有一半的市场。", "target_word": "占有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他占有这块地已经十年了。", "target_word": "占有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家占有大量的石油资源。", "target_word": "占有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店占有这条街最好的位置。", "target_word": "占有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们占有这座城市三分之一的土地。", "target_word": "占有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种饮料占有最大的市场份额。", "target_word": "占有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们家占有这片山林。", "target_word": "占有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家企业占有这项技术的全部专利。", "target_word": "占有", "complexity_tier": "T3", "furigana": "zhè jiā qǐyè zhànyǒu zhè xiàng jìshù de quánbù zhuānlì", "sentence_source": "generated"}, {"text": "这家企业占有很高的市场份额。", "target_word": "占有", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "占有了", "label": "体标"}, {"form": "占有着", "label": "体标"}, {"form": "占有过", "label": "体标"}, {"form": "占有率", "label": "复合"}], "register": "书面", "sense_fingerprint": "拥有或控制某物，如市场、土地、资源", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3b355173-4ded-4ba2-b8ef-c4046b577508') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12725, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "占有", "is_correct": true, "explanation": "正确：“从单一的物理空间占有”指对空间的拥有或控制，与后文“转向……贡献能力”的语境相符。"}, {"text": "繁殖", "is_correct": false, "explanation": "语义：繁殖指生物产生后代，物理空间不能繁殖，句子不通。"}, {"text": "呼吸", "is_correct": false, "explanation": "搭配：“呼吸”不能与“物理空间”搭配，句子的搭配不当。"}, {"text": "发酵", "is_correct": false, "explanation": "语义：发酵是微生物的作用，与物理空间无关，句子不通。"}], "explanations": {"占有": "正确：“从单一的物理空间占有”指对空间的拥有或控制，与后文“转向……贡献能力”的语境相符。", "繁殖": "语义：繁殖指生物产生后代，物理空间不能繁殖，句子不通。", "呼吸": "搭配：“呼吸”不能与“物理空间”搭配，句子的搭配不当。", "发酵": "语义：发酵是微生物的作用，与物理空间无关，句子不通。"}, "sentence_index": 0, "correct_answer": "占有"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他占有很强的学习能力。", "explanation": "这里应该用〈具有〉。占有指拥有或控制实物、资源，抽象的能力要用具有。"}, {"text": "他占有了一个好消息。", "explanation": "这里应该用〈得到〉。占有指拥有或控制实物、资源，消息不能被占有，要说得到。"}, {"text": "他占有了金奖。", "explanation": "这里应该用〈获得〉。占有不能用于奖项；取得奖项要说获得。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '776b36fe-5714-4c91-a872-cd46e51e87e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12725, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "占有", "is_correct": true, "explanation": "正确：“占有最大的市场份额”指拥有或控制市场，与句子语境相符。"}, {"text": "抚养", "is_correct": false, "explanation": "语义：抚养的对象是人或动物，市场份额不能被抚养，句子不通。"}, {"text": "修剪", "is_correct": false, "explanation": "语义：修剪指剪去多余的部分，与市场份额无关，句子不通。"}, {"text": "诞生", "is_correct": false, "explanation": "配价：“诞生”是不及物动词，不能带“最大的市场份额”作宾语。"}], "explanations": {"占有": "正确：“占有最大的市场份额”指拥有或控制市场，与句子语境相符。", "抚养": "语义：抚养的对象是人或动物，市场份额不能被抚养，句子不通。", "修剪": "语义：修剪指剪去多余的部分，与市场份额无关，句子不通。", "诞生": "配价：“诞生”是不及物动词，不能带“最大的市场份额”作宾语。"}, "sentence_index": 6, "correct_answer": "占有"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在路上占有了老朋友。", "explanation": "这里应该用〈遇到〉。占有用于物品或资源，不能用于人；在路上碰见人要说遇到。"}, {"text": "他占有了这个责任。", "explanation": "这里应该用〈承担〉。占有指控制物品或资源，责任要说承担。"}, {"text": "公司占有了很大的进步。", "explanation": "这里应该用〈取得〉。占有指控制某物，进步是成果，要说取得。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '776b36fe-5714-4c91-a872-cd46e51e87e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12725, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家工厂正在占有了很大的一块土地。", "corrected_sentence": "这家工厂正在占有很大的一块土地。", "error_description": "“正在占有了”错误，应为“正在占有”。“正在”表示动作进行中，与表示完成的“了”不能同用。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '776b36fe-5714-4c91-a872-cd46e51e87e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12725, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家公司很占有当地大部分的市场。", "corrected_sentence": "这家公司占有当地大部分的市场。", "error_description": "“很占有”错误，应为“占有”。“占有”是动词，不能直接受程度副词“很”修饰，应直接说“占有”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '776b36fe-5714-4c91-a872-cd46e51e87e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
