INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12728, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "福祉指幸福、福气，多用于正式场合。", "primary_collocate": null, "pronunciation": "fú zhǐ", "ipa": "fu˧˥ ʈʂʅ˨˩˦", "syllable_count": 2, "sentences": [{"text": "房地产的价值根基，正从单一的物理空间占有，转向对生态服务流与社区福祉的动态贡献能力。", "target_word": "福祉", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "政府应该关心人民的福祉。", "target_word": "福祉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这项政策增进了老人的福祉。", "target_word": "福祉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "教育关系到下一代的福祉。", "target_word": "福祉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要为全体市民谋福祉。", "target_word": "福祉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一生致力于增进社会福祉。", "target_word": "福祉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "提升居民福祉是这个项目的目标。", "target_word": "福祉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "保护环境就是保护子孙的福祉。", "target_word": "福祉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司不能只追求利润，也要考虑员工的福祉。", "target_word": "福祉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "基金会致力于改善儿童福祉。", "target_word": "福祉", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "正式", "sense_fingerprint": "幸福、福气（正式用语）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd042e930-7fd0-48af-9748-9ff8f70b3c62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12728, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "福祉", "is_correct": true, "explanation": "福祉 fú zhǐ：幸福、福气，是本词。"}, {"text": "复制", "is_correct": false, "explanation": "复制 fù zhì：两个音节的声调都不同，意思是照原样做出一份，与福祉声音相近。"}, {"text": "扶持", "is_correct": false, "explanation": "扶持 fú chí：声母由 zh 变为 ch，声调也不同，意思是扶助支持。"}, {"text": "废纸", "is_correct": false, "explanation": "废纸 fèi zhǐ：韵母由 u 变为 ei，声调也不同，意思是没用的纸。"}, {"text": "肤质", "is_correct": false, "explanation": "肤质 fū zhì：两个音节的声调都不同，意思是皮肤的质地。"}], "explanations": {"福祉": "福祉 fú zhǐ：幸福、福气，是本词。", "复制": "复制 fù zhì：两个音节的声调都不同，意思是照原样做出一份，与福祉声音相近。", "扶持": "扶持 fú chí：声母由 zh 变为 ch，声调也不同，意思是扶助支持。", "废纸": "废纸 fèi zhǐ：韵母由 u 变为 ei，声调也不同，意思是没用的纸。", "肤质": "肤质 fū zhì：两个音节的声调都不同，意思是皮肤的质地。"}, "sentence_index": null, "correct_answer": "福祉"}, "level_3": {"options": [{"text": "福祉", "is_correct": true, "explanation": "正确：社区福祉指社区居民的幸福与利益，与前句的“生态服务”和“贡献能力”相合。"}, {"text": "价格", "is_correct": false, "explanation": "语义：“价格”是交易中的金额，与“社区……贡献能力”的福利内涵不符。"}, {"text": "垃圾", "is_correct": false, "explanation": "语义：“垃圾”是废弃物，与“价值根基”和正面的贡献语境相悖。"}, {"text": "停车场", "is_correct": false, "explanation": "搭配：“贡献能力”的对象应是人或社会利益，“停车场”是设施，不能作为贡献的对象。"}], "explanations": {"福祉": "正确：社区福祉指社区居民的幸福与利益，与前句的“生态服务”和“贡献能力”相合。", "价格": "语义：“价格”是交易中的金额，与“社区……贡献能力”的福利内涵不符。", "垃圾": "语义：“垃圾”是废弃物，与“价值根基”和正面的贡献语境相悖。", "停车场": "搭配：“贡献能力”的对象应是人或社会利益，“停车场”是设施，不能作为贡献的对象。"}, "sentence_index": 0, "correct_answer": "福祉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公司为员工发了很好的福祉，大家都很满意。", "explanation": "这里应该用〈福利〉。福利指员工得到的具体待遇，福祉指人的整体幸福，不用于具体的待遇。"}, {"text": "这次谈判我们争取到了很大的福祉。", "explanation": "这里应该用〈利益〉。福祉指人的幸福，谈判争取到的得失要用利益，不用福祉。"}, {"text": "这家商店把店里的福祉都卖光了。", "explanation": "这里应该用〈商品〉。福祉指人的幸福，不能像货物一样卖光；店里的货物要用商品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7543f63b-fd76-44ab-99eb-487ab45345c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12728, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "福祉", "is_correct": true, "explanation": "福祉 fú zhǐ：幸福、福气，是本词。"}, {"text": "服饰", "is_correct": false, "explanation": "服饰 fú shì：第二音节声母由 zh 变为 sh，声调也不同，意思是衣服和装饰品。"}, {"text": "股指", "is_correct": false, "explanation": "股指 gǔ zhǐ：声母由 f 变为 g，声调也不同，意思是股票指数。"}, {"text": "故址", "is_correct": false, "explanation": "故址 gù zhǐ：声母由 f 变为 g，声调也不同，意思是旧址、遗址。"}, {"text": "扶志", "is_correct": false, "explanation": "扶志 fú zhì：第二音节由第三声变为第四声，意思是扶助意志。"}], "explanations": {"福祉": "福祉 fú zhǐ：幸福、福气，是本词。", "服饰": "服饰 fú shì：第二音节声母由 zh 变为 sh，声调也不同，意思是衣服和装饰品。", "股指": "股指 gǔ zhǐ：声母由 f 变为 g，声调也不同，意思是股票指数。", "故址": "故址 gù zhǐ：声母由 f 变为 g，声调也不同，意思是旧址、遗址。", "扶志": "扶志 fú zhì：第二音节由第三声变为第四声，意思是扶助意志。"}, "sentence_index": null, "correct_answer": "福祉"}, "level_3": {"options": [{"text": "福祉", "is_correct": true, "explanation": "正确：居民福祉指居民的幸福与利益，与“居民”和“项目目标”相合。"}, {"text": "恩情", "is_correct": false, "explanation": "搭配：“提升”不能与“恩情”搭配，恩情是要报答的，不能被提升。"}, {"text": "树木", "is_correct": false, "explanation": "搭配：“提升”用于质量或水平，“居民树木”没有意义，树木不能作为提升的对象。"}, {"text": "蚊子", "is_correct": false, "explanation": "语义：蚊子是害虫，项目不会以提升蚊子为目标，与语境不符。"}], "explanations": {"福祉": "正确：居民福祉指居民的幸福与利益，与“居民”和“项目目标”相合。", "恩情": "搭配：“提升”不能与“恩情”搭配，恩情是要报答的，不能被提升。", "树木": "搭配：“提升”用于质量或水平，“居民树木”没有意义，树木不能作为提升的对象。", "蚊子": "语义：蚊子是害虫，项目不会以提升蚊子为目标，与语境不符。"}, "sentence_index": 6, "correct_answer": "福祉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家公司给社区带来了一座福祉。", "explanation": "这里不该用〈座〉，应当用〈种〉。座用于山、房屋等大型固定的东西，福祉是抽象的，不能这样计量。"}, {"text": "政府给每家每户送了一颗福祉。", "explanation": "这里不该用〈颗〉，应当用〈种〉。颗用于粒状或圆形的小东西，不能用来计量福祉。"}, {"text": "这个基金会给孩子们留下了一把福祉。", "explanation": "这里不该用〈把〉，应当用〈种〉。把用于有柄或可握的东西，不能用来计量福祉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7543f63b-fd76-44ab-99eb-487ab45345c5') 