INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12728, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这项计划带来了一颗福祉。", "corrected_sentence": "这项计划带来了很多福祉。", "error_description": "量词错误：「颗」用于粒状的小东西，不能用来计量福祉，应说「很多福祉」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7543f63b-fd76-44ab-99eb-487ab45345c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12728, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位市长一直市民谋福祉。", "corrected_sentence": "这位市长一直为市民谋福祉。", "error_description": "介词缺失：“为市民”表示对象，不能省去“为”，应说“为市民谋福祉”，不能说“市民谋福祉”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7543f63b-fd76-44ab-99eb-487ab45345c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12730, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "新", "is_correct": true, "explanation": "“新”与“老”在存在时间长的意思上相反。"}, {"text": "快", "is_correct": false, "explanation": "“快”形容速度，与“老”的时间义没有反义关系。"}, {"text": "高", "is_correct": false, "explanation": "“高”形容高度，与“老”的时间义没有反义关系。"}, {"text": "厚", "is_correct": false, "explanation": "“厚”形容厚度，与“老”的时间义没有反义关系。"}], "correct_answer": "新", "explanations": {"新": "“新”与“老”在存在时间长的意思上相反。", "快": "“快”形容速度，与“老”的时间义没有反义关系。", "高": "“高”形容高度，与“老”的时间义没有反义关系。", "厚": "“厚”形容厚度，与“老”的时间义没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b807295-70ef-4a27-b0f7-f6022d1a5a9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12730, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "新", "is_correct": true, "explanation": "“新”与“老”在存在时间长的意思上相反。"}, {"text": "轻", "is_correct": false, "explanation": "“轻”形容重量，与“老”的时间义没有反义关系。"}, {"text": "亮", "is_correct": false, "explanation": "“亮”形容光线，与“老”的时间义没有反义关系。"}, {"text": "宽", "is_correct": false, "explanation": "“宽”形容宽度，与“老”的时间义没有反义关系。"}], "correct_answer": "新", "explanations": {"新": "“新”与“老”在存在时间长的意思上相反。", "轻": "“轻”形容重量，与“老”的时间义没有反义关系。", "亮": "“亮”形容光线，与“老”的时间义没有反义关系。", "宽": "“宽”形容宽度，与“老”的时间义没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b807295-70ef-4a27-b0f7-f6022d1a5a9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12730, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指程度深、时间长或经验丰富。", "primary_collocate": null, "pronunciation": "lǎo", "ipa": "lɑʊ˨˩˦", "syllable_count": 1, "sentences": [{"text": "在很干的地方，人们有老方法用水。", "target_word": "老", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "这座房子很老，下雨时会漏水。", "target_word": "老", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是老医生，看病的经验很丰富。", "target_word": "老", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这棵树太老了，今年没有长叶子。", "target_word": "老", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老农民种了五十年地，知道什么时候下雨。", "target_word": "老", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是老工人，修机器又快又好。", "target_word": "老", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老厨师做菜又快又好吃。", "target_word": "老", "complexity_tier": "T3", "furigana": "lǎo chúshī zuò cài yòu kuài yòu hǎochī", "sentence_source": "generated"}, {"text": "这条街上有很多老房子，都有一百年了。", "target_word": "老", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我听的是一首老歌，二十年前很有名。", "target_word": "老", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷的手机很老，只能打电话。", "target_word": "老", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "老了", "label": "体标"}], "register": "中性", "sense_fingerprint": "老：存在的时间长，或经验丰富", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e2dde96-c6b3-456a-92c6-668f8966c4d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12730, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "老", "is_correct": true, "explanation": "老 lǎo：存在的时间长，或经验丰富。"}, {"text": "劳", "is_correct": false, "explanation": "láo（第二声）与 lǎo 声调不同，意思是劳动。"}, {"text": "烙", "is_correct": false, "explanation": "lào（第四声）与 lǎo 声调不同，意思是用火烤。"}, {"text": "脑", "is_correct": false, "explanation": "nǎo 与 lǎo 声母不同（n 与 l），意思是大脑。"}], "explanations": {"老": "老 lǎo：存在的时间长，或经验丰富。", "劳": "láo（第二声）与 lǎo 声调不同，意思是劳动。", "烙": "lào（第四声）与 lǎo 声调不同，意思是用火烤。", "脑": "nǎo 与 lǎo 声母不同（n 与 l），意思是大脑。"}, "sentence_index": null, "correct_answer": "老"}, "level_3": {"options": [{"text": "老", "is_correct": true, "explanation": "“老方法”指存在时间长的传统方法，与句中的语境相符。"}, {"text": "湿", "is_correct": false, "explanation": "语义：“很干的地方”与“湿”矛盾，“湿方法用水”说不通。"}, {"text": "年轻", "is_correct": false, "explanation": "语义：“年轻”只用于人或年龄，不能修饰“方法”。"}, {"text": "慢", "is_correct": false, "explanation": "搭配：“慢方法”不是固定说法，与“用水”的语境不搭。"}], "explanations": {"老": "“老方法”指存在时间长的传统方法，与句中的语境相符。", "湿": "语义：“很干的地方”与“湿”矛盾，“湿方法用水”说不通。", "年轻": "语义：“年轻”只用于人或年龄，不能修饰“方法”。", "慢": "搭配：“慢方法”不是固定说法，与“用水”的语境不搭。"}, "sentence_index": 0, "correct_answer": "老"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位工人操作机器很老，从不出错。", "explanation": "这里应该用〈熟练〉。「老」形容东西存在的时间长或人的经验丰富，不说操作机器很老；操作的熟练程度要用「熟练」。"}, {"text": "这里离市中心很老，骑车要一个小时。", "explanation": "这里应该用〈远〉。「老远」可以说，但「很老」不用来形容距离；说距离远要用「远」。"}, {"text": "这件事已经过去很老了，大家都忘了。", "explanation": "这里应该用〈久〉。「老」形容东西或人的状态，不说事情过去的时间，表示时间长要用「久」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b807295-70ef-4a27-b0f7-f6022d1a5a9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12730, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "老", "is_correct": true, "explanation": "老 lǎo：存在的时间长，或经验丰富。"}, {"text": "牢", "is_correct": false, "explanation": "láo（第二声）与 lǎo 声调不同，意思是监狱。"}, {"text": "涝", "is_correct": false, "explanation": "lào（第四声）与 lǎo 声调不同，意思是雨水过多造成的积水。"}, {"text": "恼", "is_correct": false, "explanation": "nǎo（第三声）与 lǎo 声母不同（n 与 l），意思是生气。"}], "explanations": {"老": "老 lǎo：存在的时间长，或经验丰富。", "牢": "láo（第二声）与 lǎo 声调不同，意思是监狱。", "涝": "lào（第四声）与 lǎo 声调不同，意思是雨水过多造成的积水。", "恼": "nǎo（第三声）与 lǎo 声母不同（n 与 l），意思是生气。"}, "sentence_index": null, "correct_answer": "老"}, "level_3": {"options": [{"text": "老", "is_correct": true, "explanation": "“老厨师”指经验丰富的厨师，与句中的语境相符。"}, {"text": "慢", "is_correct": false, "explanation": "语义：“慢厨师”与后半句“做菜又快又好吃”矛盾。"}, {"text": "笨", "is_correct": false, "explanation": "语义：“笨”形容能力差，与“做菜又快又好吃”矛盾。"}, {"text": "懒", "is_correct": false, "explanation": "搭配：“懒”形容性格，与“做菜又快又好吃”的描述不搭。"}], "explanations": {"老": "“老厨师”指经验丰富的厨师，与句中的语境相符。", "慢": "语义：“慢厨师”与后半句“做菜又快又好吃”矛盾。", "笨": "语义：“笨”形容能力差，与“做菜又快又好吃”矛盾。", "懒": "搭配：“懒”形容性格，与“做菜又快又好吃”的描述不搭。"}, "sentence_index": 6, "correct_answer": "老"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的数学成绩很老，这次又考了第一名。", "explanation": "这里应该用〈高〉。「老」形容东西存在的时间长或人的经验丰富，不用来形容成绩的好坏；成绩好要用「高」。"}, {"text": "今天的天气很老，适合出去玩。", "explanation": "这里应该用〈好〉。「老」指人或东西存在的时间长，不用来形容天气；天气好坏要用「好」。"}, {"text": "他写字很老，一分钟就写完了。", "explanation": "这里应该用〈快〉。「老」形容东西存在的时间长或人的经验丰富，不用来形容动作的速度；写得快要用「快」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b807295-70ef-4a27-b0f7-f6022d1a5a9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12730, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这棵树已经老了了，不结果了。", "corrected_sentence": "这棵树已经老了，不结果了。", "error_description": "“老了”后面不能再加“了”。正确的说法是「这棵树已经老了，不结果了」，错误在多加了一个“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b807295-70ef-4a27-b0f7-f6022d1a5a9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12730, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那辆自行车很老过，但是还能骑。", "corrected_sentence": "那辆自行车很老，但是还能骑。", "error_description": "“老”后面不能用“过”表示经历，应去掉“过”，说「那辆自行车很老，但是还能骑」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b807295-70ef-4a27-b0f7-f6022d1a5a9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
