INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12736, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "种植农作物的土地。", "primary_collocate": null, "pronunciation": "tián", "ipa": "tʰiɛn˧˥", "syllable_count": 1, "sentences": [{"text": "田在低的地方，水不会跑掉。", "target_word": "田", "complexity_tier": "T2", "sentence_source": "mined"}, {"text": "爷爷每天早上去田里工作。", "target_word": "田", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这块田很大，种着绿色的菜。", "target_word": "田", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨以后，田里有很多水。", "target_word": "田", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我家的田在河的旁边。", "target_word": "田", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "农民在田里种稻子，秋天就有吃的。", "target_word": "田", "complexity_tier": "T3", "furigana": "nóng mín zài tián lǐ zhòng dào zi, qiū tiān jiù yǒu chī de.", "sentence_source": "generated"}, {"text": "那片田里的麦子黄了。", "target_word": "田", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "春天，他们在田里种上了玉米。", "target_word": "田", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这块田太干了，要给它浇水。", "target_word": "田", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "田里的牛慢慢地走着。", "target_word": "田", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "块", "label": "量词"}, {"form": "片", "label": "量词"}], "register": "中性", "sense_fingerprint": "种植农作物的土地", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e2dde96-c6b3-456a-92c6-668f8966c4d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12736, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "田", "is_correct": true, "explanation": "田指种植农作物的土地，读 tián（阳平）。"}, {"text": "天", "is_correct": false, "explanation": "天（tiān，阴平）与 tián（阳平）声调不同，意思是天空。"}, {"text": "添", "is_correct": false, "explanation": "添（tiān，阴平）与 tián（阳平）声调不同，意思是增加。"}, {"text": "年", "is_correct": false, "explanation": "年（nián）与 tián 声母不同（n/t），意思是年份。"}, {"text": "谈", "is_correct": false, "explanation": "谈（tán）与 tián 少了中间的 i，意思是谈话。"}], "explanations": {"田": "田指种植农作物的土地，读 tián（阳平）。", "天": "天（tiān，阴平）与 tián（阳平）声调不同，意思是天空。", "添": "添（tiān，阴平）与 tián（阳平）声调不同，意思是增加。", "年": "年（nián）与 tián 声母不同（n/t），意思是年份。", "谈": "谈（tán）与 tián 少了中间的 i，意思是谈话。"}, "sentence_index": null, "correct_answer": "田"}, "level_3": {"options": [{"text": "田", "is_correct": true, "explanation": "正确：田指低洼处的农田，能留住水，句意通顺。"}, {"text": "河", "is_correct": false, "explanation": "语义：河里的水是流动的，不会留在低处，与“水不会跑掉”矛盾。"}, {"text": "山", "is_correct": false, "explanation": "体貌：山通常位于高处，与“低的地方”不符。"}, {"text": "云", "is_correct": false, "explanation": "语义：云在高空，与“低的地方”矛盾。"}], "explanations": {"田": "正确：田指低洼处的农田，能留住水，句意通顺。", "河": "语义：河里的水是流动的，不会留在低处，与“水不会跑掉”矛盾。", "山": "体貌：山通常位于高处，与“低的地方”不符。", "云": "语义：云在高空，与“低的地方”矛盾。"}, "sentence_index": 0, "correct_answer": "田"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天走路去田里上学。", "explanation": "这里应该用〈学校〉。田指种庄稼的地，上学的地方是学校，不能说去田里上学。"}, {"text": "我们在田里玩电脑游戏。", "explanation": "这里应该用〈客厅〉。田指种庄稼的地，玩电脑游戏应在室内，不能说在田里。"}, {"text": "我家有一只田，在河边。", "explanation": "这里应该用〈块〉或〈片〉。“只”用于动物，田是土地，不能用它来计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b807295-70ef-4a27-b0f7-f6022d1a5a9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12736, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "田", "is_correct": true, "explanation": "田指种植农作物的土地，读 tián（阳平）。"}, {"text": "舔", "is_correct": false, "explanation": "舔（tiǎn，第三声）与 tián（第二声）声调不同，意思是用舌头碰。"}, {"text": "连", "is_correct": false, "explanation": "连（lián）与 tián 声母不同（t/l），意思是连接。"}, {"text": "闲", "is_correct": false, "explanation": "闲（xián）与 tián 声母不同（t/x），意思是空闲。"}, {"text": "咸", "is_correct": false, "explanation": "咸（xián）与 tián 声母不同（t/x），意思是味道咸。"}], "explanations": {"田": "田指种植农作物的土地，读 tián（阳平）。", "舔": "舔（tiǎn，第三声）与 tián（第二声）声调不同，意思是用舌头碰。", "连": "连（lián）与 tián 声母不同（t/l），意思是连接。", "闲": "闲（xián）与 tián 声母不同（t/x），意思是空闲。", "咸": "咸（xián）与 tián 声母不同（t/x），意思是味道咸。"}, "sentence_index": null, "correct_answer": "田"}, "level_3": {"options": [{"text": "田", "is_correct": true, "explanation": "正确：“那片田里”指田地，句意通顺。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包里长不出麦子，「那片书包」也不能这样说。"}, {"text": "床", "is_correct": false, "explanation": "语义：床上长不出麦子，「那片床」也不能这样说。"}, {"text": "钱包", "is_correct": false, "explanation": "语义：钱包里长不出麦子，「那片钱包」也不能这样说。"}], "explanations": {"田": "正确：“那片田里”指田地，句意通顺。", "书包": "语义：书包里长不出麦子，「那片书包」也不能这样说。", "床": "语义：床上长不出麦子，「那片床」也不能这样说。", "钱包": "语义：钱包里长不出麦子，「那片钱包」也不能这样说。"}, "sentence_index": 6, "correct_answer": "田"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "操场上铺着一片田，孩子们在上面跑。", "explanation": "这里应该用〈草地〉。田专指种庄稼的土地，不指草坪。"}, {"text": "这座公园里有一块田，专门用来滑冰。", "explanation": "这里应该用〈溜冰场〉。田指种庄稼的地，不能用来滑冰。"}, {"text": "老师让我们在田里写生字。", "explanation": "这里应该用〈本子〉。田指农田，不指书写的地方，“在田里写字”说不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b807295-70ef-4a27-b0f7-f6022d1a5a9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12736, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们在田种了一排树苗。", "corrected_sentence": "我们在田里种了一排树苗。", "error_description": "“田”后缺少方位词“里”。表示在田地中的位置时应说“在田里”，不能直接说“在田”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b807295-70ef-4a27-b0f7-f6022d1a5a9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12736, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那块田上种了很多玉米。", "corrected_sentence": "那块田里种了很多玉米。", "error_description": "表示田地中的位置时要用方位词“里”，“田上”不是自然的说法，应说“田里”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b807295-70ef-4a27-b0f7-f6022d1a5a9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
