INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12739, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指年龄较大、经验丰富的一代人，通常指父母或祖父母辈的人。", "primary_collocate": null, "pronunciation": "lǎo yí bèi", "ipa": "lɑʊ˨˩˦ i˧˥ peɪ˥˩", "syllable_count": 3, "sentences": [{"text": "这是老一辈传下来的办法。", "target_word": "老一辈", "complexity_tier": "T2", "sentence_source": "mined"}, {"text": "老一辈的人都很爱惜粮食。", "target_word": "老一辈", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要多听听老一辈的故事。", "target_word": "老一辈", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老一辈常说，做人要老实。", "target_word": "老一辈", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个习惯是从老一辈那里学来的。", "target_word": "老一辈", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老一辈的人不太会用手机。", "target_word": "老一辈", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "过年的时候，老一辈会给孩子红包。", "target_word": "老一辈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里的老一辈都记得这条河。", "target_word": "老一辈", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老一辈受过很多苦，所以很节约。", "target_word": "老一辈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很尊敬老一辈，经常去看他们。", "target_word": "老一辈", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "年龄较大、经验丰富的一代人，父母或祖父母辈", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e2dde96-c6b3-456a-92c6-668f8966c4d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12739, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "老一辈", "is_correct": true, "explanation": "正确：老一辈是年长的一代，能把办法一代代传下来。"}, {"text": "年轻人", "is_correct": false, "explanation": "语义：年轻人刚开始做事，不会有长期传下来的办法。"}, {"text": "机器人", "is_correct": false, "explanation": "语义：机器人没有「传下来」办法的经历，句子说不通。"}, {"text": "孙子", "is_correct": false, "explanation": "配价：“孙子”指一个人，与“一辈”这种群体概念不匹配。"}], "explanations": {"老一辈": "正确：老一辈是年长的一代，能把办法一代代传下来。", "年轻人": "语义：年轻人刚开始做事，不会有长期传下来的办法。", "机器人": "语义：机器人没有「传下来」办法的经历，句子说不通。", "孙子": "配价：“孙子”指一个人，与“一辈”这种群体概念不匹配。"}, "sentence_index": 0, "correct_answer": "老一辈"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我和老一辈的同学每天一起去上学。", "explanation": "这里应该用〈同辈〉。老一辈指年长的一代，不能指同龄的同学。"}, {"text": "刚出生的婴儿是老一辈。", "explanation": "这里应该用〈晚辈〉。老一辈指年长的一代，刚出生的孩子属于晚辈，不能说是老一辈。"}, {"text": "我们班的老一辈都是新来的同学。", "explanation": "这里应该用〈晚辈〉。老一辈指年长的一代，新来的同学属于年轻一代。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b807295-70ef-4a27-b0f7-f6022d1a5a9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12739, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "老一辈", "is_correct": true, "explanation": "正确：老一辈是长辈，过年时会给晚辈发红包。"}, {"text": "小朋友", "is_correct": false, "explanation": "语义：小朋友自己还是孩子，不会给孩子发红包。"}, {"text": "婴儿", "is_correct": false, "explanation": "配价：婴儿不能施行“给”这个动作，句子主语不成立。"}, {"text": "小猫", "is_correct": false, "explanation": "语义：小猫不会给人发红包，「小猫会给孩子红包」说不通。"}], "explanations": {"老一辈": "正确：老一辈是长辈，过年时会给晚辈发红包。", "小朋友": "语义：小朋友自己还是孩子，不会给孩子发红包。", "婴儿": "配价：婴儿不能施行“给”这个动作，句子主语不成立。", "小猫": "语义：小猫不会给人发红包，「小猫会给孩子红包」说不通。"}, "sentence_index": 6, "correct_answer": "老一辈"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我家附近住着一位老一辈，每天去公园散步。", "explanation": "这里应该用〈老人〉。老一辈是一代人的统称，不指某一位老人。"}, {"text": "我家的小狗是老一辈。", "explanation": "这里应该用〈老狗〉。老一辈指年长的人群，不能用来指小狗。"}, {"text": "他是我们班最小的老一辈，才十岁。", "explanation": "这里应该用〈晚辈〉。老一辈指年长的一代，十岁的孩子属于晚辈。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b807295-70ef-4a27-b0f7-f6022d1a5a9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12739, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们要多向一位老一辈学习。", "corrected_sentence": "我们要多向老一辈学习。", "error_description": "“老一辈”是一代人的统称，不能与个体量词“位”搭配。这里直接说“老一辈”即可。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b807295-70ef-4a27-b0f7-f6022d1a5a9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12739, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个老一辈都经历过不容易的日子。", "corrected_sentence": "很多老一辈都经历过不容易的日子。", "error_description": "“老一辈”指一代人，是统称，不能用“这个”这类个体限定。应说“很多老一辈”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b807295-70ef-4a27-b0f7-f6022d1a5a9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12740, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "失传", "is_correct": true, "explanation": "正确：失传指技艺、习俗等失去传授而不再流传，与“传下来”的意思正相反。"}, {"text": "购买", "is_correct": false, "explanation": "无关：“购买”指用钱买东西，与“传下来”没有反义关系。"}, {"text": "散步", "is_correct": false, "explanation": "无关：“散步”指随意走动，与“传下来”没有反义关系。"}, {"text": "打扫", "is_correct": false, "explanation": "无关：“打扫”指清理环境，与“传下来”没有反义关系。"}], "correct_answer": "失传", "explanations": {"失传": "正确：失传指技艺、习俗等失去传授而不再流传，与“传下来”的意思正相反。", "购买": "无关：“购买”指用钱买东西，与“传下来”没有反义关系。", "散步": "无关：“散步”指随意走动，与“传下来”没有反义关系。", "打扫": "无关：“打扫”指清理环境，与“传下来”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72a5c259-26f4-4ee3-a93e-3b6674c9f02b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12740, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "失传", "is_correct": true, "explanation": "正确：失传指技艺、习俗等失去传授而不再流传，与“传下来”的意思正相反。"}, {"text": "唱歌", "is_correct": false, "explanation": "无关：“唱歌”指发出乐音，与“传下来”没有反义关系。"}, {"text": "洗澡", "is_correct": false, "explanation": "无关：“洗澡”指清洁身体，与“传下来”没有反义关系。"}, {"text": "跑步", "is_correct": false, "explanation": "无关：“跑步”指快速移动，与“传下来”没有反义关系。"}], "correct_answer": "失传", "explanations": {"失传": "正确：失传指技艺、习俗等失去传授而不再流传，与“传下来”的意思正相反。", "唱歌": "无关：“唱歌”指发出乐音，与“传下来”没有反义关系。", "洗澡": "无关：“洗澡”指清洁身体，与“传下来”没有反义关系。", "跑步": "无关：“跑步”指快速移动，与“传下来”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72a5c259-26f4-4ee3-a93e-3b6674c9f02b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12740, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指事物或知识、习俗等从过去流传、保存到现在。", "primary_collocate": null, "pronunciation": "chuán xià lai", "ipa": "tʂʰwan˧˥ ɕja˥˩ lai", "syllable_count": 3, "sentences": [{"text": "这是老一辈传下来的办法。", "target_word": "传下来", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "春节吃饺子是祖先传下来的习俗。", "target_word": "传下来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这门手艺从清朝一直传下来了。", "target_word": "传下来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "端午节的很多习惯都是古代传下来的。", "target_word": "传下来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些古老的知识是怎么传下来的呢？", "target_word": "传下来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶家有一本传下来的老书。", "target_word": "传下来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个节日已经传下来一千多年了。", "target_word": "传下来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种做茶的方法传下来很不容易。", "target_word": "传下来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要把好传统一直传下来。", "target_word": "传下来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座古城的故事是一代代传下来的。", "target_word": "传下来", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "传下来了", "label": "体标"}, {"form": "传下来的", "label": "结构助词"}], "register": "中性", "sense_fingerprint": "习俗、知识、办法等从过去流传保存到现在", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea494939-a4c9-431c-bc0d-cd219d6a4140') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12740, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "传下来", "is_correct": true, "explanation": "正确：表示办法从老一辈一直流传到现在。"}, {"text": "买", "is_correct": false, "explanation": "语义：“办法”是抽象的，不能被“买”，“老一辈买的办法”说不通。"}, {"text": "打碎", "is_correct": false, "explanation": "搭配：“打碎”只搭配有形的器物，不能说“打碎的办法”。"}, {"text": "吃掉", "is_correct": false, "explanation": "配价：“吃掉”的宾语必须是可吃的东西，“办法”不能被吃掉。"}], "explanations": {"传下来": "正确：表示办法从老一辈一直流传到现在。", "买": "语义：“办法”是抽象的，不能被“买”，“老一辈买的办法”说不通。", "打碎": "搭配：“打碎”只搭配有形的器物，不能说“打碎的办法”。", "吃掉": "配价：“吃掉”的宾语必须是可吃的东西，“办法”不能被吃掉。"}, "sentence_index": 0, "correct_answer": "传下来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他临走时传下来一封信。", "explanation": "这里应该用〈留下〉。传下来指事物从过去一代代流传到现在，当场留下一封信要用“留下”。"}, {"text": "这种感冒很容易传下来给身边的人。", "explanation": "这里应该用〈传染〉。传下来指从过去流传到现在，不表示病菌在身边的人之间相互传播。"}, {"text": "我把包裹传下来寄到了北京。", "explanation": "这里应该用〈托运〉。传下来强调时间上的流传，不表示把包裹运送到远方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72a5c259-26f4-4ee3-a93e-3b6674c9f02b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12740, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "传下来", "is_correct": true, "explanation": "正确：表示节日从过去一直流传到现在，已经一千多年。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：节日不能游泳，“节日已经游泳一千多年”说不通。"}, {"text": "拆开", "is_correct": false, "explanation": "搭配：“拆开”的对象是有形的包装，不能说“拆开节日”。"}, {"text": "烧掉", "is_correct": false, "explanation": "语义：节日不能被烧掉，与“一千多年”的延续义相反。"}], "explanations": {"传下来": "正确：表示节日从过去一直流传到现在，已经一千多年。", "游泳": "语义：节日不能游泳，“节日已经游泳一千多年”说不通。", "拆开": "搭配：“拆开”的对象是有形的包装，不能说“拆开节日”。", "烧掉": "语义：节日不能被烧掉，与“一千多年”的延续义相反。"}, "sentence_index": 6, "correct_answer": "传下来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这门手艺是三个月前才传下来的。", "explanation": "这里应该用〈学到〉。传下来指事物从过去一代代流传到现在，需要很长时间，三个月前才得到的东西不能这样说。"}, {"text": "工人们花了三年传下来了这座桥。", "explanation": "这里应该用〈建造〉。传下来指事物从过去流传到现在，不表示人们花时间建造东西。"}, {"text": "他在比赛中传下来了第一名。", "explanation": "这里应该用〈得到〉。传下来指事物从过去流传到现在，不能用于比赛中取得的名次。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72a5c259-26f4-4ee3-a93e-3b6674c9f02b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12740, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种手艺是爷爷的爷爷传下来。", "corrected_sentence": "这种手艺是爷爷的爷爷传下来的。", "error_description": "“传下来”后少了“的”。“是……的”句式中，“传下来”要带“的”来修饰“手艺”。应为“这种手艺是爷爷的爷爷传下来的。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72a5c259-26f4-4ee3-a93e-3b6674c9f02b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12740, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这门技艺是很传下来的。", "corrected_sentence": "这门技艺是一代代传下来的。", "error_description": "修饰语“很”不能修饰动词“传下来”，这里应用表示时间延续的“一代代”。应为“这门技艺是一代代传下来的。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72a5c259-26f4-4ee3-a93e-3b6674c9f02b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
