INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12745, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "拉，使物体移动或延长。", "primary_collocate": null, "pronunciation": "yǐn", "ipa": "in˨˩", "syllable_count": 1, "sentences": [{"text": "他们用石头建小水渠，把雨水引到田里。", "target_word": "引", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "农民把绳子引到井边。", "target_word": "引", "complexity_tier": "T3", "furigana": "nóng mín bǎ shéng zi yǐn dào jǐng biān", "sentence_source": "generated"}, {"text": "工人把电线引到新房子里。", "target_word": "引", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人把钢缆引到河对岸，搭起了桥。", "target_word": "引", "complexity_tier": "T3", "furigana": "gōng rén bǎ gāng lǎn yǐn dào hé duì àn, dā qǐ le qiáo", "sentence_source": "generated"}, {"text": "他想把晾衣绳引到阳台上。", "target_word": "引", "complexity_tier": "T3", "furigana": "tā xiǎng bǎ liàng yī shéng yǐn dào yáng tái shàng", "sentence_source": "generated"}, {"text": "村里把山上的绳子引下来了。", "target_word": "引", "complexity_tier": "T3", "furigana": "cūn lǐ bǎ shān shàng de shéng zi yǐn xià lái le", "sentence_source": "generated"}, {"text": "请把这根线引到窗边。", "target_word": "引", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们把铁丝引到了棚子里。", "target_word": "引", "complexity_tier": "T3", "furigana": "tā men bǎ tiě sī yǐn dào le péng zi lǐ", "sentence_source": "generated"}, {"text": "师傅把电线引到了新盖的棚顶上。", "target_word": "引", "complexity_tier": "T3", "furigana": "shī fu bǎ diàn xiàn yǐn dào le xīn gài de péng dǐng shàng", "sentence_source": "generated"}, {"text": "我想把网线引到二楼。", "target_word": "引", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "引了", "label": "体标"}, {"form": "引着", "label": "体标"}, {"form": "引过", "label": "体标"}], "register": "中性", "sense_fingerprint": "把水、电线等引导着拉到别处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '23a895ae-04dc-425d-89b4-86e14f5ee5e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12745, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "引", "is_correct": true, "explanation": "正确答案：引（yǐn，第三声），意思是把水、电线等引导着拉到别处。"}, {"text": "音", "is_correct": false, "explanation": "yīn（第一声）与 yǐn（第三声）声调不同，意思是声音。"}, {"text": "银", "is_correct": false, "explanation": "yín（第二声）与 yǐn（第三声）声调不同，意思是银子。"}, {"text": "印", "is_correct": false, "explanation": "yìn（第四声）与 yǐn（第三声）声调不同，意思是印章。"}, {"text": "影", "is_correct": false, "explanation": "yǐng 与 yǐn 韵尾不同（ng 与 n），意思是影子。"}], "explanations": {"引": "正确答案：引（yǐn，第三声），意思是把水、电线等引导着拉到别处。", "音": "yīn（第一声）与 yǐn（第三声）声调不同，意思是声音。", "银": "yín（第二声）与 yǐn（第三声）声调不同，意思是银子。", "印": "yìn（第四声）与 yǐn（第三声）声调不同，意思是印章。", "影": "yǐng 与 yǐn 韵尾不同（ng 与 n），意思是影子。"}, "sentence_index": null, "correct_answer": "引"}, "level_3": {"options": [{"text": "引", "is_correct": true, "explanation": "正确：“引”表示引导着把雨水送到别处，“把雨水引到田里”通顺。"}, {"text": "挖", "is_correct": false, "explanation": "语义：“挖”是掘取，不能表示把雨水送到田里，句子说不通。"}, {"text": "烧", "is_correct": false, "explanation": "语义：“烧”表示燃烧或加热，不能表示水的输送，句子说不通。"}, {"text": "拆", "is_correct": false, "explanation": "搭配：“拆”不能与“雨水”搭配，“把雨水拆到田里”不成立。"}], "explanations": {"引": "正确：“引”表示引导着把雨水送到别处，“把雨水引到田里”通顺。", "挖": "语义：“挖”是掘取，不能表示把雨水送到田里，句子说不通。", "烧": "语义：“烧”表示燃烧或加热，不能表示水的输送，句子说不通。", "拆": "搭配：“拆”不能与“雨水”搭配，“把雨水拆到田里”不成立。"}, "sentence_index": 0, "correct_answer": "引"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把一支笔引到了耳朵上。", "explanation": "这里应该用〈夹〉。“引”指引导着拉到别处，把笔夹在耳朵上要用“夹”。"}, {"text": "我把饭引到碗里。", "explanation": "这里应该用〈盛〉。“引”指引导着拉到别处，装饭要用“盛”。"}, {"text": "我把钥匙引到口袋里。", "explanation": "这里应该用〈放〉。“引”指引导着拉过去，把钥匙装进口袋要用“放”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1249cc0b-e936-4f6d-a885-4bc9b9606521') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12745, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "引", "is_correct": true, "explanation": "正确答案：引（yǐn，第三声），意思是把东西引导着拉到别处。"}, {"text": "因", "is_correct": false, "explanation": "yīn（第一声）与 yǐn（第三声）声调不同，意思是因为。"}, {"text": "吟", "is_correct": false, "explanation": "yín（第二声）与 yǐn（第三声）声调不同，意思是吟诵。"}, {"text": "印", "is_correct": false, "explanation": "yìn（第四声）与 yǐn（第三声）声调不同，意思是印章。"}, {"text": "影", "is_correct": false, "explanation": "yǐng 与 yǐn 只差韵尾（ng 与 n），声调相同，意思是影子。"}], "explanations": {"引": "正确答案：引（yǐn，第三声），意思是把东西引导着拉到别处。", "因": "yīn（第一声）与 yǐn（第三声）声调不同，意思是因为。", "吟": "yín（第二声）与 yǐn（第三声）声调不同，意思是吟诵。", "印": "yìn（第四声）与 yǐn（第三声）声调不同，意思是印章。", "影": "yǐng 与 yǐn 只差韵尾（ng 与 n），声调相同，意思是影子。"}, "sentence_index": null, "correct_answer": "引"}, "level_3": {"options": [{"text": "引", "is_correct": true, "explanation": "正确：“引”表示把线引导着拉到别处，“把这根线引到窗边”通顺。"}, {"text": "切", "is_correct": false, "explanation": "语义：“切”是割断，不能表示把线移到别处，句子说不通。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”是加热食物，不能表示把线移到窗边，句子说不通。"}, {"text": "眨", "is_correct": false, "explanation": "配价：“眨”不能带“到窗边”这样的处所补语，“把线眨到窗边”不通。"}], "explanations": {"引": "正确：“引”表示把线引导着拉到别处，“把这根线引到窗边”通顺。", "切": "语义：“切”是割断，不能表示把线移到别处，句子说不通。", "煮": "语义：“煮”是加热食物，不能表示把线移到窗边，句子说不通。", "眨": "配价：“眨”不能带“到窗边”这样的处所补语，“把线眨到窗边”不通。"}, "sentence_index": 6, "correct_answer": "引"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把书引到了地上。", "explanation": "这里应该用〈放〉。“引”指引导着拉到别处，把书放到地上要用“放”。"}, {"text": "他把画引到了墙上。", "explanation": "这里应该用〈挂〉。“引”指拉或引导水、线等送到别处，画挂在墙上要用“挂”。"}, {"text": "他把嗓门引高了。", "explanation": "这里应该用〈提高〉。“引”不用于声音的高低，嗓门变大要说“提高”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1249cc0b-e936-4f6d-a885-4bc9b9606521') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12745, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们用管子把山泉水引村里。", "corrected_sentence": "他们用管子把山泉水引到村里。", "error_description": "错误在补语：“引”后要用“到”引出处所，应说“引到村里”，不能省去“到”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1249cc0b-e936-4f6d-a885-4bc9b9606521') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12745, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他已经电线引到门口了。", "corrected_sentence": "他已经把电线引到门口了。", "error_description": "错误在缺少“把”：处置“电线”要用“把”字句，应说“他已经把电线引到门口了”，不能说“他已经电线引到门口了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1249cc0b-e936-4f6d-a885-4bc9b9606521') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
