INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12746, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指共同居住在一个地方，通常指家庭成员或关系亲密的人一起生活。", "primary_collocate": null, "pronunciation": "zhù zài yì qǐ", "ipa": "ʈ͡ʂu˥˩ t͡sai˥˩ i˥˩ t͡ɕʰi˨˩˦", "syllable_count": 4, "sentences": [{"text": "大家住在一起，每家轮流用水。", "target_word": "住在一起", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "他们是一家人，住在一起很热闹。", "target_word": "住在一起", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我和朋友在北京住在一起。", "target_word": "住在一起", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "奶奶和我们住在一起。", "target_word": "住在一起", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他们结婚以后，就住在一起了。", "target_word": "住在一起", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两个学生为了省钱，住在一起。", "target_word": "住在一起", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你想和爸爸妈妈住在一起吗？", "target_word": "住在一起", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "以前我们三个人住在一起过。", "target_word": "住在一起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "毕业以后，我和两个朋友住在一起，互相照顾。", "target_word": "住在一起", "complexity_tier": "T3", "furigana": "bì yè yǐ hòu, wǒ hé liǎng gè péngyou zhù zài yì qǐ, hù xiāng zhào gù.", "sentence_source": "generated"}, {"text": "姐姐想搬出去，不想和父母住在一起。", "target_word": "住在一起", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "住在一起了", "label": "完成体"}, {"form": "住在一起过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "亲人或亲密的人共同居住在同一处并一起生活", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c1bae2b-5f4e-4b27-899a-8770b7917f2a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12746, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "独居", "is_correct": false, "explanation": "语义：“独居”指一人独自生活，与“大家”共处一处、轮流用水的情境矛盾。"}, {"text": "住在一起", "is_correct": true, "explanation": "正确：“大家住在一起”与“每家轮流用水”相符，几家共处一处才需要轮流用水。"}, {"text": "搬走", "is_correct": false, "explanation": "语义：“搬走”指迁离原处，与几家仍共用水源的情境矛盾。"}, {"text": "散步", "is_correct": false, "explanation": "语义：“散步”指闲步走动，与“每家轮流用水”的情境无关。"}], "explanations": {"独居": "语义：“独居”指一人独自生活，与“大家”共处一处、轮流用水的情境矛盾。", "住在一起": "正确：“大家住在一起”与“每家轮流用水”相符，几家共处一处才需要轮流用水。", "搬走": "语义：“搬走”指迁离原处，与几家仍共用水源的情境矛盾。", "散步": "语义：“散步”指闲步走动，与“每家轮流用水”的情境无关。"}, "sentence_index": 0, "correct_answer": "住在一起"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我一个人住在一起，很自在。", "explanation": "这里不这么用。住在一起指两人或多人共同住在一处，只有一个人时应说“一个人住”。"}, {"text": "这台冰箱和洗衣机住在一起。", "explanation": "这里应该用〈放在一起〉。住在一起指人或动物共同居住，家电不能“住”，只能说放在一起。"}, {"text": "地铁高峰时，大家住在一起。", "explanation": "这里应该用〈挤在一起〉。住在一起指共同居住，不能形容车厢里拥挤。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba5bea40-6cbd-42c5-88ea-fcdfcfe36f85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12746, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "失散", "is_correct": false, "explanation": "语义：“失散”指走散、失去联系，与“你想和爸爸妈妈……吗”的意愿相悖。"}, {"text": "住在一起", "is_correct": true, "explanation": "正确：“你想和爸爸妈妈住在一起吗”是询问是否愿意同住，与句意相符。"}, {"text": "分手", "is_correct": false, "explanation": "搭配：“分手”多指恋人或伴侣分开，不能用于和父母的关系。"}, {"text": "居留", "is_correct": false, "explanation": "语域：“居留”是书面或官方用语，不符合这句口语提问。"}], "explanations": {"失散": "语义：“失散”指走散、失去联系，与“你想和爸爸妈妈……吗”的意愿相悖。", "住在一起": "正确：“你想和爸爸妈妈住在一起吗”是询问是否愿意同住，与句意相符。", "分手": "搭配：“分手”多指恋人或伴侣分开，不能用于和父母的关系。", "居留": "语域：“居留”是书面或官方用语，不符合这句口语提问。"}, "sentence_index": 6, "correct_answer": "住在一起"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "周末我们在公园住在一起。", "explanation": "这里应该用〈见面〉。住在一起指共同住在一处，不能表示在公园碰面。"}, {"text": "拍合影时，我们住在一起。", "explanation": "这里应该用〈站在一起〉。住在一起指共同居住，拍照时的站位不能用它。"}, {"text": "排队买票时，大家住在一起。", "explanation": "这里应该用〈排队〉。住在一起指共同居住，不能指买票时排成队。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba5bea40-6cbd-42c5-88ea-fcdfcfe36f85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12746, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "毕业后，把我和同学住在一起，房租一人一半。", "corrected_sentence": "毕业后，我和同学住在一起，房租一人一半。", "error_description": "“把”错误：“住在一起”前不能加“把”，应去掉“把”，说“我和同学住在一起”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba5bea40-6cbd-42c5-88ea-fcdfcfe36f85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12746, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "如果你毕业了，还想和爸爸妈妈住在一起了吗？", "corrected_sentence": "如果你毕业了，还想和爸爸妈妈住在一起吗？", "error_description": "多余的“了”：“还想”表示尚未实现的意愿，句中不能用“了”，应去掉“了”，说“还想和爸爸妈妈住在一起吗”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba5bea40-6cbd-42c5-88ea-fcdfcfe36f85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12747, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba5bea40-6cbd-42c5-88ea-fcdfcfe36f85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12747, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba5bea40-6cbd-42c5-88ea-fcdfcfe36f85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12747, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "按顺序依次进行，一个接着一个，周而复始。", "primary_collocate": null, "pronunciation": "lún liú", "ipa": "lwən˧˥ ljoʊ˧˥", "syllable_count": 2, "sentences": [{"text": "大家住在一起，每家轮流用水。", "target_word": "轮流", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "我们三个人轮流做饭。", "target_word": "轮流", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "孩子生病了，爸爸妈妈轮流照顾他。", "target_word": "轮流", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "同学们轮流回答老师的问题。", "target_word": "轮流", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今天你洗碗，明天他洗，我们轮流。", "target_word": "轮流", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "司机太累了，两个人轮流开车。", "target_word": "轮流", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们轮流打扫教室，今天轮到我。", "target_word": "轮流", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请大家排好队，轮流上车。", "target_word": "轮流", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "夜里孩子哭，妈妈和奶奶轮流起床。", "target_word": "轮流", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们轮流用一台电脑写作业。", "target_word": "轮流", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "按顺序一个接一个地做，并且反复循环", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c1bae2b-5f4e-4b27-899a-8770b7917f2a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12747, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "辩论", "is_correct": false, "explanation": "语义：“辩论”指争论是非，与“每家轮流用水”的情境无关。"}, {"text": "轮流", "is_correct": true, "explanation": "正确：“每家轮流用水”指几家依次用水，与“大家住在一起”相符。"}, {"text": "霸占", "is_correct": false, "explanation": "语义：“霸占”指强占，与依次轮用水的意思不符。"}, {"text": "打理", "is_correct": false, "explanation": "搭配：“打理”不能搭配“用水”。"}], "explanations": {"辩论": "语义：“辩论”指争论是非，与“每家轮流用水”的情境无关。", "轮流": "正确：“每家轮流用水”指几家依次用水，与“大家住在一起”相符。", "霸占": "语义：“霸占”指强占，与依次轮用水的意思不符。", "打理": "搭配：“打理”不能搭配“用水”。"}, "sentence_index": 0, "correct_answer": "轮流"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我一个人轮流回答老师的问题。", "explanation": "这里不这么用。轮流需要两人或以上依次进行，只有一个人时不能用〈轮流〉。"}, {"text": "同学们轮流同时回答老师的问题。", "explanation": "这里不这么用。轮流指一个接一个依次进行，与“同时”矛盾。"}, {"text": "同学们轮流集体回答老师的问题。", "explanation": "这里应该用〈一起〉。轮流指依次进行，与“集体”（同时全体）矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba5bea40-6cbd-42c5-88ea-fcdfcfe36f85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12747, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "独自", "is_correct": false, "explanation": "语义：“独自”指一个人，与“我们”及“今天轮到我”的轮换矛盾。"}, {"text": "轮流", "is_correct": true, "explanation": "正确：“我们轮流打扫教室，今天轮到我”说明大家依次打扫，与句意相符。"}, {"text": "包揽", "is_correct": false, "explanation": "语义：“包揽”指全部承担，与“今天轮到我”的轮换矛盾。"}, {"text": "退避", "is_correct": false, "explanation": "语域：“退避”是书面用语，且意思是躲避，不符合这句口语。"}], "explanations": {"独自": "语义：“独自”指一个人，与“我们”及“今天轮到我”的轮换矛盾。", "轮流": "正确：“我们轮流打扫教室，今天轮到我”说明大家依次打扫，与句意相符。", "包揽": "语义：“包揽”指全部承担，与“今天轮到我”的轮换矛盾。", "退避": "语域：“退避”是书面用语，且意思是躲避，不符合这句口语。"}, "sentence_index": 6, "correct_answer": "轮流"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们轮流各自用一台电脑写作业。", "explanation": "这里不这么用。“轮流”表示共用一件东西依次使用，“各自用一台”与之矛盾。"}, {"text": "他们轮流并排写作业。", "explanation": "这里应该用〈一起〉。轮流指依次进行，与“并排”（同时在旁）矛盾。"}, {"text": "他们轮流一起写作业。", "explanation": "这里应该用〈依次〉。轮流指依次进行，与“一起”（同时）矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba5bea40-6cbd-42c5-88ea-fcdfcfe36f85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12747, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "同学们轮流了打扫教室，每周换一次。", "corrected_sentence": "同学们轮流打扫教室，每周换一次。", "error_description": "“轮流了”错误，应为“轮流打扫”。“了”不能插在状语“轮流”和动词“打扫”之间，应去掉。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba5bea40-6cbd-42c5-88ea-fcdfcfe36f85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12747, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们三个人把轮流看护孩子，每人一天。", "corrected_sentence": "他们三个人轮流看护孩子，每人一天。", "error_description": "“把”误用：“轮流”是状语，后面直接接动词，“把”字句需要“把+宾语+动词”，此处应去掉“把”，说“轮流看护孩子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba5bea40-6cbd-42c5-88ea-fcdfcfe36f85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12751, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "大意", "is_correct": true, "explanation": "“大意”指粗疏、不留神，与“小心”构成反义关系。"}, {"text": "明亮", "is_correct": false, "explanation": "与“小心”没有反义关系，语义无关。"}, {"text": "柔软", "is_correct": false, "explanation": "与“小心”没有反义关系，语义无关。"}, {"text": "整齐", "is_correct": false, "explanation": "与“小心”没有反义关系，语义无关。"}], "correct_answer": "大意", "explanations": {"大意": "“大意”指粗疏、不留神，与“小心”构成反义关系。", "明亮": "与“小心”没有反义关系，语义无关。", "柔软": "与“小心”没有反义关系，语义无关。", "整齐": "与“小心”没有反义关系，语义无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba5bea40-6cbd-42c5-88ea-fcdfcfe36f85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12751, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "粗心", "is_correct": true, "explanation": "“粗心”指不细心、不留神，与“小心”构成反义关系。"}, {"text": "热闹", "is_correct": false, "explanation": "与“小心”没有反义关系，语义无关。"}, {"text": "潮湿", "is_correct": false, "explanation": "与“小心”没有反义关系，语义无关。"}, {"text": "圆满", "is_correct": false, "explanation": "与“小心”没有反义关系，语义无关。"}], "correct_answer": "粗心", "explanations": {"粗心": "“粗心”指不细心、不留神，与“小心”构成反义关系。", "热闹": "与“小心”没有反义关系，语义无关。", "潮湿": "与“小心”没有反义关系，语义无关。", "圆满": "与“小心”没有反义关系，语义无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba5bea40-6cbd-42c5-88ea-fcdfcfe36f85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12751, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "注意、留神，避免发生危险或错误。", "primary_collocate": null, "pronunciation": "xiǎo xīn", "ipa": "ɕjɑʊ˨˩˦ ɕin˥˥", "syllable_count": 2, "sentences": [{"text": "田里的庄稼需要水，但水不多，所以每个人都要小心。", "target_word": "小心", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "这杯水很烫，你喝的时候要小心。", "target_word": "小心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "考试时要小心，别写错名字。", "target_word": "小心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些玻璃杯很容易碎，请你小心拿。", "target_word": "小心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他做事很小心，从来不会算错钱。", "target_word": "小心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "路上车多，你开车要小心。", "target_word": "小心", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师说，写作业时要小心，别抄错题。", "target_word": "小心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请小心，地上的水还没有干。", "target_word": "小心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这是重要的文件，你要小心保管。", "target_word": "小心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把鸡蛋小心地放进篮子里。", "target_word": "小心", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "小心点儿", "label": "儿化"}, {"form": "小心翼翼", "label": "复合"}, {"form": "小心地", "label": "状语形式"}], "register": "中性", "sense_fingerprint": "小心：留神注意，避免出错或出危险", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c1bae2b-5f4e-4b27-899a-8770b7917f2a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12751, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "小心", "is_correct": true, "explanation": "“小心”指注意留神、避免出错，与“水不多”需要处处留意用水的语境相合。"}, {"text": "浪费", "is_correct": false, "explanation": "语义：“浪费”与“水不多”相反，句意要求每个人都珍惜用水。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：唱歌与“庄稼需要水、水不多”的语境毫无关联。"}, {"text": "处理", "is_correct": false, "explanation": "配价：“处理”需要带宾语，“每个人都要处理”里没有处理的对象。"}], "explanations": {"小心": "“小心”指注意留神、避免出错，与“水不多”需要处处留意用水的语境相合。", "浪费": "语义：“浪费”与“水不多”相反，句意要求每个人都珍惜用水。", "唱歌": "语义：唱歌与“庄稼需要水、水不多”的语境毫无关联。", "处理": "配价：“处理”需要带宾语，“每个人都要处理”里没有处理的对象。"}, "sentence_index": 0, "correct_answer": "小心"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈每天小心生病的爷爷。", "explanation": "这里应该用〈照顾〉。“小心”表示注意避免错误或危险，不用于照料人。"}, {"text": "奶奶每天小心孙子上学。", "explanation": "这里应该用〈陪伴〉。“小心”表示留神避免出错，不能用来指陪同。"}, {"text": "他很小心，一句话不说就动手打人。", "explanation": "这里应该用〈冲动〉。“小心”表示留神避免错误，与“动手打人”的莽撞相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba5bea40-6cbd-42c5-88ea-fcdfcfe36f85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12751, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "小心", "is_correct": true, "explanation": "“小心”指注意避免出错，与后句“别抄错题”前后呼应。"}, {"text": "跳舞", "is_correct": false, "explanation": "语义：写作业时跳舞与句意不相合。"}, {"text": "抄", "is_correct": false, "explanation": "语义：“抄”与后句“别抄错题”矛盾。"}, {"text": "打扫", "is_correct": false, "explanation": "配价：“打扫”需要带宾语，句中没有打扫的对象。"}], "explanations": {"小心": "“小心”指注意避免出错，与后句“别抄错题”前后呼应。", "跳舞": "语义：写作业时跳舞与句意不相合。", "抄": "语义：“抄”与后句“别抄错题”矛盾。", "打扫": "配价：“打扫”需要带宾语，句中没有打扫的对象。"}, "sentence_index": 6, "correct_answer": "小心"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "孩子很小心，总是乱跑。", "explanation": "这里应该用〈调皮〉。“小心”指谨慎留神，与“总是乱跑”的行为矛盾。"}, {"text": "这个孩子很小心，把书包忘在了学校。", "explanation": "这里应该用〈粗心〉。“小心”表示留神，与“把书包忘在了学校”的疏忽相矛盾。"}, {"text": "他做事很小心，常常丢三落四。", "explanation": "这里应该用〈大意〉。“小心”表示留神，与“丢三落四”的粗心相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba5bea40-6cbd-42c5-88ea-fcdfcfe36f85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12751, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他小心地得把碗放在桌子上。", "corrected_sentence": "他小心地把碗放在桌子上。", "error_description": "“地”与“得”不能同时使用：“小心地”作状语后不能再接补语标记“得”，应说“他小心地把碗放在桌子上”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba5bea40-6cbd-42c5-88ea-fcdfcfe36f85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12751, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位老人做事很有小心。", "corrected_sentence": "这位老人做事很小心。", "error_description": "“小心”作谓语时前面不加“有”，应说“很小心”，不说“很有小心”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba5bea40-6cbd-42c5-88ea-fcdfcfe36f85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
