INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12752, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "从幼年时期起。", "primary_collocate": null, "pronunciation": "cóng xiǎo", "ipa": "tsʰʊŋ˧˥ ɕjɑʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "他们从小听老人讲这些方法。", "target_word": "从小", "complexity_tier": "T2", "sentence_source": "mined"}, {"text": "她从小住在海边，很会游泳。", "target_word": "从小", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我从小喜欢画画，现在还在画。", "target_word": "从小", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他从小就爱看书，家里到处是书。", "target_word": "从小", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷从小在农村长大，会种很多菜。", "target_word": "从小", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个孩子从小怕狗，看见狗就哭。", "target_word": "从小", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们从小是好朋友，一起上学。", "target_word": "从小", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她从小跳舞，现在是一名舞蹈老师。", "target_word": "从小", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他从小生活在北方，不怕冷。", "target_word": "从小", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈从小教我要说谢谢。", "target_word": "从小", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "从小到大", "label": "固定搭配"}, {"form": "从小就", "label": "常见搭配"}], "register": "中性", "sense_fingerprint": "从小：从幼年时期起，一直如此", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c1bae2b-5f4e-4b27-899a-8770b7917f2a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12752, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "业已", "is_correct": false, "explanation": "语域：“业已”是书面语，与口语化的“听老人讲这些方法”不协调。"}, {"text": "从小", "is_correct": true, "explanation": "正确：“从小”表示从幼年时期起，与“听老人讲这些方法”的早年经历相符。"}, {"text": "方才", "is_correct": false, "explanation": "语域：“方才”指刚刚过去不久，带文言色彩，不适合这句口语化的叙述。"}, {"text": "从来", "is_correct": false, "explanation": "搭配：“从来”后面一般要接否定词或“都”，不能直接用于“听老人讲”这种经历。"}], "explanations": {"业已": "语域：“业已”是书面语，与口语化的“听老人讲这些方法”不协调。", "从小": "正确：“从小”表示从幼年时期起，与“听老人讲这些方法”的早年经历相符。", "方才": "语域：“方才”指刚刚过去不久，带文言色彩，不适合这句口语化的叙述。", "从来": "搭配：“从来”后面一般要接否定词或“都”，不能直接用于“听老人讲”这种经历。"}, "sentence_index": 0, "correct_answer": "从小"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座老房子从小就有一口井，现在已经填掉了。", "explanation": "这里应该用〈从前〉。“从小”指生物从幼年起的经历，房子没有幼年，说它过去的样子要用“从前”。"}, {"text": "那次事故以后，他从小不再开车了。", "explanation": "这里应该用〈从此〉。“从小”指从幼年时期起，不能用来说某件事之后才开始的变化。"}, {"text": "他从小在北京工作过三年。", "explanation": "这里应该用〈以前〉。“从小”指幼年时期起的情况，工作是成年后的事，不能用“从小”；说成年后的经历要用“以前”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba5bea40-6cbd-42c5-88ea-fcdfcfe36f85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12752, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "忽而", "is_correct": false, "explanation": "语域：“忽而”是书面的副词，表示忽然、时有时无，与“我们是好朋友”的稳定关系不协调。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示不经常，说“偶尔是好朋友”与“从小”开始的长期关系相矛盾。"}, {"text": "从小", "is_correct": true, "explanation": "正确：“从小”表示从幼年时期起，与“是好朋友，一起上学”的长期关系相符。"}, {"text": "立刻", "is_correct": false, "explanation": "搭配：“立刻”表示马上发生，不能修饰“是好朋友”这种长期状态。"}], "explanations": {"忽而": "语域：“忽而”是书面的副词，表示忽然、时有时无，与“我们是好朋友”的稳定关系不协调。", "偶尔": "语义：“偶尔”表示不经常，说“偶尔是好朋友”与“从小”开始的长期关系相矛盾。", "从小": "正确：“从小”表示从幼年时期起，与“是好朋友，一起上学”的长期关系相符。", "立刻": "搭配：“立刻”表示马上发生，不能修饰“是好朋友”这种长期状态。"}, "sentence_index": 6, "correct_answer": "从小"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他从小去了城里工作。", "explanation": "这里应该用〈以后〉。“从小”指从幼年起的情况，不能用来说长大后才发生的事。"}, {"text": "这间屋子从小是厨房。", "explanation": "这里应该用〈原来〉。“从小”指生物从幼年起的情况，物件没有幼年，说它的早先用途要用“原来”。"}, {"text": "他从小接了电话。", "explanation": "这里应该用〈立刻〉。“从小”指从幼年起持续的情况，不能表示马上发生的一次动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba5bea40-6cbd-42c5-88ea-fcdfcfe36f85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12752, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她从小的喜欢吃甜的。", "corrected_sentence": "她从小喜欢吃甜的。", "error_description": "错误：“从小”是副词，后面不能加“的”，“从小的”不能直接作谓语前的状语。正确应为“她从小喜欢吃甜的。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba5bea40-6cbd-42c5-88ea-fcdfcfe36f85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12752, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我弟弟从小了就爱吃糖。", "corrected_sentence": "我弟弟从小就爱吃糖。", "error_description": "错误：“从小”后面直接加了“了”。“从小”是时间状语，不能带“了”。正确应为“我弟弟从小就爱吃糖。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba5bea40-6cbd-42c5-88ea-fcdfcfe36f85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
