INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12753, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把植物的种子或幼苗栽进土里，使其生长，如“他种了三棵树”。", "primary_collocate": null, "pronunciation": "zhòng", "ipa": "ʈʂʊŋ˥˩", "syllable_count": 1, "sentences": [{"text": "他每年春天都在屋后的小菜园里种菜。", "target_word": "种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷在院子里种了三棵苹果树。", "target_word": "种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天到了，农民开始在地里种玉米。", "target_word": "种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想在阳台上种几盆花。", "target_word": "种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个地方太冷，不能种水稻。", "target_word": "种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈每年都在窗前种一些小葱。", "target_word": "种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他种过很多年菜，经验很丰富。", "target_word": "种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们一起去山上种树吧。", "target_word": "种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨以后，农民马上去田里种麦子。", "target_word": "种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师带学生在学校后面种蔬菜。", "target_word": "种", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种了", "label": "体标"}, {"form": "种过", "label": "体标"}, {"form": "种着", "label": "体标"}], "register": "中性", "sense_fingerprint": "种（zhòng）：把植物的种子或幼苗栽进土里，让它生长", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e2dde96-c6b3-456a-92c6-668f8966c4d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12753, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "种", "is_correct": true, "explanation": "zhòng 指把种子埋进土里，让植物生长，是本词的读音和意思。"}, {"text": "中", "is_correct": false, "explanation": "zhōng（第一声）与 zhòng（第四声）声调不同，中指中间，与栽种无关。"}, {"text": "钟", "is_correct": false, "explanation": "zhōng（第一声）与 zhòng（第四声）声调不同，钟指时钟。"}, {"text": "肿", "is_correct": false, "explanation": "zhǒng（第三声）与 zhòng（第四声）声调不同，肿指身体局部鼓起。"}, {"text": "终", "is_correct": false, "explanation": "zhōng（第一声）与 zhòng（第四声）声调不同，终指结束。"}], "explanations": {"种": "zhòng 指把种子埋进土里，让植物生长，是本词的读音和意思。", "中": "zhōng（第一声）与 zhòng（第四声）声调不同，中指中间，与栽种无关。", "钟": "zhōng（第一声）与 zhòng（第四声）声调不同，钟指时钟。", "肿": "zhǒng（第三声）与 zhòng（第四声）声调不同，肿指身体局部鼓起。", "终": "zhōng（第一声）与 zhòng（第四声）声调不同，终指结束。"}, "sentence_index": null, "correct_answer": "种"}, "level_3": {"options": [{"text": "种", "is_correct": true, "explanation": "种：此处是动词，“种菜”指在小菜园里栽种蔬菜，句意通顺。"}, {"text": "骑", "is_correct": false, "explanation": "搭配：“骑”的宾语应是车、马等，不能说骑菜。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“穿”的宾语应是衣服、鞋帽，不能说穿菜。"}, {"text": "戴", "is_correct": false, "explanation": "语义：“戴”指戴在头、脸或手上，与“菜”毫不相干，句意不通。"}], "explanations": {"种": "种：此处是动词，“种菜”指在小菜园里栽种蔬菜，句意通顺。", "骑": "搭配：“骑”的宾语应是车、马等，不能说骑菜。", "穿": "搭配：“穿”的宾语应是衣服、鞋帽，不能说穿菜。", "戴": "语义：“戴”指戴在头、脸或手上，与“菜”毫不相干，句意不通。"}, "sentence_index": 0, "correct_answer": "种"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家种了一只猫。", "explanation": "这里应该用〈养〉。种指栽植植物，养用于动物，猫要说“养”。"}, {"text": "我想在学校种几个朋友。", "explanation": "这里应该用〈交〉。种只用于栽植植物，结交朋友要说“交”。"}, {"text": "我每天晚上种作业到十点。", "explanation": "这里应该用〈做〉。种指栽植植物，做作业要说“做”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b807295-70ef-4a27-b0f7-f6022d1a5a9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12753, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "种", "is_correct": true, "explanation": "zhòng 指把种子埋进土里，让植物生长，是本词的读音和意思。"}, {"text": "忠", "is_correct": false, "explanation": "zhōng（第一声）与 zhòng（第四声）声调不同，忠指忠诚。"}, {"text": "盅", "is_correct": false, "explanation": "zhōng（第一声）与 zhòng（第四声）声调不同，盅指小杯子或小碗。"}, {"text": "冢", "is_correct": false, "explanation": "zhǒng（第三声）与 zhòng（第四声）声调不同，冢指大坟墓。"}, {"text": "踵", "is_correct": false, "explanation": "zhǒng（第三声）与 zhòng（第四声）声调不同，踵指脚后跟。"}], "explanations": {"种": "zhòng 指把种子埋进土里，让植物生长，是本词的读音和意思。", "忠": "zhōng（第一声）与 zhòng（第四声）声调不同，忠指忠诚。", "盅": "zhōng（第一声）与 zhòng（第四声）声调不同，盅指小杯子或小碗。", "冢": "zhǒng（第三声）与 zhòng（第四声）声调不同，冢指大坟墓。", "踵": "zhǒng（第三声）与 zhòng（第四声）声调不同，踵指脚后跟。"}, "sentence_index": null, "correct_answer": "种"}, "level_3": {"options": [{"text": "种", "is_correct": true, "explanation": "种：此处是动词，“种过菜”指有过栽种蔬菜的经历，与“经验很丰富”相合。"}, {"text": "拆", "is_correct": false, "explanation": "语义：“拆”的对象是建筑或物件，“拆菜”说不通。"}, {"text": "驾", "is_correct": false, "explanation": "搭配：“驾”的对象是车、马等交通工具，不能说驾菜。"}, {"text": "吹", "is_correct": false, "explanation": "语义：“吹”指用气流推动，与菜不相干，句意不通。"}], "explanations": {"种": "种：此处是动词，“种过菜”指有过栽种蔬菜的经历，与“经验很丰富”相合。", "拆": "语义：“拆”的对象是建筑或物件，“拆菜”说不通。", "驾": "搭配：“驾”的对象是车、马等交通工具，不能说驾菜。", "吹": "语义：“吹”指用气流推动，与菜不相干，句意不通。"}, "sentence_index": 6, "correct_answer": "种"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师带学生在学校后面种一座楼。", "explanation": "这里应该用〈盖〉。种只用于栽植植物，盖楼要说“盖”。"}, {"text": "老师带学生在学校后面种一个礼堂。", "explanation": "这里应该用〈建〉。种指栽植，建造礼堂要说“建”。"}, {"text": "老师带学生在学校后面种一口井。", "explanation": "这里应该用〈打〉。种指栽植，打井要说“打”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b807295-70ef-4a27-b0f7-f6022d1a5a9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12753, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在院子里种得一棵苹果树。", "corrected_sentence": "他在院子里种了一棵苹果树。", "error_description": "“种”后面接“得”引出补语，但这里没有补语，应该用“了”表示完成。错误：“种得一棵苹果树”。正确：“他在院子里种了一棵苹果树。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b807295-70ef-4a27-b0f7-f6022d1a5a9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12753, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在地里种得一排白菜。", "corrected_sentence": "他在地里种着一排白菜。", "error_description": "“种”后面接“得”引出补语，但这里没有补语，应该用“着”表示动作持续的状态。错误：“种得一排白菜”。正确：“他在地里种着一排白菜。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b807295-70ef-4a27-b0f7-f6022d1a5a9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
