INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12757, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "一代接一代地相传下去，指某种传统、知识、技艺或物品在世代之间传递、延续。", "primary_collocate": null, "pronunciation": "dài dài xiāng chuán", "ipa": "taɪ˥˩ taɪ˥˩ ɕjaŋ˥ ʈʂʰwan˧˥", "syllable_count": 4, "sentences": [{"text": "这些方法是他们的文化遗产，代代相传。", "target_word": "代代相传", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "这种做面条的手艺在我们家代代相传。", "target_word": "代代相传", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春节包饺子的习惯，在中国家庭里代代相传。", "target_word": "代代相传", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个民间故事在村子里代代相传。", "target_word": "代代相传", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶说，这个做茶的方法是祖先留下的，代代相传。", "target_word": "代代相传", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中医的很多知识靠师傅教徒弟，代代相传。", "target_word": "代代相传", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首儿歌很老了，在孩子们中间代代相传。", "target_word": "代代相传", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们家的茶馆开了一百年，手艺代代相传。", "target_word": "代代相传", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些传统节日的故事，一直代代相传。", "target_word": "代代相传", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这门做陶瓷的技术，在这个小镇代代相传。", "target_word": "代代相传", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "传统、技艺、知识在世代之间传递延续", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7441cee5-2e00-483a-8d58-1c3e5c5576de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12757, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "离开", "is_correct": false, "explanation": "语义：方法是文化遗产，“离开”说不通，句意不成立。"}, {"text": "代代相传", "is_correct": true, "explanation": "正确：文化遗产的方法要“代代相传”，与“文化遗产”的语境相符。"}, {"text": "落户", "is_correct": false, "explanation": "搭配：“落户”指定居、安家，不能和“文化遗产”搭配。"}, {"text": "散步", "is_correct": false, "explanation": "语义：“散步”是人的活动，不能用来说明方法的延续，句意不通。"}], "explanations": {"离开": "语义：方法是文化遗产，“离开”说不通，句意不成立。", "代代相传": "正确：文化遗产的方法要“代代相传”，与“文化遗产”的语境相符。", "落户": "搭配：“落户”指定居、安家，不能和“文化遗产”搭配。", "散步": "语义：“散步”是人的活动，不能用来说明方法的延续，句意不通。"}, "sentence_index": 0, "correct_answer": "代代相传"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条新闻很快就代代相传了。", "explanation": "这里应该用〈传播〉。“代代相传”指世代延续，不能用于一时间传开的新闻。"}, {"text": "他把书代代相传给了同桌。", "explanation": "这里应该用〈传递〉。“代代相传”强调世代延续，不能用于一次性交给某人。"}, {"text": "这篇文章在网上代代相传得很快。", "explanation": "这里应该用〈转发〉。“代代相传”指世代之间的延续，不能形容网上短时间的转发。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f474352a-c393-4fb5-801c-049a504dc0c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12757, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "放假", "is_correct": false, "explanation": "搭配：“放假”是学校、单位的事，不说“在孩子们中间放假”。"}, {"text": "代代相传", "is_correct": true, "explanation": "正确：儿歌很老了，所以是在孩子们中间“代代相传”，与句意相符。"}, {"text": "停电", "is_correct": false, "explanation": "语义：“停电”是供电的事，与儿歌在孩子们中间流传的语境不符。"}, {"text": "上班", "is_correct": false, "explanation": "语义：“上班”是成人的工作，与儿歌在孩子们中间流传的语境不符。"}], "explanations": {"放假": "搭配：“放假”是学校、单位的事，不说“在孩子们中间放假”。", "代代相传": "正确：儿歌很老了，所以是在孩子们中间“代代相传”，与句意相符。", "停电": "语义：“停电”是供电的事，与儿歌在孩子们中间流传的语境不符。", "上班": "语义：“上班”是成人的工作，与儿歌在孩子们中间流传的语境不符。"}, "sentence_index": 6, "correct_answer": "代代相传"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这首歌去年代代相传。", "explanation": "这里应该用〈流行〉。“代代相传”指世代延续，不能用于一年之内流行的歌曲。"}, {"text": "他昨晚代代相传得很好。", "explanation": "这里应该用〈睡〉。“代代相传”指世代延续，不能用来形容一夜的睡眠。"}, {"text": "这条规定从明天开始代代相传。", "explanation": "这里应该用〈生效〉。“代代相传”指世代延续，不能用于规定从某天起执行。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f474352a-c393-4fb5-801c-049a504dc0c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
