INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12757, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这门手艺在这个小镇已经了代代相传几百年。", "corrected_sentence": "这门手艺在这个小镇已经代代相传几百年。", "error_description": "错误：“已经了代代相传”；正确：“已经代代相传”。“了”是完成标记，不能放在动词短语前面，应放在动词后面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f474352a-c393-4fb5-801c-049a504dc0c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
