INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12766, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c60899f1-e56a-4535-96d2-aa943636429c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12766, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指从躺、坐等状态转换为站立的状态。", "primary_collocate": null, "pronunciation": "qǐ lái", "ipa": "tɕʰi˨˩ lai˧˥", "syllable_count": 2, "sentences": [{"text": "地上很凉，你快起来吧。", "target_word": "起来", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他从沙发上起来，去开门。", "target_word": "起来", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老人坐了很久，慢慢起来了。", "target_word": "起来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请大家都起来，我们一起唱国歌。", "target_word": "起来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子躺在地上哭，妈妈叫他起来。", "target_word": "起来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他摔倒了，但是很快就起来了。", "target_word": "起来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你别躺着了，起来走走吧。", "target_word": "起来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到老师的名字，他马上从座位上起来。", "target_word": "起来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生说病人今天可以起来走路。", "target_word": "起来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家坐了一个小时，都起来活动活动。", "target_word": "起来", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "起来了", "label": "体标"}], "register": "口语", "sense_fingerprint": "从躺或坐的状态变为站立；起身", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ade6ce41-a0e9-49cf-8af0-3740ac5cd6f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12766, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "起来", "is_correct": true, "explanation": "起来：表示从躺或坐变为站立，符合“地上很凉，你快……吧”劝人起身的语境。"}, {"text": "躺", "is_correct": false, "explanation": "语义：地上很凉时劝人“快躺吧”与语境相反，躺卧不是离开凉地的动作。"}, {"text": "蹲", "is_correct": false, "explanation": "搭配：“快……吧”劝人离开地面时，不能说“快蹲吧”。"}, {"text": "跪", "is_correct": false, "explanation": "语义：“跪”是屈膝着地，与“地上很凉”劝人离开地面的语境不合。"}], "explanations": {"起来": "起来：表示从躺或坐变为站立，符合“地上很凉，你快……吧”劝人起身的语境。", "躺": "语义：地上很凉时劝人“快躺吧”与语境相反，躺卧不是离开凉地的动作。", "蹲": "搭配：“快……吧”劝人离开地面时，不能说“快蹲吧”。", "跪": "语义：“跪”是屈膝着地，与“地上很凉”劝人离开地面的语境不合。"}, "sentence_index": 0, "correct_answer": "起来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一头倒在床上，就躺起来了。", "explanation": "这里应该用〈下来〉。“躺下来”表示由站或坐变为躺，“躺起来”的“起来”指起身，方向相反。"}, {"text": "他滑了一跤，就摔起来了。", "explanation": "这里应该用〈倒下〉。“摔倒”表示向下倒，“起来”指起身或站起，不能表示摔倒。"}, {"text": "他站在门口，突然坐起来了。", "explanation": "这里应该用〈坐下来〉。“坐起来”指从躺卧变为坐直，从站立变为坐要用“坐下来”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c60899f1-e56a-4535-96d2-aa943636429c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12766, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "起来", "is_correct": true, "explanation": "起来：表示从躺卧变为起身，符合“你别躺着了，……走走吧”的语境。"}, {"text": "坐", "is_correct": false, "explanation": "搭配：“坐”不能与“走走”连用表示起身后活动。"}, {"text": "站", "is_correct": false, "explanation": "语义：“站”只表示站立不动，与“走走”的活动义不合。"}, {"text": "睡", "is_correct": false, "explanation": "语义：前文已说“你别躺着了”，“睡”与躺卧的语境重复，且与“走走”不合。"}], "explanations": {"起来": "起来：表示从躺卧变为起身，符合“你别躺着了，……走走吧”的语境。", "坐": "搭配：“坐”不能与“走走”连用表示起身后活动。", "站": "语义：“站”只表示站立不动，与“走走”的活动义不合。", "睡": "语义：前文已说“你别躺着了”，“睡”与躺卧的语境重复，且与“走走”不合。"}, "sentence_index": 6, "correct_answer": "起来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他站着说话，突然跪起来了。", "explanation": "这里应该用〈跪下来〉。“跪下来”表示由站或坐变为跪，“跪起来”的“起来”指起身站立，不能这样用。"}, {"text": "他被推了一下，就躺起来了。", "explanation": "这里应该用〈躺下来〉。“躺下来”表示由站或坐变为躺，“起来”表示起身，方向相反。"}, {"text": "这些数字还没加完，就停起来了。", "explanation": "这里应该用〈停下来〉。“起来”表示开始，中止要用“停下来”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c60899f1-e56a-4535-96d2-aa943636429c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12766, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他坐了太久，腿麻了，才站起来着。", "corrected_sentence": "他坐了太久，腿麻了，才站起来了。", "error_description": "错误形式：“站起来着”；正确形式：“站起来了”。表示动作已经完成要用“了”，“着”表示动作持续，不能用于此处。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c60899f1-e56a-4535-96d2-aa943636429c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12766, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他从椅子上站起来的，给客人倒水。", "corrected_sentence": "他从椅子上站起来，给客人倒水。", "error_description": "错误形式：“站起来的，给客人倒水”；正确形式：“站起来，给客人倒水”。“站起来”后面不能加“的”，直接接逗号和后续动作即可。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c60899f1-e56a-4535-96d2-aa943636429c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
