INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12768, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '925ff1f8-9638-4c99-a47e-c4dcf897ebd8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12768, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "表示等待直到某一时刻或某一事件发生。", "primary_collocate": null, "pronunciation": "děng dào", "ipa": "tɤŋ˨˩˦ taʊ˥˩", "syllable_count": 2, "sentences": [{"text": "等到干旱时，再把这些水用来灌溉农田。", "target_word": "等到", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "等到天黑了，我们再回家。", "target_word": "等到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "等到你长大了，就会明白。", "target_word": "等到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "等到雨停了，我们再出去玩。", "target_word": "等到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "等到我到家，饭已经做好了。", "target_word": "等到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "等到明年春天，这里的花就开了。", "target_word": "等到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "等到工作做完，我再给你打电话。", "target_word": "等到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "等到他赶到车站，火车已经开走了。", "target_word": "等到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "别急，等到有空我就帮你修。", "target_word": "等到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "等到孩子们都睡着了，妈妈才开始看书。", "target_word": "等到", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "等到：引出某个时刻或事件，后面常接再／才／就", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b91ba0fb-3b3b-487a-84e1-8487031e38b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12768, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "等到", "is_correct": true, "explanation": "等到表示等待直到某个时刻或事件发生，与“干旱时”和后面的“再”相呼应。"}, {"text": "虽然", "is_correct": false, "explanation": "语义：虽然表示让步，与“再把这些水用来灌溉农田”的先后安排不合。"}, {"text": "所以", "is_correct": false, "explanation": "搭配：所以要接在原因之后表示结果，前面没有原因分句，不能引出“干旱时”这个时间状语。"}, {"text": "从而", "is_correct": false, "explanation": "语域：从而是偏书面的连词，且表示结果，与这里表示时间的口语语境不合。"}], "explanations": {"等到": "等到表示等待直到某个时刻或事件发生，与“干旱时”和后面的“再”相呼应。", "虽然": "语义：虽然表示让步，与“再把这些水用来灌溉农田”的先后安排不合。", "所以": "搭配：所以要接在原因之后表示结果，前面没有原因分句，不能引出“干旱时”这个时间状语。", "从而": "语域：从而是偏书面的连词，且表示结果，与这里表示时间的口语语境不合。"}, "sentence_index": 0, "correct_answer": "等到"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "等到他很聪明，所以考上了大学。", "explanation": "这里应该用〈因为〉。〈等到〉只表示等待某个时间或事件出现，不能用来说明原因。"}, {"text": "我们等到两个小时的时间，才开始讨论。", "explanation": "这里应该用〈等了〉。〈等到〉表示等来某个时刻，不能直接接一段时长；“两个小时的时间”是时长，应说“等了两个小时”。"}, {"text": "等到他很累，他还坚持工作。", "explanation": "这里应该用〈虽然〉。〈等到〉表示时间或事件，不表示让步。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '925ff1f8-9638-4c99-a47e-c4dcf897ebd8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12768, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "等到", "is_correct": true, "explanation": "等到表示先等待、后发生，与“工作做完”之后“再打电话”的顺序相符。"}, {"text": "尽管", "is_correct": false, "explanation": "语义：尽管表示让步，与“工作做完”之后再打电话的时间顺序不合。"}, {"text": "因此", "is_correct": false, "explanation": "语义：因此表示结果，前面没有原因分句，不能引出“工作做完”这个时间条件。"}, {"text": "然而", "is_correct": false, "explanation": "语域：然而表示转折，偏书面，与这里的顺承关系不合。"}], "explanations": {"等到": "等到表示先等待、后发生，与“工作做完”之后“再打电话”的顺序相符。", "尽管": "语义：尽管表示让步，与“工作做完”之后再打电话的时间顺序不合。", "因此": "语义：因此表示结果，前面没有原因分句，不能引出“工作做完”这个时间条件。", "然而": "语域：然而表示转折，偏书面，与这里的顺承关系不合。"}, "sentence_index": 6, "correct_answer": "等到"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "等到我做饭，我们同时看电视。", "explanation": "这里应该用〈一边〉…〈一边〉。〈等到〉表示先等待、后发生，与〈同时〉表示的同步进行冲突。"}, {"text": "等到他考上大学，所以我很骄傲。", "explanation": "这里应该用〈因为〉。〈等到〉只引出时间或事件，不能说明我骄傲的原因。"}, {"text": "我一直等到半个晚上的时间。", "explanation": "这里应该用〈等了〉。〈等到〉表示等来某个时刻或结果，不能直接接一段持续的时长。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '925ff1f8-9638-4c99-a47e-c4dcf897ebd8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12768, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "等到到晚饭做好，我们再吃。", "corrected_sentence": "等到晚饭做好，我们再吃。", "error_description": "错误：“到”被重复写了一次，“等到”后面多出一个“到”。正确：“等到”是一个词，后面直接接时间分句“晚饭做好”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '925ff1f8-9638-4c99-a47e-c4dcf897ebd8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12768, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们等到到他回来，再一起吃饭。", "corrected_sentence": "我们等到他回来，再一起吃饭。", "error_description": "错误：“到”被重复写了一次，“等到”后面多出一个“到”。正确：“等到”是一个词，后面直接接“他回来”这样的事件。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '925ff1f8-9638-4c99-a47e-c4dcf897ebd8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12771, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c02ee696-eb52-4659-90f1-cdd91367f0cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12771, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c02ee696-eb52-4659-90f1-cdd91367f0cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12771, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "用来种植农作物（如水稻、蔬菜）的土地。", "primary_collocate": null, "pronunciation": "nóng tián", "ipa": "nʊŋ˧˥ tʰiɛn˧˥", "syllable_count": 2, "sentences": [{"text": "例如，在中亚与北非的古老绿洲系统中，人们通过精密设计的灌溉网络——如坎儿井（qanat）——将高山融雪水引至低地农田。", "target_word": "农田", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "等到干旱时，再把这些水用来灌溉农田。", "target_word": "农田", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "农田里种着水稻和蔬菜。", "target_word": "农田", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天，农民在农田里忙着种菜。", "target_word": "农田", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雨过后，农田里全是水。", "target_word": "农田", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这片农田离村子很近。", "target_word": "农田", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他每天早上去农田浇水。", "target_word": "农田", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "工人在农田旁边修了一条水渠。", "target_word": "农田", "complexity_tier": "T3", "furigana": "gōng rén zài nóng tián páng biān xiū le yì tiáo shuǐ qú", "sentence_source": "generated"}, {"text": "农田里的稻子黄了。", "target_word": "农田", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "农民把水引到农田里。", "target_word": "农田", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "農田", "label": "繁体"}, {"form": "片", "label": "量词"}, {"form": "农田水利", "label": "复合"}], "register": "中性", "sense_fingerprint": "用于种植水稻、蔬菜等农作物的耕地", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e003bea1-9a51-40cb-91ca-bdd0a7fd19d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12771, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "海洋", "is_correct": false, "explanation": "语义：海洋不是灌溉的对象，“引至低地”后面接“海洋”，与句中的灌溉网络不符。"}, {"text": "教室", "is_correct": false, "explanation": "语义：教室与灌溉无关，句子讲的是把融雪水引到需要浇灌的低地。"}, {"text": "矿山", "is_correct": false, "explanation": "搭配：“灌溉网络”“融雪水”搭配的是耕地，矿山不是引水灌溉的对象。"}, {"text": "农田", "is_correct": true, "explanation": "农田是种植农作物的土地，正是灌溉水要引去的地方。"}], "explanations": {"海洋": "语义：海洋不是灌溉的对象，“引至低地”后面接“海洋”，与句中的灌溉网络不符。", "教室": "语义：教室与灌溉无关，句子讲的是把融雪水引到需要浇灌的低地。", "矿山": "搭配：“灌溉网络”“融雪水”搭配的是耕地，矿山不是引水灌溉的对象。", "农田": "农田是种植农作物的土地，正是灌溉水要引去的地方。"}, "sentence_index": 0, "correct_answer": "农田"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他大学的专业是农田。", "explanation": "这里应该用〈农业〉。农田指种庄稼的土地，专业名称要用农业。"}, {"text": "我家门口有一间农田。", "explanation": "这里应该用〈片〉。农田是一大片土地，不能用量词“间”，间多用于房屋。"}, {"text": "他每天在农田里练习游泳。", "explanation": "这里应该用〈游泳池〉。农田是种植农作物的土地，不是游泳的地方，练游泳要去游泳池。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c02ee696-eb52-4659-90f1-cdd91367f0cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12771, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "银行", "is_correct": false, "explanation": "语义：银行与浇水无关，去银行浇水不合常理。"}, {"text": "游泳池", "is_correct": false, "explanation": "语义：游泳池是注满水的场所，不需要人去浇水，与句意不合。"}, {"text": "电影院", "is_correct": false, "explanation": "语义：电影院不需要浇水，句子说的是去种植作物的地方。"}, {"text": "农田", "is_correct": true, "explanation": "农田是种植作物的地方，早上去农田浇水符合常识。"}], "explanations": {"银行": "语义：银行与浇水无关，去银行浇水不合常理。", "游泳池": "语义：游泳池是注满水的场所，不需要人去浇水，与句意不合。", "电影院": "语义：电影院不需要浇水，句子说的是去种植作物的地方。", "农田": "农田是种植作物的地方，早上去农田浇水符合常识。"}, "sentence_index": 6, "correct_answer": "农田"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们一家住在一间农田里。", "explanation": "这里应该用〈农舍〉。农田是耕地，不是住的地方，住房要说农舍。"}, {"text": "这片农田结满了苹果。", "explanation": "这里应该用〈果园〉。苹果长在树上，种果树的地方要说果园，农田种的是庄稼。"}, {"text": "他每天都在干农田。", "explanation": "这里应该用〈农活〉。农田是土地，不是劳动，干的是农活。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c02ee696-eb52-4659-90f1-cdd91367f0cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12771, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "村子东边有一座农田。", "corrected_sentence": "村子东边有一块农田。", "error_description": "量词错误：“农田”是一大片土地，应该用“块”或“片”，不能用“座”（座多用于山、楼房）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c02ee696-eb52-4659-90f1-cdd91367f0cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12771, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "春天，农民农田里播种。", "corrected_sentence": "春天，农民在农田里播种。", "error_description": "介词缺失：表示地点的“农田”前要加“在”，应说“在农田里”，不能直接说“农田里”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c02ee696-eb52-4659-90f1-cdd91367f0cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
