INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12775, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "小米，又称粟米，是禾本科植物谷子（粟）去壳后的籽实，颗粒细小，颜色淡黄，常被用作粮食或煮粥食用。", "primary_collocate": null, "pronunciation": "xiǎo mǐ", "ipa": "ɕiɑʊ˨˩˦ mi˨˩˦", "syllable_count": 2, "sentences": [{"text": "他们还知道哪些作物耐旱，比如高粱和小米。", "target_word": "小米", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "我早上煮了一锅小米，加了红枣。", "target_word": "小米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小米的颗粒很小，颜色是淡黄的。", "target_word": "小米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈买了一斤小米回来煮粥。", "target_word": "小米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北方人常吃小米，南方人更爱吃米饭。", "target_word": "小米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小米是用谷子去壳做成的。", "target_word": "小米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他胃不好，妈妈每天给他买小米，煮粥喝。", "target_word": "小米", "complexity_tier": "T3", "furigana": "tā wèi bù hǎo, māma měi tiān gěi tā mǎi xiǎomǐ, zhǔ zhōu hē.", "sentence_source": "generated"}, {"text": "小鸟在地上啄着小米。", "target_word": "小米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这袋小米是奶奶从老家带来的。", "target_word": "小米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小米放在水里煮一会儿就软了。", "target_word": "小米", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一粒小米", "label": "量词"}, {"form": "小米粥", "label": "复合"}], "register": "中性", "sense_fingerprint": "颗粒细小淡黄的谷物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2daf036-d3ee-4a6e-8456-4cf29727c315') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12775, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "小米", "is_correct": true, "explanation": "正确：小米，颗粒细小、颜色淡黄的谷物。"}, {"text": "小麦", "is_correct": false, "explanation": "mài（第四声）与 mǐ（第三声）韵母与声调都不同，意思是小麦。"}, {"text": "小名", "is_correct": false, "explanation": "míng（第二声）与 mǐ（第三声）韵尾不同（ing 与 i），声调也不同，意思是小名（乳名）。"}, {"text": "小明", "is_correct": false, "explanation": "míng（第二声）与 mǐ（第三声）韵尾不同，声调也不同，意思是小明（人名）。"}, {"text": "小美", "is_correct": false, "explanation": "měi（第三声）与 mǐ（第三声）韵母不同（ei 与 i），声调相同，意思是小美（人名）。"}], "explanations": {"小米": "正确：小米，颗粒细小、颜色淡黄的谷物。", "小麦": "mài（第四声）与 mǐ（第三声）韵母与声调都不同，意思是小麦。", "小名": "míng（第二声）与 mǐ（第三声）韵尾不同（ing 与 i），声调也不同，意思是小名（乳名）。", "小明": "míng（第二声）与 mǐ（第三声）韵尾不同，声调也不同，意思是小明（人名）。", "小美": "měi（第三声）与 mǐ（第三声）韵母不同（ei 与 i），声调相同，意思是小美（人名）。"}, "sentence_index": null, "correct_answer": "小米"}, "level_3": {"options": [{"text": "小米", "is_correct": true, "explanation": "正确：高粱和小米都是耐旱的作物，与句意相符。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机不是作物，不能和高粱并列说“耐旱的作物”。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车不是作物，与“耐旱的作物”的语境冲突。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：“耐旱”修饰作物，不能说“耐旱的石头”。"}], "explanations": {"小米": "正确：高粱和小米都是耐旱的作物，与句意相符。", "手机": "语义：手机不是作物，不能和高粱并列说“耐旱的作物”。", "汽车": "语义：汽车不是作物，与“耐旱的作物”的语境冲突。", "石头": "搭配：“耐旱”修饰作物，不能说“耐旱的石头”。"}, "sentence_index": 0, "correct_answer": "小米"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妹妹的小名叫小米，她很可爱。", "explanation": "这里的〈小米〉是人的小名，不是粮食，与粮食的意思不符。"}, {"text": "妈妈在厨房里切小米，准备炒菜。", "explanation": "这里应该用〈土豆〉。切要用于块状的菜，小米是颗粒状的粮食，不能切。"}, {"text": "早上我喝了一碗小米。", "explanation": "这里应该用〈牛奶〉。喝的是液体，小米是颗粒状粮食，不能喝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad57f395-052a-408d-9832-25e9deaf0d13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12775, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "小米", "is_correct": true, "explanation": "正确：小米，颗粒细小、颜色淡黄的谷物。"}, {"text": "小鸡", "is_correct": false, "explanation": "jī（第一声）与 mǐ（第三声）声母与声调都不同，意思是小鸡。"}, {"text": "小磨", "is_correct": false, "explanation": "mò（第四声）与 mǐ（第三声）韵母与声调不同，意思是小磨（石磨）。"}, {"text": "小弟", "is_correct": false, "explanation": "dì（第四声）与 mǐ（第三声）声母与声调都不同，意思是小弟（年轻的弟弟或晚辈）。"}, {"text": "小妹", "is_correct": false, "explanation": "mèi（第四声）与 mǐ（第三声）韵母与声调不同，意思是小妹（妹妹）。"}], "explanations": {"小米": "正确：小米，颗粒细小、颜色淡黄的谷物。", "小鸡": "jī（第一声）与 mǐ（第三声）声母与声调都不同，意思是小鸡。", "小磨": "mò（第四声）与 mǐ（第三声）韵母与声调不同，意思是小磨（石磨）。", "小弟": "dì（第四声）与 mǐ（第三声）声母与声调都不同，意思是小弟（年轻的弟弟或晚辈）。", "小妹": "mèi（第四声）与 mǐ（第三声）韵母与声调不同，意思是小妹（妹妹）。"}, "sentence_index": null, "correct_answer": "小米"}, "level_3": {"options": [{"text": "小米", "is_correct": true, "explanation": "正确：妈妈买小米煮粥喝，与句意相符。"}, {"text": "西瓜", "is_correct": false, "explanation": "搭配：“煮粥”的主料要用粮食，西瓜不用来煮粥。"}, {"text": "钢笔", "is_correct": false, "explanation": "语义：钢笔不能吃，与“煮粥喝”的语境冲突。"}, {"text": "手套", "is_correct": false, "explanation": "语义：手套不能煮来喝，与“煮粥喝”的语境冲突。"}], "explanations": {"小米": "正确：妈妈买小米煮粥喝，与句意相符。", "西瓜": "搭配：“煮粥”的主料要用粮食，西瓜不用来煮粥。", "钢笔": "语义：钢笔不能吃，与“煮粥喝”的语境冲突。", "手套": "语义：手套不能煮来喝，与“煮粥喝”的语境冲突。"}, "sentence_index": 6, "correct_answer": "小米"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我昨天买了一部小米，用来打电话。", "explanation": "这里的〈小米〉指小米手机的品牌，不是粮食，与粮食的意思不符。"}, {"text": "妈妈在厨房里包小米。", "explanation": "这里应该用〈饺子〉。包的是饺子、包子这类有皮的食物，小米不能用来包。"}, {"text": "妈妈用石磨把小米磨成豆浆。", "explanation": "这里应该用〈黄豆〉。豆浆要用黄豆等豆类磨成，小米磨不出豆浆。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad57f395-052a-408d-9832-25e9deaf0d13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12775, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "奶奶今天买了一只小米。", "corrected_sentence": "奶奶今天买了一斤小米。", "error_description": "量词错误：小米是散装粮食，应说“一斤小米”或“一袋小米”，不能用“只”（“只”用于动物或成对物品中的一个）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad57f395-052a-408d-9832-25e9deaf0d13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12775, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈昨天买了两斤小米们。", "corrected_sentence": "妈妈昨天买了两斤小米。", "error_description": "词形错误：小米是不可数的粮食，不能加“们”，应直接说“两斤小米”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad57f395-052a-408d-9832-25e9deaf0d13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
