INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12779, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "山坡是指山体倾斜的表面，通常覆盖着土壤和植物。", "primary_collocate": null, "pronunciation": "shān pō", "ipa": "ʂan˥ pʰo˥", "syllable_count": 2, "sentences": [{"text": "山坡被改成一层一层的平台，这样可以减少水土流失。", "target_word": "山坡", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "羊在山坡上吃草。", "target_word": "山坡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们坐在山坡上看日落。", "target_word": "山坡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山坡上开满了黄色的花。", "target_word": "山坡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩从山坡上跑下来。", "target_word": "山坡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个山坡太陡，自行车骑不上去。", "target_word": "山坡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨以后，山坡变得很滑。", "target_word": "山坡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山坡上种着一排排茶树。", "target_word": "山坡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在山坡下搭了一个小帐篷。", "target_word": "山坡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天，山坡上都是白雪。", "target_word": "山坡", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个山坡", "label": "量词"}, {"form": "一片山坡", "label": "量词"}], "register": "中性", "sense_fingerprint": "山体倾斜的表面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2daf036-d3ee-4a6e-8456-4cf29727c315') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12779, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "山坡", "is_correct": true, "explanation": "山坡是倾斜的地表，可以改造成一层一层的平台，从而减少水土流失，符合句意。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流是水体，不是倾斜的地表，改不成梯田式的平台，也与减少水土流失无关。"}, {"text": "大海", "is_correct": false, "explanation": "语义：大海是水域，没有可以改造的土地，句中的水土流失也与海无关。"}, {"text": "地平线", "is_correct": false, "explanation": "搭配：“改成”的对象须是可以加工的实体，“地平线”只是视觉上的界线，不能被改造。"}], "explanations": {"山坡": "山坡是倾斜的地表，可以改造成一层一层的平台，从而减少水土流失，符合句意。", "河流": "语义：河流是水体，不是倾斜的地表，改不成梯田式的平台，也与减少水土流失无关。", "大海": "语义：大海是水域，没有可以改造的土地，句中的水土流失也与海无关。", "地平线": "搭配：“改成”的对象须是可以加工的实体，“地平线”只是视觉上的界线，不能被改造。"}, "sentence_index": 0, "correct_answer": "山坡"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家门前有一棵山坡。", "explanation": "这里应该用〈片〉或〈个〉。〈棵〉用于树木，山坡是地形，不能用“棵”来计量。"}, {"text": "我们走进了一个山坡。", "explanation": "这里应该用〈山洞〉。山坡是倾斜的地表，没有内部空间，不能说“走进”。"}, {"text": "这片平坦的山坡是一个很好的操场。", "explanation": "这里应该用〈平地〉。山坡是倾斜的地表，不能说“平坦的山坡”；平坦的地面才说〈平地〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad57f395-052a-408d-9832-25e9deaf0d13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12779, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "山坡", "is_correct": true, "explanation": "山坡是倾斜的地表，下雨后会变得湿滑，符合句意。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“很滑”多用于路面、地板等有表面的物体，不能说空气很滑。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不是可以踩踏的地面，下雨后不会“变得很滑”。"}, {"text": "星星", "is_correct": false, "explanation": "语义：星星是天体，不是地表，与“下雨以后变得很滑”的情境无关。"}], "explanations": {"山坡": "山坡是倾斜的地表，下雨后会变得湿滑，符合句意。", "空气": "搭配：“很滑”多用于路面、地板等有表面的物体，不能说空气很滑。", "天空": "语义：天空不是可以踩踏的地面，下雨后不会“变得很滑”。", "星星": "语义：星星是天体，不是地表，与“下雨以后变得很滑”的情境无关。"}, "sentence_index": 6, "correct_answer": "山坡"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "山坡从山顶一直流到村子里。", "explanation": "这里应该用〈河流〉。“流”指水的移动，山坡是陆地，不会流动。"}, {"text": "工人用卡车把山坡运到了工地上。", "explanation": "这里应该用〈泥土〉。山坡是固定的大片地形，不能整体运走，运走的只能是泥土之类。"}, {"text": "山坡上飘着几只小船。", "explanation": "这里应该用〈湖面〉。船能飘在水面上，山坡是陆地表面，不能“飘”着船。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad57f395-052a-408d-9832-25e9deaf0d13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12779, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们在一棵山坡上搭了一顶帐篷。", "corrected_sentence": "我们在一片山坡上搭了一顶帐篷。", "error_description": "量词错误：「一棵山坡」应为「一片山坡」。〈棵〉用于树木，山坡是地形，应用〈片〉来计量。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad57f395-052a-408d-9832-25e9deaf0d13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12779, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "天晴以后，山坡变得干很。", "corrected_sentence": "天晴以后，山坡变得很干。", "error_description": "补语错误：程度副词“很”应放在形容词前，应说“变得很干”，不说“变得干很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad57f395-052a-408d-9832-25e9deaf0d13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
