INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12780, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "表示将原有的内容或形式改变为另一种。", "primary_collocate": null, "pronunciation": "gǎi chéng", "ipa": "kai˨˩˦ ʈʂʰɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "山坡被改成一层一层的平台，这样可以减少水土流失。", "target_word": "改成", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "我把这个房间改成了书房。", "target_word": "改成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把考试时间改成下周三。", "target_word": "改成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想把复杂的名字改成简单的名字。", "target_word": "改成", "complexity_tier": "T3", "furigana": "tā xiǎng bǎ fùzá de míngzi gǎi chéng jiǎndān de míngzi", "sentence_source": "generated"}, {"text": "这家老店已经改成饭馆了。", "target_word": "改成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把“你好”改成“您好”。", "target_word": "改成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们把圆桌改成了长桌。", "target_word": "改成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把红色的灯改成了白色。", "target_word": "改成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司把旧仓库改成了咖啡店。", "target_word": "改成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会议从上午改成下午。", "target_word": "改成", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "改成了", "label": "体标"}, {"form": "改成过", "label": "体标"}], "register": "中性", "sense_fingerprint": "把原有的内容或形式改为另一种", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2daf036-d3ee-4a6e-8456-4cf29727c315') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12780, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "改成", "is_correct": true, "explanation": "改成（gǎi chéng）：把原有的内容或形式改为另一种，即本词。"}, {"text": "搞成", "is_correct": false, "explanation": "gǎo（第三声）与 gǎi（第三声）韵母不同（ao 与 ai），意思是“弄成、做成”。"}, {"text": "盖成", "is_correct": false, "explanation": "gài（第四声）与 gǎi（第三声）声调不同，意思是“盖好、建成”。"}, {"text": "改称", "is_correct": false, "explanation": "chēng（第一声）与 chéng（第二声）声调不同，意思是“改变名称”。"}], "explanations": {"改成": "改成（gǎi chéng）：把原有的内容或形式改为另一种，即本词。", "搞成": "gǎo（第三声）与 gǎi（第三声）韵母不同（ao 与 ai），意思是“弄成、做成”。", "盖成": "gài（第四声）与 gǎi（第三声）声调不同，意思是“盖好、建成”。", "改称": "chēng（第一声）与 chéng（第二声）声调不同，意思是“改变名称”。"}, "sentence_index": null, "correct_answer": "改成"}, "level_3": {"options": [{"text": "改成", "is_correct": true, "explanation": "改成：把山坡改造为一层一层的平台，符合句意。"}, {"text": "涂成", "is_correct": false, "explanation": "语义：涂是把颜料抹在表面，不能让山坡变成平台，也谈不上减少水土流失。"}, {"text": "画成", "is_correct": false, "explanation": "语义：画是描绘图像，画出来的东西无法减少水土流失。"}, {"text": "染成", "is_correct": false, "explanation": "搭配：“染成”后通常接颜色，不接“平台”，不能说“山坡被染成一层一层的平台”。"}], "explanations": {"改成": "改成：把山坡改造为一层一层的平台，符合句意。", "涂成": "语义：涂是把颜料抹在表面，不能让山坡变成平台，也谈不上减少水土流失。", "画成": "语义：画是描绘图像，画出来的东西无法减少水土流失。", "染成": "搭配：“染成”后通常接颜色，不接“平台”，不能说“山坡被染成一层一层的平台”。"}, "sentence_index": 0, "correct_answer": "改成"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个孩子很快改成了大人。", "explanation": "这里应该用〈变成〉。“改成”指把内容或形式改为另一种，人的成长不用“改成”。"}, {"text": "他改成了我的作业。", "explanation": "这里应该用〈修改〉。“改成”后要接变化后的结果，不能直接带“我的作业”这样的对象。"}, {"text": "我们一家从北京改成了上海。", "explanation": "这里应该用〈搬到〉。“改成”用于内容或形式的改变，人搬迁到另一地不说“改成”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad57f395-052a-408d-9832-25e9deaf0d13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12780, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "改成", "is_correct": true, "explanation": "改成：把圆桌改造为长桌，符合句意。"}, {"text": "煮成", "is_correct": false, "explanation": "语义：煮是用水加热食物，圆桌不能被煮成长桌，句意不通。"}, {"text": "写成", "is_correct": false, "explanation": "语义：写是书写文字，不能把圆桌写成长桌。"}, {"text": "烤成", "is_correct": false, "explanation": "搭配：“烤”多用于食物，不说“烤成长桌”。"}], "explanations": {"改成": "改成：把圆桌改造为长桌，符合句意。", "煮成": "语义：煮是用水加热食物，圆桌不能被煮成长桌，句意不通。", "写成": "语义：写是书写文字，不能把圆桌写成长桌。", "烤成": "搭配：“烤”多用于食物，不说“烤成长桌”。"}, "sentence_index": 6, "correct_answer": "改成"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她大学毕业后改成了老师。", "explanation": "这里应该用〈成为〉。“改成”用于内容或形式的改变，人的身份变化不说“改成”。"}, {"text": "他的成绩改成了很好。", "explanation": "这里应该用〈提高〉。“改成”用于内容或形式的改变，成绩上升应说“提高”，不能说“改成很好”。"}, {"text": "他们改成了座位。", "explanation": "这里应该用〈交换〉。“改成”后接的是变化后的结果，“改成座位”说不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad57f395-052a-408d-9832-25e9deaf0d13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12780, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我把这个仓库了改成厨房。", "corrected_sentence": "我把这个仓库改成了厨房。", "error_description": "体标位置错误：「了」不能放在「改成」之前，应置于「改成」之后，即「改成了厨房」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad57f395-052a-408d-9832-25e9deaf0d13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12780, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们把客厅改成着书房。", "corrected_sentence": "我们把客厅改成了书房。", "error_description": "“了”误用为“着”：「改成着书房」应为「改成了书房」。“着”表示状态持续，这里指已完成的变化，应用“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad57f395-052a-408d-9832-25e9deaf0d13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
