INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12782, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指土地表面的土壤被水流冲刷而流失的现象。", "primary_collocate": null, "pronunciation": "shuǐ tǔ liú shī", "ipa": "ʂweɪ̯˨˩˦ tʰu˨˩˦ li̯oʊ̯˧˥ ʂɨ˥", "syllable_count": 4, "sentences": [{"text": "山坡被改成一层一层的平台，这样可以减少水土流失。", "target_word": "水土流失", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "山上没有树，水土流失就很严重。", "target_word": "水土流失", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "种树可以防止水土流失。", "target_word": "水土流失", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个地方的水土流失越来越严重。", "target_word": "水土流失", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府正在想办法解决水土流失的问题。", "target_word": "水土流失", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雨以后，山坡上的水土流失特别明显。", "target_word": "水土流失", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水土流失会让田里的好土越来越少。", "target_word": "水土流失", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们讲了水土流失的原因。", "target_word": "水土流失", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水变黄，是因为那里有水土流失。", "target_word": "水土流失", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "修梯田是减少水土流失的好办法。", "target_word": "水土流失", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "名词：土壤被雨水冲走的自然或环境现象", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18a0cdcb-cafe-4630-adc0-3cff093ef8e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12782, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "水土流失", "is_correct": true, "explanation": "水土流失指土壤被水冲走，修梯田正是为了减少它。"}, {"text": "植被", "is_correct": false, "explanation": "语义：修梯田是为了保护植被，不会减少植被。"}, {"text": "耕地", "is_correct": false, "explanation": "语义：梯田是为了保住耕地，句子里减少的不可能是耕地。"}, {"text": "水土保持", "is_correct": false, "explanation": "搭配：“水土保持”是要做的好事，不能跟“减少”搭配。"}], "explanations": {"水土流失": "水土流失指土壤被水冲走，修梯田正是为了减少它。", "植被": "语义：修梯田是为了保护植被，不会减少植被。", "耕地": "语义：梯田是为了保住耕地，句子里减少的不可能是耕地。", "水土保持": "搭配：“水土保持”是要做的好事，不能跟“减少”搭配。"}, "sentence_index": 0, "correct_answer": "水土流失"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个地方的水土流失越来越聪明了。", "explanation": "这里应该用〈严重〉。“聪明”形容人，水土流失不能说“聪明”。"}, {"text": "这个地方有一只水土流失。", "explanation": "这里应该用〈种〉。“只”用于动物或小东西，不能用来数水土流失。"}, {"text": "我们的工作是水土流失。", "explanation": "这里应该用〈水土保持〉。水土保持是防治水土流失的工作，水土流失本身是要防治的坏现象，不能说成“工作”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'daf36125-14a4-4db2-9f79-fbeb173290ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12782, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "水土流失", "is_correct": true, "explanation": "水土流失指土壤被水冲走，句子说的正是它让好土越来越少。"}, {"text": "粮食", "is_correct": false, "explanation": "语义：粮食不会让田里的土变少，句子说的是土减少。"}, {"text": "草原", "is_correct": false, "explanation": "搭配：“草原”与“田里的好土”不搭，句子讲的是田里的情况。"}, {"text": "良田", "is_correct": false, "explanation": "语义：良田本身就是好土，不会让好土变少。"}], "explanations": {"水土流失": "水土流失指土壤被水冲走，句子说的正是它让好土越来越少。", "粮食": "语义：粮食不会让田里的土变少，句子说的是土减少。", "草原": "搭配：“草原”与“田里的好土”不搭，句子讲的是田里的情况。", "良田": "语义：良田本身就是好土，不会让好土变少。"}, "sentence_index": 6, "correct_answer": "水土流失"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这里的水土流失很好吃。", "explanation": "这里应该用〈严重〉。“好吃”形容食物，水土流失不是食物，不能说“好吃”。"}, {"text": "这里的水土流失很有效。", "explanation": "这里应该用〈治理〉。“有效”形容治理措施，不能形容水土流失。"}, {"text": "这次水土流失吹得很厉害。", "explanation": "这里应该用〈沙尘暴〉。沙尘暴会“吹”，水土流失是土被水冲走，不能说“吹”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'daf36125-14a4-4db2-9f79-fbeb173290ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12782, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只水土流失对农田很不好。", "corrected_sentence": "这种水土流失对农田很不好。", "error_description": "“只”用于动物或小的东西，水土流失这类现象应该用量词“种”，应说“这种水土流失”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'daf36125-14a4-4db2-9f79-fbeb173290ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12782, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这里的水土流失了很严重。", "corrected_sentence": "这里的水土流失很严重。", "error_description": "“了”不能加在名词“水土流失”后面，这里应直接说“这里的水土流失很严重”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'daf36125-14a4-4db2-9f79-fbeb173290ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
