INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12783, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'daf36125-14a4-4db2-9f79-fbeb173290ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12783, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指水从云中落下来的自然现象。", "primary_collocate": null, "pronunciation": "xià yǔ", "ipa": "ɕi̯ɑ˥˩ y˨˩˦", "syllable_count": 2, "sentences": [{"text": "如果长时间不下雨，庄稼就会干死。", "target_word": "下雨", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "下雨时，水不会很快流走，而是慢慢渗入土壤。", "target_word": "下雨", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "今天下雨，我们不去公园了。", "target_word": "下雨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天阴了，好像要下雨。", "target_word": "下雨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天夜里下雨了，地上还是湿的。", "target_word": "下雨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里春天常常下雨。", "target_word": "下雨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别忘了带伞，外面在下雨。", "target_word": "下雨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨的时候，路上的车很少。", "target_word": "下雨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一下雨，空气就变得很新鲜。", "target_word": "下雨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我最喜欢听下雨的声音。", "target_word": "下雨", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "下了雨", "label": "体标（了）"}, {"form": "下过雨", "label": "体标（过）"}, {"form": "下大雨", "label": "离合（插入定语）"}], "register": "中性", "sense_fingerprint": "动词：云里的水落到地面，天气现象", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18a0cdcb-cafe-4630-adc0-3cff093ef8e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12783, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "下雨", "is_correct": true, "explanation": "下雨是水从云中落下来，句子说长时间不下雨，庄稼会缺水干死。"}, {"text": "结冰", "is_correct": false, "explanation": "语义：结冰说的是温度变化，句子讲的是缺水，两者无关。"}, {"text": "说话", "is_correct": false, "explanation": "语义：庄稼不说话，句子说的是缺水导致庄稼干死。"}, {"text": "开会", "is_correct": false, "explanation": "语义：开会是人的活动，与庄稼是否干死无关，句子说的是缺水。"}], "explanations": {"下雨": "下雨是水从云中落下来，句子说长时间不下雨，庄稼会缺水干死。", "结冰": "语义：结冰说的是温度变化，句子讲的是缺水，两者无关。", "说话": "语义：庄稼不说话，句子说的是缺水导致庄稼干死。", "开会": "语义：开会是人的活动，与庄稼是否干死无关，句子说的是缺水。"}, "sentence_index": 0, "correct_answer": "下雨"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "昨晚下雨，把窗户吹开了。", "explanation": "这里应该用〈刮风〉。把窗户吹开是风的作用，下雨不能吹东西。"}, {"text": "他很会下雨，大家都佩服他。", "explanation": "这里应该用〈唱歌〉。唱歌是人能做的本领，下雨是天气现象，不能说“很会下雨”。"}, {"text": "我从二楼下雨到一楼。", "explanation": "语义：这里是“下楼”的意思，“下雨”不能表示从楼上走到楼下。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'daf36125-14a4-4db2-9f79-fbeb173290ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12783, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "下雨", "is_correct": true, "explanation": "下雨是天气现象，句子提醒带伞是因为外面在下雨。"}, {"text": "打鼾", "is_correct": false, "explanation": "语义：打鼾是人睡觉时的声音，外面不会打鼾。"}, {"text": "生病", "is_correct": false, "explanation": "语义：“外面”是地方，不会生病。"}, {"text": "发烧", "is_correct": false, "explanation": "搭配：“发烧”是人的病，不能用在“外面”后面。"}], "explanations": {"下雨": "下雨是天气现象，句子提醒带伞是因为外面在下雨。", "打鼾": "语义：打鼾是人睡觉时的声音，外面不会打鼾。", "生病": "语义：“外面”是地方，不会生病。", "发烧": "搭配：“发烧”是人的病，不能用在“外面”后面。"}, "sentence_index": 6, "correct_answer": "下雨"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他去年下雨了，现在找工作很难。", "explanation": "这里应该用〈下岗〉。下岗指失去工作岗位，下雨是天气现象，不能用来说人失去工作。"}, {"text": "我每天五点下雨。", "explanation": "这里应该用〈下班〉。下班指工作结束离开单位，下雨是天气现象，不能说几点“下雨”。"}, {"text": "周末我们一起下雨吧。", "explanation": "这里应该用〈下棋〉。下棋是一种游戏，下雨是天气现象，不能说“一起下雨”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'daf36125-14a4-4db2-9f79-fbeb173290ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12783, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "昨天下了一个雨，路还是湿的。", "corrected_sentence": "昨天下了一阵雨，路还是湿的。", "error_description": "量词误用：雨应用“阵”计量，应说“一阵雨”，不能说“一个雨”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'daf36125-14a4-4db2-9f79-fbeb173290ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12783, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "前几天下雨过，地还是湿的。", "corrected_sentence": "前几天下过雨，地还是湿的。", "error_description": "体标“过”要紧跟动词，应说“下过雨”，不能拆成“下雨过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'daf36125-14a4-4db2-9f79-fbeb173290ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12784, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'daf36125-14a4-4db2-9f79-fbeb173290ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12784, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'daf36125-14a4-4db2-9f79-fbeb173290ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12784, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "液体流动而消失；也比喻时间等逝去。", "primary_collocate": null, "pronunciation": "liú zǒu", "ipa": "li̯oʊ̯˧˥ tsoʊ̯˨˩˦", "syllable_count": 2, "sentences": [{"text": "下雨时，水不会很快流走，而是慢慢渗入土壤。", "target_word": "流走", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "浴缸里的水慢慢流走了。", "target_word": "流走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水带着树叶流走了。", "target_word": "流走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打开门，房间里的水很快就流走了。", "target_word": "流走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "时间像水一样，一天天流走了。", "target_word": "流走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小河里的水流走了，只剩下石头。", "target_word": "流走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨水从屋顶流走，不会留在院子里。", "target_word": "流走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你看，那片叶子跟着水流走了。", "target_word": "流走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们坐在河边，看着水慢慢流走。", "target_word": "流走", "complexity_tier": "T3", "furigana": "wǒmen zuò zài hébiān, kànzhe shuǐ mànmàn liúzǒu.", "sentence_source": "generated"}, {"text": "美好的日子慢慢流走，再也回不来。", "target_word": "流走", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "流走了", "label": "体标（了）"}, {"form": "流不走", "label": "可能补语（否定）"}], "register": "中性", "sense_fingerprint": "动词：液体流开不见了，也比喻时间逝去", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18a0cdcb-cafe-4630-adc0-3cff093ef8e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12784, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "流走", "is_correct": true, "explanation": "流走 liú zǒu：液体流开、不见了，是这个词的本义。"}, {"text": "留足", "is_correct": false, "explanation": "留足 liú zú：足（zú）与走（zǒu）韵母与声调均不同，指充分留出。"}, {"text": "游走", "is_correct": false, "explanation": "游走 yóu zǒu：游（yóu）与流（liú）声母不同，指四处走动，不是液体流开。"}, {"text": "留守", "is_correct": false, "explanation": "留守 liú shǒu：shǒu 与 zǒu 声母不同（sh 与 z），指留在原地看守。"}], "explanations": {"流走": "流走 liú zǒu：液体流开、不见了，是这个词的本义。", "留足": "留足 liú zú：足（zú）与走（zǒu）韵母与声调均不同，指充分留出。", "游走": "游走 yóu zǒu：游（yóu）与流（liú）声母不同，指四处走动，不是液体流开。", "留守": "留守 liú shǒu：shǒu 与 zǒu 声母不同（sh 与 z），指留在原地看守。"}, "sentence_index": null, "correct_answer": "流走"}, "level_3": {"options": [{"text": "流走", "is_correct": true, "explanation": "流走：液体流开消失，与“慢慢渗入土壤”形成对比，符合句意。"}, {"text": "沸腾", "is_correct": false, "explanation": "语义：下雨时的水不会沸腾，与“下雨时”的情境矛盾。"}, {"text": "结冰", "is_correct": false, "explanation": "语义：句子说水没有停在地表，而是渗进土壤，“结冰”会让水留下，与句意矛盾。"}, {"text": "凝固", "is_correct": false, "explanation": "搭配：水一般说“结冰”，“凝固”多用于血液、水泥等物质。"}], "explanations": {"流走": "流走：液体流开消失，与“慢慢渗入土壤”形成对比，符合句意。", "沸腾": "语义：下雨时的水不会沸腾，与“下雨时”的情境矛盾。", "结冰": "语义：句子说水没有停在地表，而是渗进土壤，“结冰”会让水留下，与句意矛盾。", "凝固": "搭配：水一般说“结冰”，“凝固”多用于血液、水泥等物质。"}, "sentence_index": 0, "correct_answer": "流走"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他趁老师不注意，悄悄流走了。", "explanation": "这里应该用〈溜走〉。流走指液体流开不见，人悄悄离开要用溜走。"}, {"text": "石头从山坡上流走了。", "explanation": "这里应该用〈滚走〉。流走用于液体、时间等流动的东西，石头被推下山要用滚走。"}, {"text": "洪水流走了村里的房子。", "explanation": "这里应该用〈冲走〉。流走是不及物动词，不能带“房子”作宾语，把东西冲离原处要用冲走。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'daf36125-14a4-4db2-9f79-fbeb173290ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12784, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "流走", "is_correct": true, "explanation": "流走：液体离开屋顶、不再留存，与“不会留在院子里”呼应。"}, {"text": "上升", "is_correct": false, "explanation": "语义：雨水从屋顶向下流，不会向上升，与句中的走向矛盾。"}, {"text": "漂浮", "is_correct": false, "explanation": "搭配：“漂浮”要说“在水面上漂浮”，不能直接接“从屋顶”。"}, {"text": "倒流", "is_correct": false, "explanation": "语义：“倒流”指逆向流回，与“从屋顶”的下流路线矛盾。"}], "explanations": {"流走": "流走：液体离开屋顶、不再留存，与“不会留在院子里”呼应。", "上升": "语义：雨水从屋顶向下流，不会向上升，与句中的走向矛盾。", "漂浮": "搭配：“漂浮”要说“在水面上漂浮”，不能直接接“从屋顶”。", "倒流": "语义：“倒流”指逆向流回，与“从屋顶”的下流路线矛盾。"}, "sentence_index": 6, "correct_answer": "流走"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这首歌在民间流走了几百年。", "explanation": "这里应该用〈流传〉。流走表示消失，歌曲代代传下去要用流传。"}, {"text": "她想起母亲，眼泪忍不住流走了。", "explanation": "这里应该用〈流下〉。流走指液体流开消失，眼泪沿脸颊往下淌要用流下。"}, {"text": "小鸟停在树枝上，忽然流走了。", "explanation": "这里应该用〈飞走〉。流走用于液体、时间等流动的东西，鸟离开要用飞走。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'daf36125-14a4-4db2-9f79-fbeb173290ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12784, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "厨房水槽里的水很快就把流走了。", "corrected_sentence": "厨房水槽里的水很快就流走了。", "error_description": "“流走”是不及物动词，不能用在“把”字句里作处置，应去掉“把”，说“水很快就流走了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'daf36125-14a4-4db2-9f79-fbeb173290ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12784, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雨水一会儿就把屋檐流走了。", "corrected_sentence": "雨水一会儿就从屋檐流走了。", "error_description": "“流走”表示液体从某处流开，起点要用“从”引出，不能用“把”处置，应说“从屋檐流走”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'daf36125-14a4-4db2-9f79-fbeb173290ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12785, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'daf36125-14a4-4db2-9f79-fbeb173290ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
