INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12785, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "液体或气体慢慢进入固体或物体的内部。", "primary_collocate": null, "pronunciation": "shèn rù", "ipa": "ʂən˥˩ ʐu˥˩", "syllable_count": 2, "sentences": [{"text": "下雨时，水不会很快流走，而是慢慢渗入土壤。", "target_word": "渗入", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "雨水慢慢渗入泥土里。", "target_word": "渗入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "墨水渗入了纸里，字变模糊了。", "target_word": "渗入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "污水渗入地下，会污染井水。", "target_word": "渗入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把布放进水里，水很快就渗入布中。", "target_word": "渗入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "咖啡洒在桌布上，慢慢渗入了布里。", "target_word": "渗入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨停以后，水渗入沙子，地面很快干了。", "target_word": "渗入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "油渗入木头后，木头的颜色变深了。", "target_word": "渗入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水渗入河岸的泥土，旁边的草长得很好。", "target_word": "渗入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雪化了，雪水渗入田地，让土地变软了。", "target_word": "渗入", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "渗入了", "label": "体标"}, {"form": "渗入过", "label": "体标"}], "register": "中性", "sense_fingerprint": "液体或气体慢慢进入固体或物体的内部", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18a0cdcb-cafe-4630-adc0-3cff093ef8e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12785, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "渗入", "is_correct": true, "explanation": "渗入 shèn rù：液体或气体慢慢进入固体或物体内部。"}, {"text": "深入", "is_correct": false, "explanation": "深入 shēn rù：shēn（第一声）与 shèn（第四声）声调不同，指向深处进入。"}, {"text": "沉入", "is_correct": false, "explanation": "沉入 chén rù：chén 与 shèn 声母不同（ch 与 sh），指下沉到水中等。"}, {"text": "盛入", "is_correct": false, "explanation": "盛入 shèng rù：韵母 eng 与 en 不同，指装进容器里。"}], "explanations": {"渗入": "渗入 shèn rù：液体或气体慢慢进入固体或物体内部。", "深入": "深入 shēn rù：shēn（第一声）与 shèn（第四声）声调不同，指向深处进入。", "沉入": "沉入 chén rù：chén 与 shèn 声母不同（ch 与 sh），指下沉到水中等。", "盛入": "盛入 shèng rù：韵母 eng 与 en 不同，指装进容器里。"}, "sentence_index": null, "correct_answer": "渗入"}, "level_3": {"options": [{"text": "渗入", "is_correct": true, "explanation": "渗入：水进入土壤内部，与“而是慢慢……土壤”的句意一致。"}, {"text": "渗出", "is_correct": false, "explanation": "语义：“渗出”是从里面出来，与“而是慢慢……土壤”的进入方向相反。"}, {"text": "冒出", "is_correct": false, "explanation": "搭配：“冒出”多接“地面”“地表”，不说“冒出土壤”。"}, {"text": "冻结", "is_correct": false, "explanation": "语义：下雨时水不会冻结，句子说水渗进土壤，与冻结矛盾。"}], "explanations": {"渗入": "渗入：水进入土壤内部，与“而是慢慢……土壤”的句意一致。", "渗出": "语义：“渗出”是从里面出来，与“而是慢慢……土壤”的进入方向相反。", "冒出": "搭配：“冒出”多接“地面”“地表”，不说“冒出土壤”。", "冻结": "语义：下雨时水不会冻结，句子说水渗进土壤，与冻结矛盾。"}, "sentence_index": 0, "correct_answer": "渗入"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "汗水从皮肤里渗入了。", "explanation": "这里应该用〈渗出〉。渗入指向内进入，汗水从皮肤里出来要用渗出。"}, {"text": "石头渗入了水底。", "explanation": "这里应该用〈沉入〉。渗入只用于液体或气体慢慢进入，石头整块下沉要用沉入。"}, {"text": "硬币渗入了沙子里。", "explanation": "这里应该用〈埋入〉。渗入是液体或气体慢慢进入，硬币被埋进沙子要用埋入。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'daf36125-14a4-4db2-9f79-fbeb173290ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12785, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "渗入", "is_correct": true, "explanation": "渗入：水进入沙子内部，与“地面很快干了”的结果相呼应。"}, {"text": "覆盖", "is_correct": false, "explanation": "语义：水覆盖在沙子上，地面会变湿，与“地面很快干了”矛盾。"}, {"text": "堆积", "is_correct": false, "explanation": "语义：水堆积在沙子上会形成积水，与“地面很快干了”矛盾。"}, {"text": "泼洒", "is_correct": false, "explanation": "搭配：“泼洒”是人主动把液体撒出，不说“水泼洒沙子”。"}], "explanations": {"渗入": "渗入：水进入沙子内部，与“地面很快干了”的结果相呼应。", "覆盖": "语义：水覆盖在沙子上，地面会变湿，与“地面很快干了”矛盾。", "堆积": "语义：水堆积在沙子上会形成积水，与“地面很快干了”矛盾。", "泼洒": "搭配：“泼洒”是人主动把液体撒出，不说“水泼洒沙子”。"}, "sentence_index": 6, "correct_answer": "渗入"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "子弹渗入了木板。", "explanation": "这里应该用〈射入〉。渗入是液体或气体慢慢进入，子弹高速穿入要用射入。"}, {"text": "针渗入了皮肤。", "explanation": "这里应该用〈扎入〉。渗入是缓慢进入，针快速刺进去要用扎入。"}, {"text": "燕子渗入了树林。", "explanation": "这里应该用〈飞入〉。渗入用于液体或气体，燕子飞进树林要用飞入。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'daf36125-14a4-4db2-9f79-fbeb173290ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12785, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这场雨后，雪水慢慢把渗入了地里。", "corrected_sentence": "这场雨后，雪水慢慢渗入了地里。", "error_description": "“渗入”表示液体自行慢慢进入，不能用于“把”字句，应去掉“把”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'daf36125-14a4-4db2-9f79-fbeb173290ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12785, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "浇下去的水很快就把渗入了土层。", "corrected_sentence": "浇下去的水很快就渗入了土层。", "error_description": "“把”字句中“把”后要紧接被处置的名词，“把渗入了土层”中“把”后直接是动词，结构不成立；“渗入”表示液体自行进入，不用于“把”字句，正确说法是“浇下去的水很快就渗入了土层”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'daf36125-14a4-4db2-9f79-fbeb173290ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
