INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12794, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "现代科技指当代的科学技术，包括信息技术、人工智能、互联网等领域的成果和应用。", "primary_collocate": null, "pronunciation": "xiàn dài kē jì", "ipa": "ɕjɛn˥˩ taɪ˥˩ kʰɤ˥ tɕi˥˩", "syllable_count": 4, "sentences": [{"text": "当地政府也开始重视这些传统智慧，鼓励农民结合现代科技使用它们。", "target_word": "现代科技", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "现代科技让我们的生活更方便。", "target_word": "现代科技", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "现代科技发展得很快，手机越来越聪明。", "target_word": "现代科技", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民用现代科技种菜，产量高了很多。", "target_word": "现代科技", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医院里有很多用现代科技做的机器。", "target_word": "现代科技", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我爷爷不太懂现代科技，不会用智能手机。", "target_word": "现代科技", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校请专家来讲现代科技的变化。", "target_word": "现代科技", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "有了现代科技，我们可以在家视频聊天。", "target_word": "现代科技", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现代科技也给环境带来了一些问题。", "target_word": "现代科技", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家工厂用现代科技提高了产量。", "target_word": "现代科技", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "現代科技", "label": "繁体"}, {"form": "现代科技产品", "label": "复合"}], "register": "中性", "sense_fingerprint": "当代的科学技术及其成果与应用，如信息技术、人工智能", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecc79bd2-c16d-4f8a-a9d7-dab736631f53') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12794, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "现代科技", "is_correct": true, "explanation": "正确。现代科技指当代的科学技术，农民可以把它与传统智慧结合起来使用，语义和搭配都合适。"}, {"text": "外国语言", "is_correct": false, "explanation": "语义：“使用它们”的对象是前文的传统智慧，外国语言不是可以拿来种地的方法，句子读起来不通。"}, {"text": "奢侈品", "is_correct": false, "explanation": "搭配：“结合……使用”后面接的是方法或技术，奢侈品是消费品，不能和“使用它们”搭配。"}, {"text": "体育项目", "is_correct": false, "explanation": "语义：体育项目是一种活动，不是农民种地时可以使用的方法，与“鼓励农民使用”的语境不符。"}], "explanations": {"现代科技": "正确。现代科技指当代的科学技术，农民可以把它与传统智慧结合起来使用，语义和搭配都合适。", "外国语言": "语义：“使用它们”的对象是前文的传统智慧，外国语言不是可以拿来种地的方法，句子读起来不通。", "奢侈品": "搭配：“结合……使用”后面接的是方法或技术，奢侈品是消费品，不能和“使用它们”搭配。", "体育项目": "语义：体育项目是一种活动，不是农民种地时可以使用的方法，与“鼓励农民使用”的语境不符。"}, "sentence_index": 0, "correct_answer": "现代科技"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家医院新买了一台现代科技。", "explanation": "这里应该用〈项〉。〈台〉用于机器、设备，现代科技是抽象的技术领域，不能用“台”来计数。"}, {"text": "他喝了很多现代科技。", "explanation": "这里应该用〈茶〉。“喝”的对象应是饮料，现代科技是技术领域，不能被“喝”。"}, {"text": "这所大学请来了很多现代科技。", "explanation": "这里应该用〈专家〉。“请来”的对象应是人，现代科技是技术领域，不能被请来，请来的应是〈专家〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba26d35-0c52-4e06-afc7-91807d7bd45c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12794, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "现代科技", "is_correct": true, "explanation": "正确。现代科技是可以讲解其发展和变化的领域，与专家讲座的语境相符。"}, {"text": "永恒真理", "is_correct": false, "explanation": "语义：永恒真理的本质是不变的，与句中的“变化”相矛盾，专家不会讲“永恒真理的变化”。"}, {"text": "叹息", "is_correct": false, "explanation": "语义：“叹息”是一种声音或情绪，不是可以讲解其变化的领域，与“讲……的变化”不搭。"}, {"text": "外貌", "is_correct": false, "explanation": "体貌：外貌指人的外形，学校请专家讲座不会讲某个人外貌的变化，所指不符。"}], "explanations": {"现代科技": "正确。现代科技是可以讲解其发展和变化的领域，与专家讲座的语境相符。", "永恒真理": "语义：永恒真理的本质是不变的，与句中的“变化”相矛盾，专家不会讲“永恒真理的变化”。", "叹息": "语义：“叹息”是一种声音或情绪，不是可以讲解其变化的领域，与“讲……的变化”不搭。", "外貌": "体貌：外貌指人的外形，学校请专家讲座不会讲某个人外貌的变化，所指不符。"}, "sentence_index": 6, "correct_answer": "现代科技"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这所学校每年培养很多现代科技。", "explanation": "这里应该用〈人才〉。培养的对象是人，现代科技是技术领域，不能被“培养”。"}, {"text": "护士给他注射了现代科技。", "explanation": "这里应该用〈疫苗〉。注射的是药物，现代科技是技术领域，不能被注射。"}, {"text": "他的理想是成为一名现代科技。", "explanation": "现代科技是领域名称，不指人，不能用“成为一名……”来说，指人应使用〈科学家〉这类词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba26d35-0c52-4e06-afc7-91807d7bd45c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12794, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这所学校引进了一只现代科技。", "corrected_sentence": "这所学校引进了一项现代科技。", "error_description": "量词错误：〈只〉用于动物、手等，现代科技应该用〈项〉。正确的说法是“这所学校引进了一项现代科技”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba26d35-0c52-4e06-afc7-91807d7bd45c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12794, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这十年现代科技发展得快很。", "corrected_sentence": "这十年现代科技发展得很快。", "error_description": "补语语序错误：程度补语应为“得很快”，不能说“快很”。正确的说法是“这十年现代科技发展得很快”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba26d35-0c52-4e06-afc7-91807d7bd45c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
