INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12797, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "为了学习或了解而查阅、利用某种资料或信息。", "primary_collocate": null, "pronunciation": "cān kǎo", "ipa": "tsʰan˥ kʰɑʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "它们不仅是历史的见证，也是未来可持续发展的重要参考。", "target_word": "参考", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "写作文时，你可以参考这本书。", "target_word": "参考", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做菜的时候，我常常参考网上的菜谱。", "target_word": "参考", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这篇文章参考了很多资料。", "target_word": "参考", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请参考下面的地图找到我家。", "target_word": "参考", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们可以参考老师给的材料。", "target_word": "参考", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "写报告前，我先参考了去年的数据。", "target_word": "参考", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你能把这些资料借给我参考吗？", "target_word": "参考", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买手机前，我会参考别人的评价。", "target_word": "参考", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个答案你可以参考一下，但不一定正确。", "target_word": "参考", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "参考了", "label": "完成体"}, {"form": "参考过", "label": "经历体"}, {"form": "参考着", "label": "持续体"}, {"form": "参考书", "label": "复合词"}, {"form": "参考资料", "label": "复合词"}], "register": "中性", "sense_fingerprint": "查阅利用资料或信息来学习了解", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecc79bd2-c16d-4f8a-a9d7-dab736631f53') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12797, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "参考", "is_correct": true, "explanation": "正确：“参考”指可供查阅、借鉴的资料，与“见证”“发展”的语境相合。"}, {"text": "污染", "is_correct": false, "explanation": "语义：“污染”是负面的，与“可持续发展的重要……”的正面语境相矛盾。"}, {"text": "浪费", "is_correct": false, "explanation": "语义：“浪费”指白白耗费，不能用来指对可持续发展有益的东西。"}, {"text": "垃圾", "is_correct": false, "explanation": "语域：“垃圾”是口语化的贬称，不能用于这种正式书面的历史与发展论述。"}], "explanations": {"参考": "正确：“参考”指可供查阅、借鉴的资料，与“见证”“发展”的语境相合。", "污染": "语义：“污染”是负面的，与“可持续发展的重要……”的正面语境相矛盾。", "浪费": "语义：“浪费”指白白耗费，不能用来指对可持续发展有益的东西。", "垃圾": "语域：“垃圾”是口语化的贬称，不能用于这种正式书面的历史与发展论述。"}, "sentence_index": 0, "correct_answer": "参考"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我昨天参考了同学的婚礼。", "explanation": "这里应该用〈参加〉。参考指查阅或借鉴资料、经验，不能说参加某个仪式或活动。"}, {"text": "他昨天参考了一场篮球比赛。", "explanation": "这里应该用〈参赛〉。参考指查阅或借鉴资料、经验，不能说以选手身份参加比赛。"}, {"text": "周末我们参考了这座古老的城市。", "explanation": "这里应该用〈参观〉。参观指到某地去看，参考的对象应是资料或经验，不能是地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba26d35-0c52-4e06-afc7-91807d7bd45c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12797, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "参考", "is_correct": true, "explanation": "正确：“参考”表示查阅数据以作依据，与“写报告前”“去年的数据”的语境相合。"}, {"text": "擦亮", "is_correct": false, "explanation": "搭配：“擦亮”用于镜子、皮鞋等，不能与“数据”搭配。"}, {"text": "吃", "is_correct": false, "explanation": "配价：“吃”的宾语应是食物，不能以“数据”为宾语。"}, {"text": "喝", "is_correct": false, "explanation": "配价：“喝”的宾语应是饮品，不能以“数据”为宾语。"}], "explanations": {"参考": "正确：“参考”表示查阅数据以作依据，与“写报告前”“去年的数据”的语境相合。", "擦亮": "搭配：“擦亮”用于镜子、皮鞋等，不能与“数据”搭配。", "吃": "配价：“吃”的宾语应是食物，不能以“数据”为宾语。", "喝": "配价：“喝”的宾语应是饮品，不能以“数据”为宾语。"}, "sentence_index": 6, "correct_answer": "参考"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我去律师事务所参考了离婚的问题。", "explanation": "这里应该用〈咨询〉。咨询指向专业人员请教问题，参考是查阅资料，不能向人求教。"}, {"text": "我去医院参考了生病的奶奶。", "explanation": "这里应该用〈看望〉。看望指去探问、慰问人，参考的对象是资料或经验，不能是人。"}, {"text": "我向老师参考了这道题。", "explanation": "这里应该用〈请教〉。请教指向别人求教，参考是自己查阅资料，不能用于向人求教。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba26d35-0c52-4e06-afc7-91807d7bd45c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12797, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我明天参考了这份资料。", "corrected_sentence": "我明天参考这份资料。", "error_description": "错误：“参考”后误加了“了”。句中“明天”表示将来，动作尚未发生，应去掉“了”，说“我明天参考这份资料”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba26d35-0c52-4e06-afc7-91807d7bd45c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12797, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我每天都参考了网上的资料。", "corrected_sentence": "我每天都参考网上的资料。", "error_description": "错误：“每天都”表示经常性的动作，不能与表示完成的“了”搭配，应去掉“了”，说“我每天都参考网上的资料”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba26d35-0c52-4e06-afc7-91807d7bd45c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
