INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12798, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指某种资源或物品的数量非常少，不能满足需要。", "primary_collocate": null, "pronunciation": "xī quē xìng", "ipa": "ɕi˥ tɕʰɥe˥ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "在极端干旱的环境中，水资源的稀缺性催生了人类文明最为精妙的生存智慧。", "target_word": "稀缺性", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "水的稀缺性让人们学会了节约。", "target_word": "稀缺性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "黄金的稀缺性使它价格很高。", "target_word": "稀缺性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经济学认为稀缺性是价格的基础。", "target_word": "稀缺性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种矿产的稀缺性越来越明显。", "target_word": "稀缺性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "土地的稀缺性让城市房价上涨。", "target_word": "稀缺性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人才的稀缺性是公司面临的问题。", "target_word": "稀缺性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "石油的稀缺性影响着世界经济。", "target_word": "稀缺性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为稀缺性，这种药材卖得很贵。", "target_word": "稀缺性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家提醒大家注意淡水的稀缺性。", "target_word": "稀缺性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "资源或物品数量很少、不能满足需要的特性", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '312fe292-15c3-4f5b-baf9-ae90a590e823') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12798, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "稀缺性", "is_correct": true, "explanation": "正确。“稀缺性”指资源少、不能满足需要，与“极端干旱”的语境吻合。"}, {"text": "丰富性", "is_correct": false, "explanation": "语义：“丰富性”指数量多，与“极端干旱”的语境相反，无法解释生存智慧的来源。"}, {"text": "便利性", "is_correct": false, "explanation": "搭配：“便利性”多用于交通、服务等，不说“水资源的便利性”。"}, {"text": "充足性", "is_correct": false, "explanation": "语义：“充足性”指足够，与“极端干旱”的语境相反。"}], "explanations": {"稀缺性": "正确。“稀缺性”指资源少、不能满足需要，与“极端干旱”的语境吻合。", "丰富性": "语义：“丰富性”指数量多，与“极端干旱”的语境相反，无法解释生存智慧的来源。", "便利性": "搭配：“便利性”多用于交通、服务等，不说“水资源的便利性”。", "充足性": "语义：“充足性”指足够，与“极端干旱”的语境相反。"}, "sentence_index": 0, "correct_answer": "稀缺性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这朵花的稀缺性很红。", "explanation": "这里应该用〈颜色〉。“稀缺性”指东西少的属性，不能用来描述颜色。"}, {"text": "我们发现了一只稀缺性。", "explanation": "这里应该用〈种〉。“只”用于动物等具体事物，抽象的属性名词要用“种”。"}, {"text": "我在超市买到了一种稀缺性。", "explanation": "“稀缺性”指事物的属性，不是可以买卖的东西；应说“买到了很稀缺的东西”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a5ba268-991a-4c1e-a3bb-87901051b3c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12798, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "稀缺性", "is_correct": true, "explanation": "正确。“人才的稀缺性”是企业常见的问题，句意通顺。"}, {"text": "灵活性", "is_correct": false, "explanation": "语义：“灵活性”是正面特点，不能说它是公司面临的问题。"}, {"text": "普遍性", "is_correct": false, "explanation": "语义：“普遍性”指到处都有，与“是公司面临的问题”的语境不符。"}, {"text": "时效性", "is_correct": false, "explanation": "搭配：“时效性”多用于信息、政策，不说“人才的时效性”。"}], "explanations": {"稀缺性": "正确。“人才的稀缺性”是企业常见的问题，句意通顺。", "灵活性": "语义：“灵活性”是正面特点，不能说它是公司面临的问题。", "普遍性": "语义：“普遍性”指到处都有，与“是公司面临的问题”的语境不符。", "时效性": "搭配：“时效性”多用于信息、政策，不说“人才的时效性”。"}, "sentence_index": 6, "correct_answer": "稀缺性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个地区的供水出现了稀缺性。", "explanation": "这里应该用〈短缺〉。“稀缺性”指资源本身的属性，不能说“出现稀缺性”；供应不足的状况要用“短缺”。"}, {"text": "这位老师的稀缺性很受学生欢迎。", "explanation": "“稀缺性”指资源的属性，不用来形容人的才能；说人的才能要用“难得”。"}, {"text": "我们用节水的稀缺性来解决缺水问题。", "explanation": "这里应该用〈办法〉。“稀缺性”指资源少的属性，不能作为解决问题的手段。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a5ba268-991a-4c1e-a3bb-87901051b3c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12798, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "经济学家研究了一只稀缺性。", "corrected_sentence": "经济学家研究了一种稀缺性。", "error_description": "“稀缺性”是抽象名词，量词应用“种”，不能用“只”（“只”用于动物等）。正确形式：一种稀缺性。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a5ba268-991a-4c1e-a3bb-87901051b3c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12798, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们应该关注淡水的一只稀缺性。", "corrected_sentence": "我们应该关注淡水的一种稀缺性。", "error_description": "量词错：抽象名词“稀缺性”应说“种”；“只”用于动物等，不能用来数它。正确形式：淡水的一种稀缺性。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a5ba268-991a-4c1e-a3bb-87901051b3c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12799, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c02ee696-eb52-4659-90f1-cdd91367f0cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12799, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c02ee696-eb52-4659-90f1-cdd91367f0cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12799, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指长期或极度缺水、降水量远小于蒸发量的自然区域。", "primary_collocate": null, "pronunciation": "gān hàn dì qū", "ipa": "kan˥ xan˥˩ ti˥˩ tɕʰy˥", "syllable_count": 4, "sentences": [{"text": "自远古以来，干旱地区的人们就学会了节约用水。", "target_word": "干旱地区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多人喜欢去干旱地区旅游。", "target_word": "干旱地区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "特别是在一些干旱地区，工厂还在大量用水做衣服，让当地居民更难找到足够的水。", "target_word": "干旱地区", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "干旱地区很少下雨，植物也不多。", "target_word": "干旱地区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个干旱地区的人们很缺水。", "target_word": "干旱地区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们去过一个干旱地区，那里一年只下几天雨。", "target_word": "干旱地区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府在干旱地区修了很多水池。", "target_word": "干旱地区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "干旱地区的农民每天都要走很远去找水。", "target_word": "干旱地区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种树能在干旱地区长得很好。", "target_word": "干旱地区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天，干旱地区的土地常常裂开。", "target_word": "干旱地区", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "片", "label": "量词"}, {"form": "干旱区", "label": "复合"}], "register": "中性", "sense_fingerprint": "长期极度缺水、降水远少于蒸发的自然区域", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e003bea1-9a51-40cb-91ca-bdd0a7fd19d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12799, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "深海", "is_correct": false, "explanation": "语义：深海不是人们生活、节约用水的地方，与“干旱地区的人们”不符。"}, {"text": "高科技园区", "is_correct": false, "explanation": "语义：“高科技园区”是现代规划的区域，与“自远古以来”的时间背景矛盾。"}, {"text": "月球", "is_correct": false, "explanation": "语义：月球上没有世代生活的人群，与“干旱地区的人们”不符。"}, {"text": "干旱地区", "is_correct": true, "explanation": "正确。“干旱地区”的人们自远古起就要应对缺水，符合这段语境。"}], "explanations": {"深海": "语义：深海不是人们生活、节约用水的地方，与“干旱地区的人们”不符。", "高科技园区": "语义：“高科技园区”是现代规划的区域，与“自远古以来”的时间背景矛盾。", "月球": "语义：月球上没有世代生活的人群，与“干旱地区的人们”不符。", "干旱地区": "正确。“干旱地区”的人们自远古起就要应对缺水，符合这段语境。"}, "sentence_index": 0, "correct_answer": "干旱地区"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们去过一个干旱地区，那里常年下着大雨。", "explanation": "这里应该用〈湿润地区〉。干旱地区指长期缺水的地方，常年下大雨的地方要说湿润地区。"}, {"text": "去年这里发生了严重的干旱地区。", "explanation": "这里应该用〈旱灾〉。干旱地区指长期缺水的地方，灾害事件要说旱灾。"}, {"text": "这片干旱地区一年到头都是绿色的草地。", "explanation": "这里应该用〈草原〉。干旱地区指缺水、植物难长的地方，草木茂盛的地方要说草原。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c02ee696-eb52-4659-90f1-cdd91367f0cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12799, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "太空", "is_correct": false, "explanation": "语义：政府不会在太空修建很多水池，这句话的语境是地面上的工程。"}, {"text": "课堂", "is_correct": false, "explanation": "语义：“课堂”是教学场所，政府不会在那里修很多水池。"}, {"text": "干旱地区", "is_correct": true, "explanation": "正确。政府在干旱地区修水池，符合这句话的语境。"}, {"text": "脑海", "is_correct": false, "explanation": "搭配：“脑海”是抽象的心理空间，不能在其中修建水池。"}], "explanations": {"太空": "语义：政府不会在太空修建很多水池，这句话的语境是地面上的工程。", "课堂": "语义：“课堂”是教学场所，政府不会在那里修很多水池。", "干旱地区": "正确。政府在干旱地区修水池，符合这句话的语境。", "脑海": "搭配：“脑海”是抽象的心理空间，不能在其中修建水池。"}, "sentence_index": 6, "correct_answer": "干旱地区"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今年的干旱地区从五月一直持续到十月。", "explanation": "这里应该用〈旱季〉。干旱地区指地方，一段少雨的时期要说旱季。"}, {"text": "这个村子的干旱地区一年到头都在下雨。", "explanation": "这里应该用〈多雨地区〉。干旱地区指少雨、土地干的地方，一年到头都在下雨要说多雨地区。"}, {"text": "我们穿过了一片干旱地区，四处都是沼泽和水草。", "explanation": "这里应该用〈湿地〉。干旱地区少雨、土地干，四处是沼泽和水草的地方要说湿地。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c02ee696-eb52-4659-90f1-cdd91367f0cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12799, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那一条干旱地区至今还没有通上电。", "corrected_sentence": "那一片干旱地区至今还没有通上电。", "error_description": "量词错误：“地区”应用“片”，“条”用于长条形的事物，不能用来修饰地区。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c02ee696-eb52-4659-90f1-cdd91367f0cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12799, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只干旱地区的农民很会节约用水。", "corrected_sentence": "这个干旱地区的农民很会节约用水。", "error_description": "量词错误：“地区”前应用“个”或“片”，“只”用于动物或单个物品，不能修饰地区；应说“这个干旱地区”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c02ee696-eb52-4659-90f1-cdd91367f0cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12800, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "促进", "is_correct": true, "explanation": "正确。“制约”是限制，“促进”是推动，二者构成反义。"}, {"text": "收获", "is_correct": false, "explanation": "“收获”指获得成果，与“制约”的限制义没有对立关系。"}, {"text": "观察", "is_correct": false, "explanation": "“观察”指仔细看，与“制约”没有反义关系。"}, {"text": "讨论", "is_correct": false, "explanation": "“讨论”指交换意见，与“制约”没有反义关系。"}], "correct_answer": "促进", "explanations": {"促进": "正确。“制约”是限制，“促进”是推动，二者构成反义。", "收获": "“收获”指获得成果，与“制约”的限制义没有对立关系。", "观察": "“观察”指仔细看，与“制约”没有反义关系。", "讨论": "“讨论”指交换意见，与“制约”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42eb6137-f768-4a96-8a30-858a9d254957') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12800, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "促进", "is_correct": true, "explanation": "正确。“互相制约”与“互相促进”构成反义。"}, {"text": "等待", "is_correct": false, "explanation": "“等待”指停留不动地盼望，与“制约”没有反义关系。"}, {"text": "整理", "is_correct": false, "explanation": "“整理”指使有条理，与“制约”没有反义关系。"}, {"text": "回忆", "is_correct": false, "explanation": "“回忆”指想起过去的事，与“制约”没有反义关系。"}], "correct_answer": "促进", "explanations": {"促进": "正确。“互相制约”与“互相促进”构成反义。", "等待": "“等待”指停留不动地盼望，与“制约”没有反义关系。", "整理": "“整理”指使有条理，与“制约”没有反义关系。", "回忆": "“回忆”指想起过去的事，与“制约”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42eb6137-f768-4a96-8a30-858a9d254957') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12800, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "指一种事物对另一种事物的限制、约束或控制，使其不能自由发展或活动。", "primary_collocate": null, "pronunciation": "zhì yuē", "ipa": "ʈʂʐ̩˥˩ yɛ˥˩", "syllable_count": 2, "sentences": [{"text": "自远古以来，干旱地区的农业社群便发展出一系列复杂的资源管理体系，这些体系不仅是对自然制约的回应，更深刻体现了本土知识与生态伦理的融合。", "target_word": "制约", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "在城市化进程日益加速的今天，生活垃圾的处理已成为制约可持续发展的关键议题。", "target_word": "制约", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "资金不足制约了公司的发展。", "target_word": "制约", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气条件制约着农业的收成。", "target_word": "制约", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "交通不便制约了这个地区的经济。", "target_word": "制约", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "语言不通是制约他工作的主要问题。", "target_word": "制约", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有法律制约，权力容易出问题。", "target_word": "制约", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人口增长受到资源的制约。", "target_word": "制约", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水源少制约了这座城市的发展。", "target_word": "制约", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个因素互相制约，缺一不可。", "target_word": "制约", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "制约了", "label": "完成体标"}, {"form": "制约着", "label": "持续体标"}], "register": "书面", "sense_fingerprint": "事物之间互相限制，使发展受阻", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '699a7efa-2ffe-43e6-84c2-b247b5d73d94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12800, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "制约", "is_correct": true, "explanation": "正确。“对自然制约的回应”指体系回应自然界的限制。"}, {"text": "货币", "is_correct": false, "explanation": "语义：货币是交换的媒介，不能成为“回应”的对象，“对自然货币的回应”句意不通。"}, {"text": "考试", "is_correct": false, "explanation": "语义：考试是人为的测验，不能成为“回应”的对象，句意不通。"}, {"text": "节日", "is_correct": false, "explanation": "搭配：“节日”不是能施加作用的对象，不能作为“回应”的对象。"}], "explanations": {"制约": "正确。“对自然制约的回应”指体系回应自然界的限制。", "货币": "语义：货币是交换的媒介，不能成为“回应”的对象，“对自然货币的回应”句意不通。", "考试": "语义：考试是人为的测验，不能成为“回应”的对象，句意不通。", "节日": "搭配：“节日”不是能施加作用的对象，不能作为“回应”的对象。"}, "sentence_index": 0, "correct_answer": "制约"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "充足的资金制约了研发的进展。", "explanation": "这里应该用〈促进〉。制约表示限制事物的发展，充足的资金应当促进研发。"}, {"text": "春雨制约了干涸的田地。", "explanation": "这里应该用〈滋润〉。制约表示限制，春雨对干涸的田地应是滋润。"}, {"text": "父亲的支持制约了他的学业。", "explanation": "这里应该用〈帮助〉。制约表示限制、约束，使人不能自由发展；对学业起促进作用应当用帮助。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42eb6137-f768-4a96-8a30-858a9d254957') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12800, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "制约", "is_correct": true, "explanation": "正确。“法律制约”指法律对权力的限制，与“权力容易出问题”的语境呼应。"}, {"text": "鼓励", "is_correct": false, "explanation": "语义：“鼓励”是支持性的做法，与“没有……权力容易出问题”的语境不符。"}, {"text": "游戏", "is_correct": false, "explanation": "搭配：“法律游戏”不成立，“游戏”不能用来约束权力。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“颜色”不能作为约束权力的手段，“法律颜色”不成立。"}], "explanations": {"制约": "正确。“法律制约”指法律对权力的限制，与“权力容易出问题”的语境呼应。", "鼓励": "语义：“鼓励”是支持性的做法，与“没有……权力容易出问题”的语境不符。", "游戏": "搭配：“法律游戏”不成立，“游戏”不能用来约束权力。", "颜色": "搭配：“颜色”不能作为约束权力的手段，“法律颜色”不成立。"}, "sentence_index": 6, "correct_answer": "制约"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "胜利制约了全队的士气。", "explanation": "这里应该用〈鼓舞〉。制约表示限制，胜利对士气应是鼓舞。"}, {"text": "这场比赛制约了观众的热情。", "explanation": "这里应该用〈激发〉。制约表示限制，比赛应当激发观众的热情。"}, {"text": "老师的鼓励制约了他的信心。", "explanation": "这里应该用〈树立〉。制约表示限制，老师的鼓励应当帮助他树立信心，而不是限制信心。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42eb6137-f768-4a96-8a30-858a9d254957') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12800, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "缺乏人才制约着了这家公司的发展。", "corrected_sentence": "缺乏人才制约着这家公司的发展。", "error_description": "体标重复：“制约着”中的“着”已表示持续，其后不能再加“了”，应写作“制约着这家公司的发展”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42eb6137-f768-4a96-8a30-858a9d254957') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12800, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这项政策制约着了中小企业的发展。", "corrected_sentence": "这项政策制约着中小企业的发展。", "error_description": "体标重复：“制约着”中的“着”已表示持续，其后不能再加“了”，应写作“这项政策制约着中小企业的发展”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42eb6137-f768-4a96-8a30-858a9d254957') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
