INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12801, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "对别人的问题或要求做出回答或反应。", "primary_collocate": null, "pronunciation": "huí yìng", "ipa": "xweɪ˧˥ iŋ˥˩", "syllable_count": 2, "sentences": [{"text": "自远古以来，干旱地区的农业社群便发展出一系列复杂的资源管理体系，这些体系不仅是对自然制约的回应，更深刻体现了本土知识与生态伦理的融合。", "target_word": "回应", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "我叫了他三次，他都没有回应。", "target_word": "回应", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师问了一个问题，同学们马上回应。", "target_word": "回应", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司还没有回应我们提出的要求。", "target_word": "回应", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "面对大家的批评，他很快做出了回应。", "target_word": "回应", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她笑着回应了朋友的问候。", "target_word": "回应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对于这个要求，政府给了明确的回应。", "target_word": "回应", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我发了信息，可是一直没有人回应。", "target_word": "回应", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他点点头，回应了妈妈的话。", "target_word": "回应", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子哭着喊妈妈，妈妈马上回应他。", "target_word": "回应", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "回应了", "label": "体标（了）"}, {"form": "回应过", "label": "体标（过）"}, {"form": "回应着", "label": "体标（着）"}, {"form": "回應", "label": "繁体"}], "register": "中性", "sense_fingerprint": "对问题、要求、批评等做出回答或反应", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '160c4f15-32da-40c3-b527-73291bf6ea7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12801, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "回应", "is_correct": true, "explanation": "回应：这里指对制约作出的反应，与“对自然制约的”搭配，符合句意。"}, {"text": "原因", "is_correct": false, "explanation": "语义：“原因”是导致某事的因素，与句中“体系是对制约的……”的意思不符，句意不通。"}, {"text": "账单", "is_correct": false, "explanation": "搭配：“账单”不能用于“对自然制约的”，搭配不当。"}, {"text": "宣言", "is_correct": false, "explanation": "语义：“宣言”是公开声明，与“对自然制约的”搭配不通，句意不符。"}], "explanations": {"回应": "回应：这里指对制约作出的反应，与“对自然制约的”搭配，符合句意。", "原因": "语义：“原因”是导致某事的因素，与句中“体系是对制约的……”的意思不符，句意不通。", "账单": "搭配：“账单”不能用于“对自然制约的”，搭配不当。", "宣言": "语义：“宣言”是公开声明，与“对自然制约的”搭配不通，句意不符。"}, "sentence_index": 0, "correct_answer": "回应"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这两篇文章的开头和结尾前后回应。", "explanation": "这里应该用〈呼应〉。“呼应”指前后相互照应，文章结构的前后照应要用“呼应”；“回应”指对别人的话或要求作出反应。"}, {"text": "他很快回应了这道数学题。", "explanation": "这里应该用〈解答〉。“解答”指算出题目的答案；“回应”只用于对别人的话或要求作出反应，不能用于解题。"}, {"text": "他一直回应弟弟，每天接送他上学。", "explanation": "这里应该用〈照应〉。“照应”指照顾、关照别人；“回应”不能表示照顾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2635fe9d-2c73-4a0d-8255-fc78d15f067c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12801, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "回应", "is_correct": true, "explanation": "回应：这里指政府对要求作出的表态，与“明确的”搭配，符合句意。"}, {"text": "礼物", "is_correct": false, "explanation": "搭配：“明确的”不能修饰“礼物”，政府给礼物也与“要求”的语境不符。"}, {"text": "味道", "is_correct": false, "explanation": "语义：“味道”与政府对要求的表态无关，句意不通。"}, {"text": "花园", "is_correct": false, "explanation": "语义：“花园”不是对要求的表态，与句意不符。"}], "explanations": {"回应": "回应：这里指政府对要求作出的表态，与“明确的”搭配，符合句意。", "礼物": "搭配：“明确的”不能修饰“礼物”，政府给礼物也与“要求”的语境不符。", "味道": "语义：“味道”与政府对要求的表态无关，句意不通。", "花园": "语义：“花园”不是对要求的表态，与句意不符。"}, "sentence_index": 6, "correct_answer": "回应"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这种试剂加入后，溶液很快就回应了。", "explanation": "这里应该用〈反应〉。“反应”用于化学变化和身体的生理变化；“回应”只用于人对话语、要求作出回答。"}, {"text": "同学们向老师回应了教室太冷的情况。", "explanation": "这里应该用〈反映〉。“反映”指向有关方面陈述情况；“回应”指对要求或话语作出反应，不能用于陈述情况。"}, {"text": "老人常常回应年轻时的生活。", "explanation": "这里应该用〈回忆〉。“回忆”指想起过去的事；“回应”不能表示回想。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2635fe9d-2c73-4a0d-8255-fc78d15f067c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12801, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他很快回应了的我的问题。", "corrected_sentence": "他很快回应了我的问题。", "error_description": "结构错误：“回应了”后直接接宾语，句中多出的“的”使“回应了的我的问题”无法构成通顺的名词短语。应去掉“的”，写成“回应了我的问题”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2635fe9d-2c73-4a0d-8255-fc78d15f067c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12801, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子哭着喊妈妈，妈妈很快就回应了着他。", "corrected_sentence": "孩子哭着喊妈妈，妈妈很快就回应了他。", "error_description": "体标错误：“了”和“着”不能同时用在同一个动词后，这里只用“了”。“回应了着他”不对，应去掉“着”，写成“回应了他”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2635fe9d-2c73-4a0d-8255-fc78d15f067c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12802, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42eb6137-f768-4a96-8a30-858a9d254957') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12802, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42eb6137-f768-4a96-8a30-858a9d254957') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12802, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "物体中所含的水分，也比喻事物中多余或不实的部分。", "primary_collocate": null, "pronunciation": "shuǐ fèn", "ipa": "ʂweɪ˨˩˦ fən˥˩", "syllable_count": 2, "sentences": [{"text": "浇地时要最大化水分利用效率，才能节约用水。", "target_word": "水分", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "桶的底部要钻几个小洞，让多余的水分可以流出来。", "target_word": "水分", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "西瓜里的水分很多，夏天吃最解渴。", "target_word": "水分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳把衣服里的水分晒干了。", "target_word": "水分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种面包水分少，放几天也不会坏。", "target_word": "水分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "苹果放久了，水分会慢慢变少。", "target_word": "水分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做饺子馅以前，要先挤掉菜里的水分。", "target_word": "水分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沙漠里的植物水分很少，却能活很久。", "target_word": "水分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你写的这份报告水分太大，要多加一些数据。", "target_word": "水分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "秋天空气干燥，皮肤也会失去水分。", "target_word": "水分", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一点", "label": "量词"}], "register": "中性", "sense_fingerprint": "水分：物体里含的水；比喻多余或不实的部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '699a7efa-2ffe-43e6-84c2-b247b5d73d94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12802, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "水分", "is_correct": true, "explanation": "正确答案，指物体中所含的水。"}, {"text": "水费", "is_correct": false, "explanation": "fèi（第四声）与 fèn（第四声）韵尾不同（i 与 n），意思是水费。"}, {"text": "水粉", "is_correct": false, "explanation": "fěn（第三声）与 fèn（第四声）声调不同，意思是水粉颜料。"}, {"text": "水嫩", "is_correct": false, "explanation": "nèn 与 fèn 声母不同（n 与 f），意思是水嫩。"}], "explanations": {"水分": "正确答案，指物体中所含的水。", "水费": "fèi（第四声）与 fèn（第四声）韵尾不同（i 与 n），意思是水费。", "水粉": "fěn（第三声）与 fèn（第四声）声调不同，意思是水粉颜料。", "水嫩": "nèn 与 fèn 声母不同（n 与 f），意思是水嫩。"}, "sentence_index": null, "correct_answer": "水分"}, "level_3": {"options": [{"text": "水分", "is_correct": true, "explanation": "正确：“水分”指物体内所含的水，“最大化水分利用效率”搭配自然。"}, {"text": "情绪", "is_correct": false, "explanation": "搭配：“利用效率”的对象应是可被利用的资源，“最大化情绪利用效率”不成立。"}, {"text": "口音", "is_correct": false, "explanation": "语义：口音与此处的生态系统、利用效率无关，不能被“最大化利用”。"}, {"text": "色彩", "is_correct": false, "explanation": "搭配：“色彩”不是可被利用的资源，与“最大化……利用效率”搭配不当。"}], "explanations": {"水分": "正确：“水分”指物体内所含的水，“最大化水分利用效率”搭配自然。", "情绪": "搭配：“利用效率”的对象应是可被利用的资源，“最大化情绪利用效率”不成立。", "口音": "语义：口音与此处的生态系统、利用效率无关，不能被“最大化利用”。", "色彩": "搭配：“色彩”不是可被利用的资源，与“最大化……利用效率”搭配不当。"}, "sentence_index": 0, "correct_answer": "水分"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我想给花浇点水分。", "explanation": "这里应该用〈水〉。水分指物体内所含的水成分，浇花用的是水，不能说“浇水分”。"}, {"text": "这瓶饮料是无色透明的水分。", "explanation": "这里应该用〈液体〉。饮料本身是液体，水分只指物体内所含的水成分，不能用来指整瓶饮料。"}, {"text": "锅里冒出了白色的水分。", "explanation": "这里应该用〈蒸汽〉。冒出的白色水汽是蒸汽，水分是物体内含的水，不指空中冒出的水汽。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42eb6137-f768-4a96-8a30-858a9d254957') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12802, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "水分", "is_correct": true, "explanation": "正确：“水分”指菜里所含的水，挤掉水分是做馅前的常见步骤。"}, {"text": "时间", "is_correct": false, "explanation": "语义：菜里不含时间，“挤掉菜里的时间”在语义上不成立。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“挤掉”不能用于颜色，颜色也不能从菜里挤出。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格不是菜里所含的物质，与“挤掉”的语义不合。"}], "explanations": {"水分": "正确：“水分”指菜里所含的水，挤掉水分是做馅前的常见步骤。", "时间": "语义：菜里不含时间，“挤掉菜里的时间”在语义上不成立。", "颜色": "搭配：“挤掉”不能用于颜色，颜色也不能从菜里挤出。", "价格": "语义：价格不是菜里所含的物质，与“挤掉”的语义不合。"}, "sentence_index": 6, "correct_answer": "水分"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把水分喝光了。", "explanation": "这里应该用〈果汁〉。水分指物体内所含的水成分，不是可以整杯喝掉的饮品，不能说“把水分喝光了”。"}, {"text": "水分很鲜，大家都夸好喝。", "explanation": "这里应该用〈汤〉。“鲜”形容汤、菜的味道，水分指所含的水成分，不能用来形容味道。"}, {"text": "水分很黑，写字很清楚。", "explanation": "这里应该用〈墨水〉。“黑”形容颜色，墨水有颜色，水分指所含的水成分，不能说“水分很黑”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42eb6137-f768-4a96-8a30-858a9d254957') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12802, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "运动后要及时补充一个水分。", "corrected_sentence": "运动后要及时补充一点水分。", "error_description": "量词错误：“水分”前应用量词“点”，说“一点水分”，不能用“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42eb6137-f768-4a96-8a30-858a9d254957') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12802, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "饺子皮擀好了，菜里的水分还没有完全挤干了。", "corrected_sentence": "饺子皮擀好了，菜里的水分还没有完全挤干。", "error_description": "“还没有”与“了”不能同时用：“还没有完全挤干”表示尚未完成，句末应去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42eb6137-f768-4a96-8a30-858a9d254957') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
