INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12806, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2635fe9d-2c73-4a0d-8255-fc78d15f067c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12806, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "绿洲是沙漠中水草丰美、适合居住的小块地区。", "primary_collocate": null, "pronunciation": "lǜ zhōu", "ipa": "ly˥˩ ʈʂoʊ̯˥˥", "syllable_count": 2, "sentences": [{"text": "例如，在中亚与北非的古老绿洲系统中，人们通过精密设计的灌溉网络——如坎儿井（qanat）——将高山融雪水引至低地农田。", "target_word": "绿洲", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "沙漠里有一片绿洲。", "target_word": "绿洲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "走了一天，他们终于看到了绿洲。", "target_word": "绿洲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "绿洲里有水，也有树。", "target_word": "绿洲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多人住在沙漠里的绿洲上。", "target_word": "绿洲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "骆驼队在绿洲旁边休息。", "target_word": "绿洲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这片绿洲的水很干净。", "target_word": "绿洲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沙漠中的绿洲给旅行的人带来水。", "target_word": "绿洲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "绿洲的农民在田里种了小麦。", "target_word": "绿洲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为没有水，这个绿洲慢慢变小了。", "target_word": "绿洲", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "片", "label": "量词"}, {"form": "綠洲", "label": "繁体"}], "register": "中性", "sense_fingerprint": "沙漠中水草丰美、可居住的小块地区", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '160c4f15-32da-40c3-b527-73291bf6ea7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12806, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "绿洲", "is_correct": true, "explanation": "正确。“古老绿洲系统”指沙漠中依靠灌溉引水形成的水草丰美地区，与句中的灌溉网络和低地农田相符。"}, {"text": "沙漠", "is_correct": false, "explanation": "语义：沙漠是干旱缺水的地带，句中要表达的是靠灌溉网络引融雪水到农田的系统，“古老沙漠系统”说不通。"}, {"text": "火山", "is_correct": false, "explanation": "语义：火山喷发的是岩浆，不能靠灌溉网络把融雪水引至农田，“古老火山系统”与句意不符。"}, {"text": "海洋", "is_correct": false, "explanation": "语义：海洋不能靠灌溉网络把融雪水引至农田，与“中亚与北非的古老系统”的语境矛盾。"}], "explanations": {"绿洲": "正确。“古老绿洲系统”指沙漠中依靠灌溉引水形成的水草丰美地区，与句中的灌溉网络和低地农田相符。", "沙漠": "语义：沙漠是干旱缺水的地带，句中要表达的是靠灌溉网络引融雪水到农田的系统，“古老沙漠系统”说不通。", "火山": "语义：火山喷发的是岩浆，不能靠灌溉网络把融雪水引至农田，“古老火山系统”与句意不符。", "海洋": "语义：海洋不能靠灌溉网络把融雪水引至农田，与“中亚与北非的古老系统”的语境矛盾。"}, "sentence_index": 0, "correct_answer": "绿洲"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这片绿洲很深，村民们用绳子把桶放下去打水。", "explanation": "这里应该用〈水井〉。水井是垂直挖下去取水的深坑；绿洲是地面上水草丰美的小块地区，不能说很深，也不能用桶放下去打水。"}, {"text": "绿洲会随着风慢慢移动。", "explanation": "这里应该用〈沙丘〉。沙丘是风吹沙子堆成的，会随风移动；绿洲是有水草的固定地方，不会移动。"}, {"text": "我们在绿洲上滑雪。", "explanation": "这里应该用〈雪山〉。雪山上有积雪才能滑雪；绿洲是水草丰美的地方，没有积雪，不能滑雪。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2635fe9d-2c73-4a0d-8255-fc78d15f067c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12806, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "绿洲", "is_correct": true, "explanation": "正确。“这片绿洲的水很干净”指沙漠中一块有水的地方，水可以被说成干净。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空上没有可以汇集、流动的地表水，“这片天空的水很干净”说不通。"}, {"text": "沙子", "is_correct": false, "explanation": "搭配：沙子一般不说有“水很干净”，“这片沙子的水”不是常用搭配。"}, {"text": "云彩", "is_correct": false, "explanation": "语义：云彩是空中的水汽，不能说“这片云彩的水很干净”，与地面绿洲的语境不符。"}], "explanations": {"绿洲": "正确。“这片绿洲的水很干净”指沙漠中一块有水的地方，水可以被说成干净。", "天空": "语义：天空上没有可以汇集、流动的地表水，“这片天空的水很干净”说不通。", "沙子": "搭配：沙子一般不说有“水很干净”，“这片沙子的水”不是常用搭配。", "云彩": "语义：云彩是空中的水汽，不能说“这片云彩的水很干净”，与地面绿洲的语境不符。"}, "sentence_index": 6, "correct_answer": "绿洲"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这片绿洲每天都涨潮，退潮后留下很多贝壳。", "explanation": "这里应该用〈海滩〉。海滩才会随潮水涨落、退潮后留下贝壳；绿洲是沙漠中水草丰美的地方，没有潮汐。"}, {"text": "这片绿洲很长，从山上一直流到大海。", "explanation": "这里应该用〈河流〉。河流才会从山上一直流到大海；绿洲是固定的水草地，不会流动。"}, {"text": "这片绿洲在海底，鱼在里面游来游去。", "explanation": "这里应该用〈珊瑚礁〉。珊瑚礁是海底鱼群聚集的地方；绿洲是沙漠中有水草的地方，不会位于海底。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2635fe9d-2c73-4a0d-8255-fc78d15f067c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12806, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "骆驼队在沙漠里找到了一条绿洲。", "corrected_sentence": "骆驼队在沙漠里找到了一片绿洲。", "error_description": "量词错误：绿洲应用“片”，“条”用于河流、道路等细长的东西。正确说法是“一片绿洲”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2635fe9d-2c73-4a0d-8255-fc78d15f067c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12806, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "沙漠中央有一把绿洲，水很清。", "corrected_sentence": "沙漠中央有一片绿洲，水很清。", "error_description": "量词错误：绿洲应用“片”，“把”用于有柄的器具，不能修饰绿洲。正确说法是“一片绿洲”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2635fe9d-2c73-4a0d-8255-fc78d15f067c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
