INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12808, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，表示将要，事情在不久之后会发生。", "primary_collocate": null, "pronunciation": "jiāng", "ipa": "tɕjɑŋ˥", "syllable_count": 1, "sentences": [{"text": "明天上午，公司将发布新产品。", "target_word": "将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会议将在下午三点开始。", "target_word": "将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新学期将从九月一日开始。", "target_word": "将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机将于晚上八点到达北京。", "target_word": "将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校将举行一次大型比赛。", "target_word": "将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座桥将在明年春天建成。", "target_word": "将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "本周末天气将变冷。", "target_word": "将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理说，下个月他将去上海工作。", "target_word": "将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "展览将持续到下周五。", "target_word": "将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下个月，我们的新家将装修好。", "target_word": "将", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "副词，表示将要：事情在不久之后会发生", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8873e8b-ebaa-461c-94d4-dce7b35fae3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12808, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "将", "is_correct": true, "explanation": "正确答案：将，jiāng（第一声），本句中读作此音。"}, {"text": "讲", "is_correct": false, "explanation": "讲 jiǎng（第三声）与 jiāng（第一声）声调不同，意思是讲话。"}, {"text": "降", "is_correct": false, "explanation": "降 jiàng（第四声）与 jiāng（第一声）声调不同，意思是下降。"}, {"text": "尖", "is_correct": false, "explanation": "尖 jiān 与 jiāng 韵尾不同（an 与 ang），意思是尖锐。"}, {"text": "肩", "is_correct": false, "explanation": "肩 jiān 与 jiāng 韵尾不同（an 与 ang），意思是肩膀。"}], "explanations": {"将": "正确答案：将，jiāng（第一声），本句中读作此音。", "讲": "讲 jiǎng（第三声）与 jiāng（第一声）声调不同，意思是讲话。", "降": "降 jiàng（第四声）与 jiāng（第一声）声调不同，意思是下降。", "尖": "尖 jiān 与 jiāng 韵尾不同（an 与 ang），意思是尖锐。", "肩": "肩 jiān 与 jiāng 韵尾不同（an 与 ang），意思是肩膀。"}, "sentence_index": null, "correct_answer": "将"}, "level_3": {"options": [{"text": "将", "is_correct": true, "explanation": "正确：将在此表示将要，与“明天上午”的将来时间相符。"}, {"text": "已经", "is_correct": false, "explanation": "体貌：已经表示动作已经完成，与表示将来的“明天上午”相冲突。"}, {"text": "正在", "is_correct": false, "explanation": "体貌：正在表示动作正在进行，与表示将来的“明天上午”不相容。"}, {"text": "曾经", "is_correct": false, "explanation": "语义：曾经指过去的经历，与“明天上午”的将来时间冲突。"}], "explanations": {"将": "正确：将在此表示将要，与“明天上午”的将来时间相符。", "已经": "体貌：已经表示动作已经完成，与表示将来的“明天上午”相冲突。", "正在": "体貌：正在表示动作正在进行，与表示将来的“明天上午”不相容。", "曾经": "语义：曾经指过去的经历，与“明天上午”的将来时间冲突。"}, "sentence_index": 0, "correct_answer": "将"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他上周将来过我家。", "explanation": "这里误用了〈将〉（将来义），应改为〈已经〉，表示上周已经发生的动作：他上周已经来过我家了。"}, {"text": "我昨天将去北京。", "explanation": "这里误用了〈将〉（将来义），应改为〈已经〉，表示昨天已经发生的动作：我昨天已经去北京了。"}, {"text": "我上个月将搬到北京。", "explanation": "这里误用了〈将〉（将来义），应改为〈已经〉，表示上个月已经发生的事：我上个月已经搬到北京了。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76d5db9a-921f-428f-a956-053a32cada6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12808, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "将", "is_correct": true, "explanation": "正确答案：将，jiāng（第一声），本句中读作此音。"}, {"text": "奖", "is_correct": false, "explanation": "奖 jiǎng（第三声）与 jiāng（第一声）声调不同，意思是奖品。"}, {"text": "酱", "is_correct": false, "explanation": "酱 jiàng（第四声）与 jiāng（第一声）声调不同，意思是酱料。"}, {"text": "间", "is_correct": false, "explanation": "间 jiān 与 jiāng 韵尾不同（an 与 ang），意思是中间或房间。"}, {"text": "煎", "is_correct": false, "explanation": "煎 jiān 与 jiāng 韵尾不同（an 与 ang），意思是煎炸。"}], "explanations": {"将": "正确答案：将，jiāng（第一声），本句中读作此音。", "奖": "奖 jiǎng（第三声）与 jiāng（第一声）声调不同，意思是奖品。", "酱": "酱 jiàng（第四声）与 jiāng（第一声）声调不同，意思是酱料。", "间": "间 jiān 与 jiāng 韵尾不同（an 与 ang），意思是中间或房间。", "煎": "煎 jiān 与 jiāng 韵尾不同（an 与 ang），意思是煎炸。"}, "sentence_index": null, "correct_answer": "将"}, "level_3": {"options": [{"text": "将", "is_correct": true, "explanation": "正确：将在此表示将要，与“本周末”的将来时间相符。"}, {"text": "刚才", "is_correct": false, "explanation": "语义：刚才指不久之前，与表示将来的“本周末”冲突。"}, {"text": "方才", "is_correct": false, "explanation": "语域：方才是书面语，且指刚过去的时间，与“本周末”冲突。"}, {"text": "早已", "is_correct": false, "explanation": "语义：早已指很久以前就已完成，与“本周末”的将来时间冲突。"}], "explanations": {"将": "正确：将在此表示将要，与“本周末”的将来时间相符。", "刚才": "语义：刚才指不久之前，与表示将来的“本周末”冲突。", "方才": "语域：方才是书面语，且指刚过去的时间，与“本周末”冲突。", "早已": "语义：早已指很久以前就已完成，与“本周末”的将来时间冲突。"}, "sentence_index": 6, "correct_answer": "将"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我刚才将出门。", "explanation": "这里误用了〈将〉（将来义），应改为〈已经〉，表示刚才已经发生的动作：我刚才已经出门了。"}, {"text": "我去年将结婚。", "explanation": "这里误用了〈将〉（将来义），应改为〈已经〉，表示去年已经发生的事：我去年已经结婚了。"}, {"text": "我三年前将毕业。", "explanation": "这里误用了〈将〉（将来义），应改为〈已经〉，表示三年前已经发生的事：我三年前已经毕业了。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76d5db9a-921f-428f-a956-053a32cada6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12808, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们下周将参加了比赛。", "corrected_sentence": "我们下周将参加比赛。", "error_description": "「将」表示将要，不能与「了」同用。应删去「了」，改为「我们下周将参加比赛。」", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76d5db9a-921f-428f-a956-053a32cada6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12808, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校下周正在将开放体育馆。", "corrected_sentence": "学校下周将开放体育馆。", "error_description": "「将」表示将要，不能与表示正在进行的「正在」同用。应删去「正在」，改为「学校下周将开放体育馆。」", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76d5db9a-921f-428f-a956-053a32cada6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
