INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12809, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "高度很大的山，通常指地形高耸、难以攀登的山峰。", "primary_collocate": null, "pronunciation": "gāo shān", "ipa": "kɑʊ˥ ʂan˥", "syllable_count": 2, "sentences": [{"text": "例如，在中亚与北非的古老绿洲系统中，人们通过精密设计的灌溉网络——如坎儿井（qanat）——将高山融雪水引至低地农田。", "target_word": "高山", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这座高山的山顶冬天有雪。", "target_word": "高山", "complexity_tier": "T3", "furigana": "zhè zuò gāoshān de shāndǐng dōngtiān yǒu xuě。", "sentence_source": "generated"}, {"text": "我们周末去爬高山。", "target_word": "高山", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "高山上的空气很冷。", "target_word": "高山", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他住在高山下面的小村子里。", "target_word": "高山", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条河从高山流向大海。", "target_word": "高山", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "高山上有很多漂亮的花。", "target_word": "高山", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "站在高山上，我们看到了云。", "target_word": "高山", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种树只长在高山上。", "target_word": "高山", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山路很难走，高山上常常下雪。", "target_word": "高山", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "座", "label": "量词"}], "register": "中性", "sense_fingerprint": "高度很大、地形高耸的山峰", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8873e8b-ebaa-461c-94d4-dce7b35fae3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12809, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "高山", "is_correct": true, "explanation": "正确：高山是融雪水的来源，与“融雪水”相符。"}, {"text": "沙漠", "is_correct": false, "explanation": "语义：沙漠少有积雪，不能提供融雪水，与句意冲突。"}, {"text": "海洋", "is_correct": false, "explanation": "语义：海洋不是融雪水的来源，与“融雪水”冲突。"}, {"text": "城市", "is_correct": false, "explanation": "搭配：“将……融雪水”要求山体作为来源，城市不能与“融雪水”搭配。"}], "explanations": {"高山": "正确：高山是融雪水的来源，与“融雪水”相符。", "沙漠": "语义：沙漠少有积雪，不能提供融雪水，与句意冲突。", "海洋": "语义：海洋不是融雪水的来源，与“融雪水”冲突。", "城市": "搭配：“将……融雪水”要求山体作为来源，城市不能与“融雪水”搭配。"}, "sentence_index": 0, "correct_answer": "高山"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座高山有三十层，住满了人。", "explanation": "这里应该用〈高楼〉。楼房才按“层”计算，高山是自然形成的山，不能说有几层。"}, {"text": "他家门前有一条高山。", "explanation": "这里应该用〈座〉作量词。“条”多用于河流、道路，山应该用“座”。"}, {"text": "这片高山一望无际，适合种水稻。", "explanation": "这里应该用〈平原〉。平原才会一望无际、适合种水稻；高山地形高耸，不能这样描述。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76d5db9a-921f-428f-a956-053a32cada6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12809, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "高山", "is_correct": true, "explanation": "正确：高山上有花，符合句意。"}, {"text": "冰山", "is_correct": false, "explanation": "语义：冰山上寒冷、少有植物，不会有很多漂亮的花。"}, {"text": "大海", "is_correct": false, "explanation": "语义：大海里没有花，“大海上有很多漂亮的花”句意不成立。"}, {"text": "海底", "is_correct": false, "explanation": "搭配：“海底”后不能直接接“……上有很多花”，与“上”搭配不当。"}], "explanations": {"高山": "正确：高山上有花，符合句意。", "冰山": "语义：冰山上寒冷、少有植物，不会有很多漂亮的花。", "大海": "语义：大海里没有花，“大海上有很多漂亮的花”句意不成立。", "海底": "搭配：“海底”后不能直接接“……上有很多花”，与“上”搭配不当。"}, "sentence_index": 6, "correct_answer": "高山"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "高山涨潮的时候，海水会涌上沙滩。", "explanation": "这里应该用〈大海〉。只有海洋或大海才会涨潮，高山不会涨潮。"}, {"text": "这座高山只有一米高，小孩也能翻过去。", "explanation": "这里应该用〈矮墙〉。高山指很高的山峰，不能用来描述只有一米高的东西。"}, {"text": "这座高山清澈见底。", "explanation": "这里应该用〈湖泊〉。“清澈见底”用于水体，高山不是水，这样说不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76d5db9a-921f-428f-a956-053a32cada6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12809, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条高山很雄伟。", "corrected_sentence": "这座高山很雄伟。", "error_description": "「山」的量词应为「座」，不能用「条」。正确的说法是「这座高山很雄伟。」", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76d5db9a-921f-428f-a956-053a32cada6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12809, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们在上高山看到了云。", "corrected_sentence": "我们在高山看到了云。", "error_description": "方位词「上」不能放在「高山」之前，应删去「上」，改为「我们在高山看到了云。」", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76d5db9a-921f-428f-a956-053a32cada6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
