INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12812, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "将水通过管道或其他方式从一个地方运送到另一个地方。", "primary_collocate": null, "pronunciation": "shū shuǐ", "ipa": "ʂu˥ ʂweɪ˨˩", "syllable_count": 2, "sentences": [{"text": "这种地下输水结构不仅减少了蒸发损耗，还实现了水力的自然分配，其工程原理直至今日仍被水文专家视为低能耗水利技术的典范。", "target_word": "输水", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这条管道专门用来输水。", "target_word": "输水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们铺好管道，为村里输水。", "target_word": "输水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条大渠每天向城市输水。", "target_word": "输水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地下管道可以向农田输水。", "target_word": "输水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座水库向三个城市输水。", "target_word": "输水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老旧的管道漏了，输水很慢。", "target_word": "输水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条长渠从山里向平原输水。", "target_word": "输水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新泵站开始向村子输水了。", "target_word": "输水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天天旱，河道每天向农田输水。", "target_word": "输水", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "输水管", "label": "复合"}, {"form": "输水了", "label": "体标"}, {"form": "輸水", "label": "繁体"}], "register": "书面", "sense_fingerprint": "通过管道、渠道等把水从一处运送到另一处，工程与水利语境", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8873e8b-ebaa-461c-94d4-dce7b35fae3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12812, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "输水", "is_correct": true, "explanation": "输水（shū shuǐ）：通过管道或渠道把水送到别处。"}, {"text": "注水", "is_correct": false, "explanation": "zhù（第四声）与 shū（第一声）声母和声调都不同，意思是把水注入。"}, {"text": "需水", "is_correct": false, "explanation": "xū 与 shū 声母不同（x 与 sh），意思是需要水。"}, {"text": "失水", "is_correct": false, "explanation": "shī 与 shū 韵母不同（i 与 u），意思是失去水分。"}], "explanations": {"输水": "输水（shū shuǐ）：通过管道或渠道把水送到别处。", "注水": "zhù（第四声）与 shū（第一声）声母和声调都不同，意思是把水注入。", "需水": "xū 与 shū 声母不同（x 与 sh），意思是需要水。", "失水": "shī 与 shū 韵母不同（i 与 u），意思是失去水分。"}, "sentence_index": null, "correct_answer": "输水"}, "level_3": {"options": [{"text": "输水", "is_correct": true, "explanation": "正确：输水指通过管道或渠道输送水，与“水力的自然分配”的语境相符。"}, {"text": "输电", "is_correct": false, "explanation": "语义：输电指输送电能，与“蒸发损耗”“水力分配”的水利结构不符。"}, {"text": "抽水", "is_correct": false, "explanation": "搭配：“抽水”要靠动力提水，不能与“低能耗”“自然分配”同时成立。"}, {"text": "通风", "is_correct": false, "explanation": "语义：通风指空气流通，与“减少蒸发损耗”的水利语境无关。"}], "explanations": {"输水": "正确：输水指通过管道或渠道输送水，与“水力的自然分配”的语境相符。", "输电": "语义：输电指输送电能，与“蒸发损耗”“水力分配”的水利结构不符。", "抽水": "搭配：“抽水”要靠动力提水，不能与“低能耗”“自然分配”同时成立。", "通风": "语义：通风指空气流通，与“减少蒸发损耗”的水利语境无关。"}, "sentence_index": 0, "correct_answer": "输水"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这首歌每天向农田输水。", "explanation": "这里误把〈输水〉用于歌曲作主语；输水须靠管道、渠道等设施，歌曲不能输水。"}, {"text": "医生给病人输水。", "explanation": "这里应该用〈输液〉。给病人静脉注入液体要说输液，输水指用管道运送水。"}, {"text": "这幅画每天向村子输水。", "explanation": "这里误把〈输水〉用于画作主语；输水须靠管道、渠道等设施，画不能输水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76d5db9a-921f-428f-a956-053a32cada6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12812, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "输水", "is_correct": true, "explanation": "正确：“输水很慢”指输送水的速度慢，与老旧管道漏了的语境相符。"}, {"text": "供电", "is_correct": false, "explanation": "语义：管道漏了与供电无关，“供电很慢”的语境不通。"}, {"text": "施肥", "is_correct": false, "explanation": "语义：施肥指给土地加肥，与管道漏水、输送水的语境不符。"}, {"text": "通电", "is_correct": false, "explanation": "搭配：“通电”指瞬间接通电流，不说“很慢”。"}], "explanations": {"输水": "正确：“输水很慢”指输送水的速度慢，与老旧管道漏了的语境相符。", "供电": "语义：管道漏了与供电无关，“供电很慢”的语境不通。", "施肥": "语义：施肥指给土地加肥，与管道漏水、输送水的语境不符。", "通电": "搭配：“通电”指瞬间接通电流，不说“很慢”。"}, "sentence_index": 6, "correct_answer": "输水"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这把椅子每天向农田输水。", "explanation": "这里误把〈输水〉用于椅子作主语，把“输水”当成了器物自行送水的义项；输水的施事须是管道、渠道等输水设施，椅子不是。"}, {"text": "这台冰箱每天向农田输水。", "explanation": "这里误把〈输水〉用于冰箱作主语，把“输水”当成了器物自行送水的义项；输水的施事须是管道、渠道等输水设施，冰箱不是。"}, {"text": "他用扫把每天向农田输水。", "explanation": "这里误把〈输水〉用于扫把一类工具完成的动作；输水靠管道、渠道等设施大批量送水，扫把不能输水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76d5db9a-921f-428f-a956-053a32cada6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12812, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工人们村子输水。", "corrected_sentence": "工人们给村子输水。", "error_description": "错误：输水的受益对象前漏掉了介词“给”。正确：“给村子输水”，受益对象要用“给”或“向”引出。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76d5db9a-921f-428f-a956-053a32cada6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12812, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这套设施每天把郊区输水。", "corrected_sentence": "这套设施每天向郊区输水。", "error_description": "错误：输水的受益对象误用介词“把”引出。正确：“向郊区输水”，“把”字句不能用来引出输水的对象。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76d5db9a-921f-428f-a956-053a32cada6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
