INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12813, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "液体受热后表面分子脱离液体变成气体，通常指水变成水蒸气的过程。", "primary_collocate": null, "pronunciation": "zhēng fā", "ipa": "ʈʂɤŋ˥ fa˥", "syllable_count": 2, "sentences": [{"text": "这种地下输水结构不仅减少了蒸发损耗，还实现了水力的自然分配，其工程原理直至今日仍被水文专家视为低能耗水利技术的典范。", "target_word": "蒸发", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "锅里的水受热后慢慢蒸发。", "target_word": "蒸发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳一晒，湖水就会蒸发。", "target_word": "蒸发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水在高温下蒸发得很快。", "target_word": "蒸发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "酒精比水更容易蒸发。", "target_word": "蒸发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海水蒸发后，盐会留下来。", "target_word": "蒸发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把汤加热，里面的水会蒸发。", "target_word": "蒸发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水蒸发时会变成水蒸气。", "target_word": "蒸发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "加热以后，杯中的液体开始蒸发。", "target_word": "蒸发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "实验中，水需要加热才能蒸发。", "target_word": "蒸发", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "蒸发了", "label": "体标"}, {"form": "蒸发着", "label": "体标"}, {"form": "蒸发量", "label": "复合"}, {"form": "蒸發", "label": "繁体"}], "register": "中性", "sense_fingerprint": "液体受热变成气体的物理过程，科学说明语境", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8873e8b-ebaa-461c-94d4-dce7b35fae3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12813, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "蒸发", "is_correct": true, "explanation": "蒸发（zhēng fā）：液体受热变成气体。"}, {"text": "增发", "is_correct": false, "explanation": "zēng 与 zhēng 声母不同（z 与 zh），意思是增加发行。"}, {"text": "生发", "is_correct": false, "explanation": "shēng 与 zhēng 声母不同（sh 与 zh），意思是头发生长。"}, {"text": "政法", "is_correct": false, "explanation": "zhèng 与 zhēng 声调不同，fǎ 与 fā 声调也不同，意思是政治和法律。"}], "explanations": {"蒸发": "蒸发（zhēng fā）：液体受热变成气体。", "增发": "zēng 与 zhēng 声母不同（z 与 zh），意思是增加发行。", "生发": "shēng 与 zhēng 声母不同（sh 与 zh），意思是头发生长。", "政法": "zhèng 与 zhēng 声调不同，fǎ 与 fā 声调也不同，意思是政治和法律。"}, "sentence_index": null, "correct_answer": "蒸发"}, "level_3": {"options": [{"text": "蒸发", "is_correct": true, "explanation": "正确：“减少了蒸发损耗”指水受热变成气体造成的损耗，与水利语境相符。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：“游泳损耗”与水受热变成气体无关，语境不通。"}, {"text": "摄入", "is_correct": false, "explanation": "搭配：“摄入损耗”不搭配水的损耗，水不说被摄入而损耗。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：“唱歌损耗”与水利技术的语境毫不相关。"}], "explanations": {"蒸发": "正确：“减少了蒸发损耗”指水受热变成气体造成的损耗，与水利语境相符。", "游泳": "语义：“游泳损耗”与水受热变成气体无关，语境不通。", "摄入": "搭配：“摄入损耗”不搭配水的损耗，水不说被摄入而损耗。", "唱歌": "语义：“唱歌损耗”与水利技术的语境毫不相关。"}, "sentence_index": 0, "correct_answer": "蒸发"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "食盐放进热水里，很快就蒸发了。", "explanation": "这里应该用〈溶解〉。食盐是固体，溶于水要说溶解，蒸发只用于液体变成气体。"}, {"text": "这块石头在阳光下慢慢蒸发了。", "explanation": "这里应该用〈风化〉。石头是固体，蒸发只指液体变成气体；岩石受日晒风吹逐渐破碎要说风化。"}, {"text": "水蒸气遇冷会蒸发成水。", "explanation": "这里应该用〈凝结〉。水蒸气遇冷变回水要说凝结，蒸发是液体变成气体，方向正好相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76d5db9a-921f-428f-a956-053a32cada6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12813, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "蒸发", "is_correct": true, "explanation": "正确：“里面的水会蒸发”指加热后水变成气体，与“把汤加热”的语境相符。"}, {"text": "结冰", "is_correct": false, "explanation": "语义：汤被加热，水不会结冰，与加热的语境相矛盾。"}, {"text": "凝固", "is_correct": false, "explanation": "语义：加热后的汤里不会凝固，凝固与受热的语境相矛盾。"}, {"text": "结块", "is_correct": false, "explanation": "搭配：“结块”指粉末或固体凝聚成块，液态的水不说结块。"}], "explanations": {"蒸发": "正确：“里面的水会蒸发”指加热后水变成气体，与“把汤加热”的语境相符。", "结冰": "语义：汤被加热，水不会结冰，与加热的语境相矛盾。", "凝固": "语义：加热后的汤里不会凝固，凝固与受热的语境相矛盾。", "结块": "搭配：“结块”指粉末或固体凝聚成块，液态的水不说结块。"}, "sentence_index": 6, "correct_answer": "蒸发"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "蜡烛油冷却后很快蒸发了。", "explanation": "这里应该用〈凝固〉。蜡烛油冷却后由液体变成固体要说凝固，蒸发是液体变成气体。"}, {"text": "水在低温下蒸发成了冰。", "explanation": "结果错误：蒸发得到的是水蒸气，变成冰要说结冰，这里把结果说错了。"}, {"text": "这块金属在室温下很快就蒸发了。", "explanation": "这里误把〈蒸发〉用于固体金属，误当成“固体也会散去”的义项；蒸发只指液体受热变成气体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76d5db9a-921f-428f-a956-053a32cada6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12813, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雨停以后，地面的水慢慢把蒸发了。", "corrected_sentence": "雨停以后，地面的水慢慢蒸发了。", "error_description": "错误：“蒸发”是不及物动词，不能带“把”字结构。正确：去掉“把”，说“慢慢蒸发了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76d5db9a-921f-428f-a956-053a32cada6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12813, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "池子里的水一直在慢慢蒸发过。", "corrected_sentence": "池子里的水一直在慢慢蒸发着。", "error_description": "错误：表示持续状态要用“着”，“过”表示曾经经历，与“一直在”不搭配。正确：“蒸发着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76d5db9a-921f-428f-a956-053a32cada6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
