INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12825, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "按照某种标准或规则进行，表示遵循、依照。", "primary_collocate": null, "pronunciation": "yī xún", "ipa": "i˥ ɕyn˧˥", "syllable_count": 2, "sentences": [{"text": "水的分配通常由村落集体协商决定，依循季节、作物类型与土地面积进行动态调整，体现了高度制度化的资源管理逻辑。", "target_word": "依循", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "我们依循老师的办法做练习。", "target_word": "依循", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他依循既定的程序办理了手续。", "target_word": "依循", "complexity_tier": "T3", "furigana": "tā yī xún jì dìng de chéng xù bàn lǐ le shǒu xù", "sentence_source": "generated"}, {"text": "做事要依循规矩。", "target_word": "依循", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "大家依循顺序排队进去。", "target_word": "依循", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司依循法律办事。", "target_word": "依循", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她依循地图找到了那家店。", "target_word": "依循", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生依循病人的情况调整了药。", "target_word": "依循", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子应该依循家里的规矩。", "target_word": "依循", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次比赛依循去年的办法进行。", "target_word": "依循", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "依循了", "label": "体标"}, {"form": "依循着", "label": "体标"}, {"form": "依循过", "label": "体标"}], "register": "书面", "sense_fingerprint": "按照某种标准或规则进行，遵循、依照", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6f39da0-9e88-4222-8183-2237ea8e061c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXC